"""モン・サン=ミシェル検証シーン(P1)用の島モデルを、Blenderのbpy APIで組み立てて
glTFへ出力する、あるいはプレビュー画像をレンダリングするスクリプト。

Tools/generate_msm_proxy.py(手書きJSONでglTFを直接生成する版)の後継。岩(rock)は実物の
寸法(周囲約960m→平均半径153m、教会が載る台地の海抜約80m、自然の最高点の海抜92m)に基づく
非対称プロファイル(北側の修道院側は急峻、南側のカメラ側は緩やか)をbmeshで直接組み立てて
いる。城壁(rampart)は岩の西〜南〜東〜北東の裾を囲む弧状のジオメトリ(本体・天端の縁取り・
持ち出し帯・城門2箇所の切り抜き)として、塔は8基(円柱6基+ヴォーバン様式の角ばった稜堡2基)
として、いずれも岩の非対称な表面プロファイルに沿わせて配置している(詳細はRAMPART_*/WALL_*/
TOWER_*/GATE_*の各定数のコメントを参照。高さ・厚み・配置角度は出典なしの決め値)。集落(village)は
岩の南東側の扇形区画(VILLAGE_ARC_START_DEG〜VILLAGE_ARC_END_DEG)に、同心円状のテラス
(VILLAGE_TERRACE_*)を積んで、固定シードの擬似乱数で機械的すぎない配置にした家屋群。教会本体(church)・
ラ・メルヴェイユ(merveille)・鐘楼(belfry)・尖塔(spire)・像(statue)は、モン・サン=
ミシェルの実物の高さ内訳(fr.wikipedia)を海抜80mの修道院床から積み上げて配置している
(詳細はCHURCH_*/MERVEILLE_*/BELFRY_*/SPIRE_*/STATUE_*の各定数のコメントを参照)。
より複雑な形状への発展は今後の作業でこのスクリプトを拡張していく。

座標系・単位の約束はTools/generate_msm_proxy.pyと同じ: 1単位=1メートル、島の底面中心が
ワールド原点、Y-up(KurenaiEngineの座標系)。ただしBlender自体はZ-upのため、このスクリプト
内ではBlenderのネイティブ座標系(Z-up)でジオメトリを組み立て、glTFエクスポート時の
export_yup=True指定でBlender公式のio_scene_gltf2アドオンが自動的にY-upへ変換する
(BlenderのglTFエクスポータの標準的な軸変換規則: gltf_x=blender_x, gltf_y=blender_z,
gltf_z=-blender_y)。そのため、このスクリプトで組み立てる際の各パーツの高さは
Tools/generate_msm_proxy.pyの「y」の値をそのままBlenderの「z」座標として使えばよい。
水平方向の変換規則は blender_x=engine_x, blender_y=engine_z(Xは反転せず、Zは反転する)。
Zを反転するのは、KurenaiPackerがAssimpのaiProcess_ConvertToLeftHandedで取り込み時にZを
反転するため、それと打ち消し合わせるのが目的。符号を変えるときは
_engine_to_blenderのdocstringを必ず読むこと(過去に東西・南北の両方で取り違えている)。

このスクリプトはBlender本体から `blender --background --factory-startup --python
blender_msm_island.py -- <引数>` の形で呼び出す前提(直接 `python blender_msm_island.py`
では動かない。bpyはBlender本体に組み込まれたモジュールのため)。呼び出しは
Tools/run_blender.ps1 経由で行うことを想定している。

コマンドライン引数(Blenderは `--` より前の引数を自分で消費するため、`sys.argv` の
`--` より後ろだけを読む):
  --export <path>   : 指定パス(.gltfのフルパス)へglTFをエクスポートする
  --preview <dir>    : 指定ディレクトリへ main.png / main_mid.png / side.png / east.png /
                        north.png / top.png / aerial_sw.png / aerial_se.png /
                        aerial_ne.png / village_closeup.png / abbey_closeup.png /
                        veg_closeup.png の12枚をCyclesでレンダリングする
                        (ディレクトリが無ければ作成する)
  --compare <dir>    : 参考写真との突き合わせ用にCOMPARE_VIEWSの各ビューを
                        COMPARE_RESOLUTION_X/Yでレンダリングする(ディレクトリが
                        無ければ作成する。突き合わせ自体はTools/compare_reference.pyで行う)。
                        ビューごとに見た目版(<name>.png、青空+地面)とマスク版
                        (<name>_mask.png、マゼンタ背景+地面無し)の2枚を出力する
  --material-id      : 診断用。ベースカラーをMATERIAL_ID_PALETTEの識別しやすい12色へ
                        差し替え、テクスチャも接続せずに書き出す。実機のアルベド表示を
                        撮ると材質ごとの完全な地図が得られる(配置を写真と突き合わせるため)
複数同時に指定してもよい。いずれも指定しなかった場合は何もせず終了する。
"""

import math
import os
import random
import sys

import addon_utils
import bmesh
import bpy
from mathutils import Matrix, Vector

# Blenderを`--python <path>`で起動した場合、スクリプトのディレクトリがsys.pathへ自動で
# 追加されないことがある(実測で確認済み)ため、同じディレクトリにあるmsm_textures.pyを
# importできるよう明示的にsys.pathへ追加する
_SCRIPT_DIR = os.path.dirname(os.path.abspath(__file__))
if _SCRIPT_DIR not in sys.path:
    sys.path.insert(0, _SCRIPT_DIR)

import msm_textures

# --- マテリアル。参考写真(pexels1.jpg/aerial6.jpg/aerial11.jpg/aerial12.jpg/aerial13.jpg/
# village3.jpg/ramparts1.jpg)から採取したピクセル値の相対比(石は暗い灰褐色、集落の壁は
# やや明るい漆喰、屋根はスレートの暗い青灰色、尖塔はなまり葺きの緑がかった灰色、像は金泥)を
# 根拠に、物理的に妥当なアルベド域へ合わせた決め値。色はリニアRGB(Principled BSDFの
# Base Colorへそのまま入れる値)。並び順がMATERIAL_SLOTS(=glTFエクスポート後のマテリアル
# インデックス)を決めるため、既存のスロット順を変えたくなる場合でも末尾に追加すること ---
# 修正パス(レビュー): Rock/Masonry/VillageWallは当初中性的すぎる色だった(レンダの城壁
# sRGB(141,140,132)=リニア(0.265,0.261,0.229)、R:G:B=1:0.98:0.86でほぼ無彩色)。
# 参考写真の実測sRGB(149,135,110)=リニア(0.302,0.240,0.157)のR:G:B比1:0.79:0.52に
# 合わせた決め値へ差し替えた(実物の花崗岩は写真上でもはっきり暖色=黄土寄りのため)
# (名前, ベースカラー(リニアRGB), ラフネス, メタリック)
ISLAND_MATERIALS = [
    ("Rock",           (0.360, 0.295, 0.205), 0.92, 0.0),
    ("Masonry",        (0.320, 0.253, 0.166), 0.88, 0.0),
    ("VillageWall",    (0.270, 0.235, 0.185), 0.88, 0.0),
    ("VillagePlaster", (0.550, 0.500, 0.420), 0.85, 0.0),
    ("VillageTimber",  (0.130, 0.045, 0.030), 0.85, 0.0),
    ("SlateRoof",      (0.100, 0.100, 0.105), 0.55, 0.0),
    ("TileRoof",       (0.130, 0.100, 0.075), 0.70, 0.0),
    ("LeadRoof",       (0.085, 0.095, 0.095), 0.45, 0.0),
    ("Gilt",           (0.750, 0.550, 0.200), 0.30, 1.0),
    ("TreeCanopy",     (0.052, 0.070, 0.022), 0.90, 0.0),
    ("TreeTrunk",      (0.055, 0.040, 0.028), 0.95, 0.0),
    # 窓(ゴシック窓の開口部)。実物の窓は暗い開口部だが、当初は壁と同じMasonryのため
    # abbey_closeup.pngで壁より明るい縦縞に見えてしまっていた。既存のスロット順を
    # 変えないよう末尾に追加する決め値
    ("WindowGlass",    (0.020, 0.022, 0.028), 0.35, 0.0),
]
MATERIAL_SLOTS = {name: index for index, (name, _c, _r, _m) in enumerate(ISLAND_MATERIALS)}

# --- 材質IDモード(--material-id)。配置を測るための診断用の書き出し ---
# 見た目用のアルベドは Rock(0.360,0.295,0.205)/Masonry(0.320,0.253,0.166)/
# VillageWall(0.270,0.235,0.185) が互いに距離0.065、SlateRoofとLeadRoofに至っては0.018しか
# 離れておらず、テクスチャのむらがこの差を超える。そのままアルベド表示を色で分類すると
# 石積を集落の壁と取り違える(実際「集落の壁が画面高さ0.6に24%ある」という誤った値が出た)。
#
# --material-id を付けて書き出すと、ベースカラーを下のパレットへ差し替え、テクスチャも
# 接続しない。実機のPresent Mode 0(アルベド表示)はアルベドをそのまま出す(ガンマを
# 掛けない)ため、撮った画像を最近傍で当てるだけで材質ごとの完全な地図が得られる。
#
# パレットは互いのユークリッド距離が最小0.4になるよう選んだ(8bit量子化やガンマの有無に
# 影響されない余裕を取るための決め値)。ISLAND_MATERIALSと同じ並び順でなければならない
MATERIAL_ID_PALETTE = [
    (0.90, 0.10, 0.10),  # Rock            赤
    (0.10, 0.90, 0.10),  # Masonry         緑
    (0.10, 0.10, 0.90),  # VillageWall     青
    (0.90, 0.90, 0.10),  # VillagePlaster  黄
    (0.90, 0.10, 0.90),  # VillageTimber   マゼンタ
    (0.10, 0.90, 0.90),  # SlateRoof       シアン
    (0.90, 0.50, 0.10),  # TileRoof        橙
    (0.50, 0.10, 0.90),  # LeadRoof        紫
    (0.10, 0.50, 0.50),  # Gilt            暗い青緑
    (0.50, 0.90, 0.10),  # TreeCanopy      黄緑
    (0.50, 0.25, 0.10),  # TreeTrunk       茶
    (0.95, 0.95, 0.95),  # WindowGlass     白
]
# _create_island_materials()が読む。main()が--material-idを受け取ったときだけTrueになる
MATERIAL_ID_MODE = False

# --- タイルテクスチャ導入(手続き生成の変動場) ---
# マテリアルごとの「テクスチャ1タイルが何メートルに相当するか」。参考写真の石積みの段の
# 高さ(約0.3〜0.4m)、スレート1枚の丈(約0.2m)から逆算した出典なしの決め値。
# 表に無いマテリアル(Gilt/TreeTrunk/WindowGlass/VillageTimber)はテクスチャを貼らず、
# これまでどおり単色のままにする(VillageTimberはUVだけ作る)
#
# 修正パス(見た目の不合格を受けての作り直し): 初版の値(Rock 30m/Masonry 6m等)は、
# 実際のレンダ距離まで縮小すると細かい模様が平均へ潰れ、Cyclesのサンプリングノイズと
# 見分けが付かない「一様な粒状ノイズ」に見えていた。1タイル内に数メートル規模の
# 低周波のむら(msm_textures.weathering_field。風化・汚れ・苔・濡れを想定)を収める
# ために、タイルサイズを大きく取り直した。ワールド空間投影(_apply_box_projection_uv)
# なので、この低周波成分は建物ごとの色調の差にもなる
MATERIAL_UV_TILE_METERS = {
    "Rock":           45.0,
    "Masonry":        15.0,
    "VillageWall":    12.0,
    "VillagePlaster": 12.0,
    "VillageTimber":  12.0,
    "SlateRoof":       8.0,
    "TileRoof":        8.0,
    "LeadRoof":        8.0,
    "TreeCanopy":     12.0,
}

# --- 色相を振るマテリアル(2色を低周波のマスクで混ぜる) ---
# 【なぜ要るか】既存の変動場は「ベースカラーに掛けるスカラー」で明暗しか変えられない。
# 参考写真の樹林を測ると R/G の中央が0.831・p10〜p90の幅が0.291あり、日向の黄緑から
# 日陰の青緑まで色相が振れている(実機は中央0.692・幅0.172で、青すぎて幅も足りない)。
# TreeCanopyのベースカラーを暗い青緑側へ寄せ、明るい黄緑をもう一方の色として混ぜる。
# 2色の中間は (0.0625, 0.0775, 0.029) で R/G=0.806・B/G=0.374 になり、
# 実機の見た目の R/G を写真の0.831へ寄せる狙い(出典なしの決め値)
# 【値の詰め直し】材質IDで樹冠の画素を選んで最終画の色味を測ると R/G=0.690・B/G=1.033
# (写真は0.831/0.855)だった。同じやり方で石を測ると 花崗岩R/G 写真1.067対実機1.019・
# B/G 0.949対0.945、城壁 1.048対0.972 / 1.024対1.000 とよく合っているので、
# 照明が青いのではなく樹冠のアルベドだけが外れている。
# アルベドから実機の色味への倍率は実測で R/G×0.84・B/G×2.83(樹冠は青が小さいぶん
# 環境光の青が相対的に効く)。写真の値を割り戻すと、要るアルベドは R/G≒0.99・B/G≒0.28。
# 2色の混合(マスクの平均0.569)後がその値になるよう2色を決めた:
#   0.431×(0.052,0.070,0.022) + 0.569×(0.096,0.082,0.021) = (0.077,0.077,0.021)
# 【注意】この値は「写真の見た目に合わせて逆算した」もので、葉のアルベドの実測ではない
# 【中央値はもう合っている】材質IDで樹冠を選び、**写真と同じ緑判定**を
# 実機側にも掛けて測り直すと(写真の緑判定は影の葉を落とすため、材質IDで全部拾うと
# 片側だけ前処理が掛かった比較になる):
#              参考写真                    実機
#   R/G   中央0.789 幅(p10-p90)0.207   中央0.781 幅0.157
#   B/G   中央0.708 幅0.292            中央0.708 幅0.118
# 中央値はもう一致している(以前記録した「B/G 1.013対0.855」は旧太陽・黒の締め前の
# 測定で、しかも片側だけの前処理が入っていた)。残るのは色の幅。
# 【色の幅はアルベドでは広げられない — 試して撤回した】2色のB/Gが 0.314 と 0.256 で
# ほとんど差が無いのが原因と考え、日陰側を青緑(0.046,0.070,0.030)・日向側を黄緑
# (0.100,0.082,0.0154)へ離してアルベドのB/Gの幅を 0.058→0.241 と**4.2倍**にした。
# 混合後は(0.0767,0.0768,0.0217)で従来とほぼ同じ、つまり平均色は変えずに幅だけ広げた。
# 結果は **B/Gの幅 0.118→0.115 でまったく動かず**、中央値だけ 0.708→0.722 と外れた。
# 樹冠は青のアルベドが小さいぶん実機の青は環境光(空)がほぼ決めており、
# アルベドの青を振っても画面のBはほとんど変わらない(この倍率は上の B/G x2.83 と同じ話)。
# 幅を広げるなら光の側(空の色・環境光の当たり方)か、葉ごとの向きの分散で、
# アルベドではない。値は元へ戻した
MATERIAL_TINT_COLORS = {
    "TreeCanopy": (0.096, 0.082, 0.021),
}
MATERIAL_TINT_FIELDS = {
    "TreeCanopy": "canopy_tint",
}

# マテリアル名 -> msm_textures.FIELD_FUNCTIONS のキー、の対応表。ここに載っているマテリアルだけ
# _create_island_materials()でBase Colorへテクスチャノードを接続する
MATERIAL_TEXTURE_FIELDS = {
    "Rock":           "rock",
    "Masonry":        "masonry",
    "VillageWall":    "rubble",
    "VillagePlaster": "plaster",
    "SlateRoof":      "slate",
    "TileRoof":       "tile",
    "LeadRoof":       "lead",
    "TreeCanopy":     "canopy",
}

# --- 岩(実物の寸法に基づく非対称プロファイル。bmeshでリングを積んで直接組み立てる) ---
# 周囲約960m→平均半径≒153m(実測値からの概算。出典あり)
ROCK_BASE_RADIUS = 153.0
# 頂上台地の半径。かつては「高さ92mの円錐を80mで切ったときの半径 153*(1-80/92)≒20m」と
# いう幾何計算を根拠にしていたが、基準面の取り違えが判明して台地自体が頂上(92m)になり、
# この導出は成り立たなくなった(円錐を頂上で切れば半径は0になる。ROCK_PLATEAU_Zのコメント参照)。
# 実物の教会の床は自然の岩ではなく4つのクリプトが支える人工のプラットフォームなので、
# 20mは「岩の頂に人工的に造られた平場の広さ」を表す出典なしの決め値として据え置く。
# かつては45m(出典なしの決め値)としていたが、それでは教会・ラ・メルヴェイユの
# 足元の大半が台地の内側に収まってしまい、build_abbey_substructure()の垂直基礎構造が
# ほぼ全周で高さ0になってしまう不具合があった。実物の修道院の床は自然の岩ではなく人工的な
# プラットフォームで、「4つのクリプトが頂上の建物を支えるために造られ、岩の上に教会を
# 建てることを可能にした」(修道院公式サイト)という記述のとおり、狭い岩の頂から基礎構造
# (build_abbey_substructure)で外へ床を張り出して建物を載せる構成が正しいため20mへ縮小した
ROCK_PLATEAU_RADIUS = 20.0
ROCK_BASE_Z = 0.0
# 教会本体が載る台地(=岩の頂上)の高さ。このスクリプトのy=0は干潟の砂の面なので、
# 砂の平原を基準にした92mを使う。
#
# 【修正・基準面の取り違え】以前はROCK_PLATEAU_Z=80.0(公式サイトの「海抜約80m」)と
# ROCK_PEAK_Z=92.0(「海抜92m」)を同じ基準面の値として扱い、台地を80mに置いた上で
# 北側だけ92mまで盛り上げていた。しかしこの2つは基準面が違う:
#   海抜基準  (fr.wikipedia「Le Mont-Saint-Michel」):
#     教会の位置での岩の高さ 78.60m / 床から塔の天端まで 34.70m / 像の頂 157.10m
#   砂地基準  (同記事「cet îlot s'élève au-dessus d'une plaine sablonneuse à 92 mètres」,
#             「Abbaye du Mont-Saint-Michel」記事「plus de 170 mètres」):
#     岩の頂上 92m / 尖塔頂の像 170m
#   差はどちらも約13m (92-78.60=13.40, 170-157.10=12.90) で、この湾の干満差に相当する。
# 修道院公式サイトは「The abbey church is built at the top of the rock」と明記しており、
# 教会は岩の頂上そのものに建つ。したがって砂地基準では 台地=頂上=92m が正しく、
# 「80mの台地の上に12mの岩の峰が別にある」という以前の構成は誤りだった。
# この修正で高さの積み上げが 92 + 34.70 + 39.80 + 3.50 = 170.00 と出典どおり閉じる
# (BELFRY_TOP_Y / SPIRE_TOP_Y / STATUE_TOP_Y のコメント参照)。
ROCK_PLATEAU_Z = 92.0
ROCK_RING_SEGMENTS = 32  # 高さ方向の分割数(リング数はi=0〜32の33本。参考写真の起伏の細かさに
                          # 合わせて24→32へ増やした決め値)
ROCK_SIDES = 96           # 周方向の分割数(同上の理由で64→96へ増やした決め値)
# 断面の指数を角度(南北)によって変え、非対称な断面にする。値が小さいほど根元から急に
# 細くなり(急峻)、大きいほど根元付近の幅を保ってから頂上付近で急に細くなる(緩やか)
ROCK_NORTH_STEEP_EXPONENT = 0.5   # 北側(修道院側, +Z): 急峻(写真と整合しているため変更なし)
# 南側(カメラ側, -Z): 緩やか。修正パス(参考写真c_south_elevation_bluesky.jpg/
# c_south_elevation_sunny.jpgの精査)で、旧値2.2は「根元の幅を保ったまま頂上付近で
# 急に細くなる」形状のため中腹に幅30mもの裸の岩肌の"肩"ができ、修道院基礎(最外段でも
# 半径55〜60m程度)がその内側に浮いてしまっていた指摘を受け、円錐に近い1.25へ変更した。
# 実測(t=高さ割合, y=t*ROCK_PLATEAU_Z):
#   t=0.56(y=44.8m, 集落上端): 旧115.9m → 新88.6m
#   t=0.72(y=57.6m):           旧 88.4m → 新64.8m
#   t=0.85(y=68.0m):           旧 60.0m → 新44.5m
# 新しい値なら既存4段の修道院基礎(最外段半径55〜60m)が岩の縁までほぼ届く。参考写真の
# 島の輪郭が水際から修道院までほぼ直線的な三角形であることにも合わせた
#
# 修正パス(コーディネーター指摘、参考写真との並置から特定): 指数1.25でも中腹(t=0.5,
# 標高40m)での半径が97mあり、実物(同じ標高で半径40〜50m程度)の約2倍で、島全体が
# 円錐ではなく低いパンケーキ(平たく広い丘)に見えてしまっていた。指数が1より大きいと
# 中腹が(根元と比べて相対的に)膨らむため、指数を1未満の0.85へ変更し中腹を絞って
# 円錐に近づける。出典なしの決め値
ROCK_SOUTH_GENTLE_EXPONENT = 0.85
# 西側だけ指数を上乗せする量(_rock_profile_exponent参照)。南北の補間だけでは西が
# 必ず中間値(0.675)になり中腹が痩せる。0.25で西の指数は0.925になり、半径95mでの
# 岩の高さが28m→37m程度に上がる計算(スカイラインの残差の実測から逆算した値)。
# 【注意】1.0を大きく超える指数は中腹を膨らませて「平たいパンケーキ」に戻すので上げすぎない
# (過去にROCK_SOUTH_GENTLE_EXPONENTを1.25から0.85へ下げた経緯がある)
#
# 【測り直し】比較ツールの平滑化の非対称と北のカメラ方位を直したあと、この値も
# 振り直した(伸長0.15・軸-80度のもとで、3組):
#   値    south_low  south_mid  north_whole  3組平均
#   0.00   0.0251     0.0411     0.0418      0.0360
#   0.20   0.0215     0.0402     0.0384      0.0334
#   0.35   0.0216     0.0399     0.0361      0.0325   ← 据え置き
#   0.50   0.0226     0.0395     0.0343      0.0321
#   0.65   0.0241     0.0399     0.0358      0.0333
#   0.80   0.0264     0.0406     0.0344      0.0338
# 平均の最小は0.50だが、0.20〜0.65の谷は幅0.0013しかなく平坦で、0.35→0.50の改善
# (0.0004)は south_low(実機カメラに対応する主ビュー)の悪化(0.0010)より小さい。
# さらに0.50では西の指数が0.675+0.50=1.175と1を超え、上の注意どおり中腹が膨らむ。
# 谷の底のうち主ビューが最良で、かつ指数が円錐(≒1.0)に収まる0.35を据え置く。
ROCK_WEST_FULL_EXTRA = 0.35
# 西の効きを真西に集中させる指数。max(0,-cos)^N のN。
# N=2で試したとき南2組とne_lowは改善したが北2組が微悪化した(北西へ染み出すため。
# theta=135度でも重みが0.5残る)。Nを上げるとローブが狭まり真西へ集中する
ROCK_WEST_FULL_FALLOFF_POWER = 4.0

# --- 平面形の伸長(裾の半径を方位で変える) ---
# 実物は北西が急に落ち、南東側(集落と城壁)へ伸びた平面形をしている。
# 傍証: 出典の周囲960m・面積7haを楕円に当てはめると軸比およそ1.5:1になる
# (同じ周囲の円なら7.34haで、面積が4.6%不足する)。ただし出典の値が丸いので決定打ではない。
# そこで裾の半径に cos の項を足して伸長できるようにし、軸と振幅を振って測った。
# t=1(頂上台地)では効かないので、岩の頂上と修道院は原点のまま動かない
# (=修道院が相対的に伸長の反対側へ寄る)。
#
# 【重要・測り直した経緯】この定数を最初に入れたときの根拠は ne_low(北東の計測ビュー)の
# 尖塔位置のずれ0.118だけだった。その後、
#   - 比較ツールが参考写真側だけを平滑化していて尖塔が消えていたこと
#   - ne_lowの参考写真は尖塔が画面上端で切れていて指標に使えないこと
#   - 北の計測ビューのカメラが真北ではなく北から東へ35度の位置であること
# の3つが判明し、根拠が全部作り直しになった。直した指標(south_low / south_mid /
# north_whole の3組)で振幅を振り直した結果:
#   振幅  south_low  south_mid  north_whole  3組平均
#   0.00   0.0226     0.0385     0.0604      0.0405
#   0.05   0.0240     0.0394     0.0508      0.0381
#   0.10   0.0254     0.0379     0.0407      0.0347
#   0.15   0.0216     0.0399     0.0361      0.0325  ← 内部最適。採用
#   0.20   0.0355     0.0360     0.0407      0.0374
#   0.25   0.0441     0.0356     0.0504      0.0434
# 両側で悪化する谷型になり、しかも south_low(実機カメラに対応する主ビュー)と
# north_whole が**同じ0.15で最小**になる。以前は「平均が単調に改善し続けるので
# 主ビューを守れる0.10で止める」という消極的な選び方しかできなかったが、
# 今回は独立した2方位が同じ値を指しており、伸長そのものが本物だと言える。
#
# 【軸の決め方】当初は集落のある南東(-40度)を想定したが、それだと南から見た東西の
# 広がりを直接変えてしまい、south_lowが大きく悪化した(南のビューの横軸は東西なので
# 直撃する)。軸を南寄り(-80度)にすると、南のビューでは伸長が視線方向とほぼ平行に
# なるため横軸をほとんど変えず、一方で北東からは画面左が伸びて尖塔の相対位置が右へ動く。
# 振幅を0.15に決めたあと、軸も直した指標で振り直した(3組平均):
#   -110度 0.0381 / -95度 0.0338 / -80度 0.0325 / -65度 0.0384 / -50度 0.0476
# こちらも谷型で-80度が最小。当初の選び方は汚染された指標の上で行ったものだったが、
# 測り直しても同じ値になった。
ROCK_PLAN_ELONGATION = 0.15            # 0.0で真円。裾の半径への相対振幅
ROCK_PLAN_ELONGATION_AXIS_DEG = -80.0  # 伸ばす方位(ほぼ真南。上のコメント参照)

# 局所的に半径を削り、垂直に近い険しい崖に見せるためのガウシアン減衰項のパラメータ
# (_rock_profile_exponentによる南北非対称の指数プロファイルはそのままに、_rock_radiusの
# 計算結果へ複数のガウシアンの和を追加で減算する。出典なしの決め値)。
# リストの各要素は(中心角度deg, sigma(広がり)deg, 中心角度での最大削り込み量m):
#   - 北東(theta=80°): 参考写真aerial6.jpg/aerial11.jpg/aerial13.jpgで見られる島北東側の
#     切り立った崖。レビューでtop.pngのシルエットが不自然に潰れていると指摘されたため、
#     SIGMA=14.0→9.0で影響範囲をより局所的に、DEPTH=35.0→12.0で削り込み量を弱めた
#   - 西南西(theta=-150°): aerial12.jpg/c_aerial_sw_daylight.jpgで見られる、島西側の
#     露出した花崗岩の断崖。修正パス(参考写真c_aerial_sw_daylight.jpgの精査)で
#     DEPTH=13.0→20.0・SIGMA=12.0→10.0(より深く、より局所的に)へ強めた
ROCK_LOCAL_CARVES = [
    (80.0, 9.0, 12.0),
    (-150.0, 10.0, 20.0),
]
ROCK_LOCAL_CARVE_MIN_RADIUS = 20.0  # 削り込み後の半径の下限(自己交差・退化面を防ぐ安全弁。全崖共通)

# 岩肌のディテール(Displaceモディファイアで重ねる粗さ)。
# (名前, noise_scale, strength)。低周波(粗い)ほどnoise_scaleを大きく・strengthを大きく、
# 高周波(細かい)ほど両方小さくする(Tools/generate_tidal_flat.pyのオクターブ重ねと同じ考え方:
# 低周波を大きく、高周波を小さく)。出典なしの決め値で、見た目のディテール量を調整する目的。
# 参考写真で見られる岩肌の凹凸密度に近づけるため、最も粗い層のstrengthを1.5倍に強め、
# 既存の最細層(Fine)よりさらに細かいスケールの層(UltraFine)を追加して4層構成にした
ROCK_DETAIL_LAYERS = [
    ("RockDetailCoarse", 60.0, 12.0),
    ("RockDetailMid", 18.0, 3.0),
    ("RockDetailFine", 5.0, 1.0),
    ("RockDetailUltraFine", 1.5, 0.4),
]

# --- 城壁(rampart)と塔。実物の根拠は「8つの門・3つの通用門・3つの稜堡を持ち、巡回路が
# 集落の入口からTour Claudineまで、北の角、ラ・メルヴェイユの足元まで続く」
# 「監視塔7基+東のGabriel塔でほぼ円形、Tour Boucleだけ後世のヴォーバン様式で四角い」という
# 構成のみ(出典: mont-saint-michel-tours.com)。高さ・厚み・直径・正確な配置角度・弧の範囲・
# 塔の基数配分は出典が無く、以下はすべて決め値。承認済み計画にあった「狭間付き胸壁(Array)」は
# 可視性ルール(3m未満の特徴は600m先のカメラでは見えない)と矛盾するため作らない。個々の
# 狭間・出し狭間(マシクーリ)の切れ目ではなく、連続した1本の帯として表現する ---

# 壁が囲む弧(城壁本体・塔・城門専用の弧範囲。集落専用の弧範囲はVILLAGE_ARC_START_DEG/
# END_DEGを参照)。thetaが-195°→65°に反時計回りで増加する向きに260度分(西〜南〜東〜北東の裾を
# 集落ごと囲み、ラ・メルヴェイユの足元近くまで届かせる配置の決め値)。当初の目安は
# -195°〜75°だったが、_rock_local_carve(北・東寄りtheta≒80°付近を最大12mまで削るガウシアン、
# center=80°, sigma=9°)と重なるため、endを75°→65°へ後退させて調整した(delta=15°地点の
# ガウシアン値exp(-(15/9)^2/2)≒0.25で削り込み量は最大12mの約25%≒3m程度に抑えられる。
# 75°のままだとdelta=5°でガウシアン値≒0.86、削り込み量が約10mに達し崖の中心付近を
# 壁がそのまま横切ってしまうため採用しなかった)。ステップ2で実装したbuild_rockの非対称
# プロファイル(_rock_radius)に沿わせるため、thetaの定義(atan2(z,x)、+Zが北)は
# build_rockと共通のものを使う
RAMPART_ARC_START_DEG = -195.0
RAMPART_ARC_END_DEG = 65.0
RAMPART_ARC_SEGMENTS = 70  # 弧の分割数(出典なしの決め値。260度分をWALL_ARC_SEGMENTS=48だった
                           # 180度分と同程度の解像度(3.75度/分割)で保つよう70に増やした)

# 壁の基準高さ: 岩のプロファイル関数_rock_radius(t, theta)のt=0.06(非頂上リングの高さは
# theta非依存でt*ROCK_PLATEAU_Z=0.06*80=4.8mになる。build_rock参照)。
# 修正パス: 岩の断面指数(ROCK_SOUTH_GENTLE_EXPONENT)を2.2→1.25にしたことで、同じ
# t=0.15でも南側の半径が151m→140.6mまで内側に寄ってしまい、城壁の外側に幅10m以上の
# 裸の岩の"縁"ができてしまっていた。指数1.25では0.06^1.25≒0.0334→半径=153-133*0.0334
# ≒148.6m、WALL_OUTWARD_OFFSET=3.0を足すと約151.6mとなり、岩の基部153mのすぐ内側に
# 戻るためWALL_REF_Tを0.15→0.06へ変更した
#
# 修正パス(コーディネーター指摘、参考写真との並置から特定): ROCK_SOUTH_GENTLE_EXPONENTを
# 1.25→0.85へ変更(円錐化)した副作用で、同じt=0.06でも南側の半径が148.6m→約140.8mまで
# 内側に寄り、城壁の外側に幅9m超の裸の岩の縁ができてしまった。t=0.01では
# _rock_radius(0.01,-90°)=153-133*0.01**0.85≒150.3m、WALL_OUTWARD_OFFSET=3.0を足すと
# 約153.3mとなり岩の裾(t=0での153.0m)をわずかに上回るため、裸の縁がほぼ消える。
# 出典なしの決め値
WALL_REF_T = 0.01
WALL_BASE_Z_REF = WALL_REF_T * ROCK_PLATEAU_Z  # =4.8m

WALL_OUTWARD_OFFSET = 3.0   # 岩の表面から壁の基準線までの張り出し量
WALL_THICKNESS = 3.0        # Solidifyモディファイアで付与する厚み

# 壁の高さに緩急を持たせる(参考写真ramparts1.jpgで見られる、区間ごとに高さが変わる壁の
# 表情を再現する目的の決め値)。RAMPART_ARC_SEGMENTS個の頂点ごとにではなく、弧を
# WALL_HEIGHT_SEGMENTS個の粗い区間に分け、区間境界に固定シードの擬似乱数で高さを割り当てて
# 区間内は線形補間する(急激な段差を避けるため)
# 【修正・城壁が画面上で写真の約1.8倍の高さだった】材質IDレンダで城壁の天端を列ごとに
# 測ると画面の正規化高さ h=0.085〜0.134(中央0.097)。参考写真に正規化格子を描いて
# 胸壁の上端を読むと h=0.05〜0.06(photo_curve_zoom.pngで描き戻して検証済み)。
# 換算表(scratchpad/ht_table.py)では裾で地表+15mがh=0.117なので、h=0.06は地表+約7m。
# 壁の基準面はWALL_BASE_Z_REF=0.92mなので、壁自体の高さは約6m。
# 旧値(8〜16m、天端8.9〜16.9m)は2倍近く高く、家並みの下半分を隠していた
WALL_HEIGHT_MIN = 4.5
WALL_HEIGHT_MAX = 8.0
WALL_HEIGHT_SEGMENTS = 8
WALL_HEIGHT_SEED = 20260803  # VILLAGE_SEEDとは独立させた専用シード

# 天端の縁取り(パラペット)。下半分は連続した帯、上半分は狭間(WALL_MERLON_*)に分ける
WALL_TOP_LEDGE_HEIGHT = 0.6

# --- 狭間(クレネル)。パラペットの上に、隙間をあけて並べる四角い歯 ---
# 【なぜ要るか】城壁の帯(島の正規化高さ h0.00〜0.12)は、参考写真との局所コントラストの
# 差がいちばん大きい場所だった(x×hの格子で上位10セルのうち6つ)。幾何の無い平らな面だけを
# 切り出すと 参考写真0.378 / 実機0.176 で、法線マップを入れてもまだ半分以下。
# 城壁の目地は既に法線の傾きの上限(60度)で2割が頭打ちになっており、テクスチャ側は天井。
# ここから先はジオメトリで、参考写真(photo_rampart.png、島の幅で5倍に拡大)を見ると
# 天端沿いに走る歯状の暗い帯と、その上の明るいパラペットが最も目を引く。
#
# 寸法は出典なしの決め値だが、根拠の軸は「実機の内部解像度で分離して見えること」:
# 内部1280幅で島の実効幅は約516画素、城壁のあたりは約1.72画素/m。
# 鐘楼のアーチ(幅1.25m=約2.2画素)は実際に分離して見えたので、それを下限の目安にする。
# 歯2.4m・隙間1.4m(周期3.8m=約6.5画素)なら隙間も約2.4画素あり確実に残る。
# 実物のクレネルはもっと細かいが、この距離では周期が細かいほど平均へ潰れて逆効果になる
WALL_MERLON_WIDTH = 2.4        # 弧に沿った歯の幅
WALL_MERLON_GAP = 1.4          # 歯と歯のあいだ(ここが空になって暗く見える)
WALL_MERLON_HEIGHT = 0.9       # パラペットの天端からさらに立ち上がる高さ

# 持ち出し帯(マシクーリの簡略化)。個々の切れ目は作らず、連続した帯1本にする。
# 【大きさを見直した】旧値(出っ張り0.6m・高さ0.8m)は内部解像度で約1画素しかなく、
# 高倍率で並べても実機側には暗い帯がまったく出ていなかった(eng_rampart.png)。
# 参考写真ではこの帯が城壁でいちばん強い線で、持ち出しの下に落ちる影が黒く見えている。
#
# 【ずっと壁の中に埋まっていた】OUTWARD_OFFSETは**基準線からの距離**で、壁は
# WALL_THICKNESS=3.0をSolidifyのoffset=0(中心振り分け)で付けているため、壁の外面は
# 基準線+1.5mにある。帯の厚みはMACHICOLATION_THICKNESS=1.0なので、
#   旧値0.6 → 帯は +0.1〜+1.1m で**完全に壁の内側**(1mmも外に出ていない)
#   1.2にしても +0.7〜+1.7m で、壁面から出るのは0.2mだけ
# 城壁を横切る行ごとの明るさを測ると、参考写真が0.50〜1.00と2倍振れるのに対し
# 実機は0.83〜1.00でほぼ平坦だった(影がまったく落ちていない)。
# 壁面から1.2m持ち出すには 1.5 + 1.2 - 0.5 = 2.2 が要る。
# 太陽の仰角15度なので、1.2mの持ち出しは壁面へ 1.2/tan(15度) = 4.5m の影を落とす
MACHICOLATION_HEIGHT = 1.4
MACHICOLATION_OUTWARD_OFFSET = 2.2
MACHICOLATION_BELOW_TOP_OFFSET = 2.0  # 天端からの下げ量
MACHICOLATION_THICKNESS = 1.0  # 計画では「薄い帯」とだけ指定(数値は出典なしの決め値)

# 塔(8基)。名前は史実の塔の名前(fr.wikipedia)を配列順に割り当てただけで、実際の史実の
# 配置順とは対応していない識別用のラベル。実物は「監視塔7基+東のGabriel塔でほぼ円形、
# Tour Boucleだけヴォーバン様式で四角い」という構成のため、円柱6基+四角い稜堡2基
# (TOWER_SQUARE_INDICESで指定)にする(実物は角ばった塔1基のみだが、参考写真
# aerial13.jpg/ramparts1.jpgで見られる稜堡らしい表情を増やす目的で決め値として2基にした)
# 修正パス(コーディネーター指摘、参考写真との並置から特定): 定数のコメント自身が「実物は
# 角ばった塔1基のみ」と認めており、参考写真でも角ばって見えるのは1基だけだったため、
# 実物どおりTour Boucle(インデックス4)の1基のみへ戻した
TOWER_NAMES = [
    "Tour du Roy",
    "Tour de l'Arcade",
    "Tour Cholet",
    "Tour Gabriel",
    "Tour Boucle",
    "Tour Béatrix",
    "Tour Nord",
    "Tour Claudine",
]
# 半径・高さは固定シードの擬似乱数で塔ごとに振る(実物も塔ごとに規模が異なるため、単一の
# 決め値より自然に見える目的)
# 修正パス(コーディネーター指摘、参考写真との並置から特定): 塔が「壁の上に載った淡い色の
# 板状の柱」に見えていた。参考写真(c_aerial_se_goldenhour/ramparts1/ramparts2)では塔が
# 壁からはっきり外へ張り出しているため、半径を5.0〜8.0→6.0〜10.0へ拡大した。出典なしの決め値
# 修正パス(ユーザー指摘「城壁の塔に屋根なんてない」を受けた参考写真の再確認): 上記2回の
# 調整はどちらも「塔に円錐屋根がある」という誤った前提の上で行っていた。
# c_aerial_se_goldenhour.jpgを確認したところ、城壁の塔は屋根の無い平らな砲座で、
# 上端が刳形で外へ張り出し狭間付きの胸壁が回る形をしている(15世紀の対砲撃用の塔で、
# 上に大砲を据えるため天面が平らなのが本来の形)。円錐屋根が付いているのは修道院側の
# 小さな階段小塔だけで、城壁の塔には1基も無い。
# 実物の塔は壁の上に数メートル出るだけの太く低いドラムで、写真から島の幅300mを基準に
# 実測すると直径は16m前後。半径を4.5〜6.5→7.0〜9.0(直径14〜18m)とする。出典なしの決め値
TOWER_RADIUS_MIN = 7.0
TOWER_RADIUS_MAX = 9.0
# 塔の高さは城壁の高さに追従させる。実物の塔は壁の上に数メートル出るだけなので、
# 壁と無関係な絶対値(旧TOWER_HEIGHT_MIN/MAX)で決めると比率が崩れる。
# 本体の天端が壁の天端よりどれだけ高いかで指定する(出典なしの決め値)
# 修正パス(参考写真c_aerial_se_goldenhour.jpgとの並置): 3.0〜6.0では塔が壁から突き出しすぎて
# 杭のように見えた。写真の塔は壁の上に1〜3m出る程度で、壁の狭間の線とほぼ一続きに見える
TOWER_ABOVE_WALL_MIN = 1.5
TOWER_ABOVE_WALL_MAX = 3.5
TOWER_SEED = 20260804  # VILLAGE_SEED/WALL_HEIGHT_SEEDとは独立させた専用シード
# 8基中どのインデックス(0始まり、TOWER_NAMESの並び順)を四角い稜堡にするかの決め値。
# 修正パス(コーディネーター指摘、参考写真との並置から特定): 「実物は角ばった塔1基のみ」
# という上のコメントの記述どおり、参考写真でも角ばって見えるのは1基だけだったため、
# {4, 6}の2基から{4}(Tour Boucleのみ)の1基へ戻した。出典なしの決め値
TOWER_SQUARE_INDICES = {4}
# 修正パス(コーディネーター指摘、参考写真との並置から特定): 壁の基準線よりさらに外側への
# 張り出しを2.0→5.0へ拡大し、塔が壁から明確に張り出して見えるようにした。出典なしの決め値
# 修正パス(コーディネーター指摘、比率の是正): 5.0では壁から切り離れて見えたため、
# 張り出しは残しつつ3.0へ戻した。出典なしの決め値
TOWER_OUTWARD_OFFSET = 3.0
# 塔の天端の胸壁(パラペット)。実物の塔は天面が平らな砲座で、縁が刳形で外へ張り出し
# 狭間付きの胸壁が回る。個々の狭間は600m先では見えないため、本体より一回り太い帯として
# 表現する。この帯が天端に濃い影の線を作り、塔が立体として読める主因になっている。
# 修正パス: 当初は中身の詰まった円柱にしたが、それでは天面が明るい円盤になって塔が
# 「杭」に見えた。実物の天面は開いた砲座なので、床と環状の胸壁を別に組み、
# 胸壁の内側に影の落ちる窪みを作る(_add_tower_parapet_to_bmesh)。
# TOWER_PARAPET_INNER_INSETは胸壁の内面を塔本体の側面よりどれだけ内側へ寄せるかで、
# 外側の張り出しと合わせて胸壁の厚みになる。厚み1.5mでは開口が大きすぎて「茶碗」に
# 見えたため、実物の対砲撃用の分厚い胸壁に合わせて0.9+2.5=3.4mとした(出典なしの決め値)
# 修正パス(参考写真との並置): 高さ2.2m・開口を絞った形では内側に影が溜まり、
# 塔が「暗いドーナツ」に見えた。写真の塔の天面は日が当たって明るい丸い膨らみに見えるため、
# 胸壁を胸の高さ相当(1.5m)まで下げ、開口も広げて床に光が入るようにする
TOWER_PARAPET_EXTRA_RADIUS = 0.9
TOWER_PARAPET_INNER_INSET = 1.8
TOWER_PARAPET_HEIGHT = 1.5
TOWER_SIDES = 32

# 城門(Porte de l'Avancée付近に相当する位置の決め値)。theta=-90度(真南)に矩形の開口を
# Booleanで1つ抜く。個々の狭間と違い、シルエットに影響する大きさのため可視性ルールに反しない
GATE_THETA_DEG = -90.0
GATE_WIDTH = 6.0
GATE_HEIGHT = 8.0
# カッターの下端を壁本体のz_bottom(WALL_BASE_Z_REF)よりこの分だけ下まで延ばす(出典なしの
# マージン)。_cut_gateのdocstring参照: 同一平面での交差はBooleanが穴を開けきれない不具合の
# 原因になるため
GATE_BOTTOM_MARGIN = 1.0

# 副次的な通用門(実物の「3つの通用門」のうちの1つに相当する位置づけの決め値)。南東寄りの
# theta=-30度に、主門よりひとまわり小さい開口を追加する
GATE2_THETA_DEG = -30.0
GATE2_WIDTH = 4.0
GATE2_HEIGHT = 6.0

# --- 集落(グランド・リュ)。中世の人口300〜400人(出典: fr.wikipedia)から、1棟あたり
# 複数人〜1世帯として数十棟程度の規模にしたという以外に根拠は無く、具体的な棟数・寸法・道の
# 正確な経路は出典なしの決め値。固定シードからPython標準randomモジュールで決定論的な擬似
# 乱数を作り、位置・寸法を機械的すぎないよう振る(Tools/generate_tidal_flat.pyと同じ考え方) ---
# 実物は指定建造物だけで約60棟が隙間なく密着している(出典: French Moments)。参考写真
# pexels1.jpg/aerial11.jpg/aerial13.jpgでも家々が密集して城壁の内側を埋め尽くしている
# ように見える。top.pngで集落が薄い帯にしか見えず「南面をびっしり埋める大きな塊」という
# 実物の印象に届いていないとの指摘を受け、100→130棟へ増やした(出典なしの決め値)。
#
# 当初は理想螺旋(城壁の弧を折り返しながら登る方式)だったが、岩を周回してしまい
# 「集落が南東の扇形の一区画に収まる」実物の配置と合わず、s=1.0付近で接線ベクトルが
# 縮退する不具合もあったため、教会が東西軸へ組み替わったのに合わせて廃止し、
# 同心円状のテラス(段)に家を並べる方式に置き換えた(VILLAGE_TERRACE_*参照)。
# 修正パス(タスクC): 「段の角度幅÷棟数」で等角度配置していた旧方式は、家の幅
# (VILLAGE_WIDTH_MIN/MAX)が間隔計算に一切使われず隙間と重なりが成り行きになり、
# 遠目に「並んだ立方体」に見える不具合があった。等角度配置をやめ、弧長に沿って家の幅
# ぶんずつ詰めて置く方式(build_village()参照)へ置き換えたため、棟数は結果として決まる
# ようになり、VILLAGE_HOUSE_COUNT(旧: 段ごとの目標棟数を決めていた定数)は不要になった
VILLAGE_SEED = 20260802

# 集落は岩の南東側の扇形区画に、同心円状のテラス(段)を積んで配置する(出典なしの決め値)。
# VILLAGE_ARC_START_DEG〜VILLAGE_ARC_END_DEGの角度範囲・VILLAGE_TERRACE_HEIGHT_T_START〜
# ENDの高さ範囲をVILLAGE_TERRACE_COUNT段に分割し、各段の中で角度方向に家を並べる。
# 集落を厚く見せるため段数を6→8へ増やし、上限も0.50→0.56へ引き上げた(密な植生帯の下限
# 0.50と少し重なるが、実物でも家と木は混在しているため問題ない)。
# 修正パス(コーディネーター指摘): 並置画像se_high__c_aerial_se_goldenhour__side_by_side.pngを
# 見比べると、参考写真では集落が右下の低い一区画にまとまり、その上に緑と段々の庭園の帯が
# はっきり見えるのに対し、モデルは屋根が斜面の上のほうまで広がり集落と修道院の間に緑の帯が
# 無く「屋根で葺かれたドーム」に見えていた。上限を0.56→0.44へ引き下げ、集落の上端を下げて
# VEGETATION_CLUSTER_HEIGHT_T_MAX(0.66)との間に0.44〜0.66の緑の帯ができるようにした
# (段数VILLAGE_TERRACE_COUNTは変えない。段の間隔が詰まるだけで、弧長パッキング方式のため
# 棟数は自動的に調整される)
# 修正パス(コーディネーター指摘、参考写真との並置から特定): 集落上端〜修道院基礎の間が
# のっぺりした裸の円錐に見える問題への対応の一部として、集落をSLOPE_TERRACE_HEIGHT_TSの
# 最下段(0.52)と噛み合うよう1段分だけ上へ伸ばす。段数8→10、上限0.50→0.56。家と擁壁が
# 多少重なっても実物もそうなっているため問題ない。出典なしの決め値
# 修正パス(コーディネーター指摘、副作用の是正): 上の拡張で集落が膨らみすぎ、島の下半分を
# 丸ごと覆って擁壁の中腹を飲み込んでしまった(「城壁/集落/擁壁と庭と樹木/修道院」の
# 4層構造が「城壁/集落/修道院」の3層に潰れていた)。段数を8へ戻し、集落を島の高さの
# 4割までの帯に留めてその上を擁壁・庭・樹木の層へ譲る。参考写真の4層構造に合わせた
# 出典なしの決め値
# 【修正・集落が斜面の下半分を埋める山になっていた】参考写真c_south_elevation_hazy.jpgと
# 並べると、実物の集落は城壁の上に載る2〜3棟ぶんの浅い帯で、その上はすぐ岩と樹木になる。
# 旧値(8段・t=0.04〜0.44)では199棟が斜面の下半分を埋め尽くし、「屋根の絨毯」に見えていた。
# この関数のdocstringにあるとおり実物は指定建造物で約60棟(出典: French Moments)なので、
# 199棟は3倍以上多い。段数8→5、範囲もt=0.06〜0.36へ狭めて帯を浅くする(出典なしの決め値)
# 【修正・集落が斜面の1/3まで登っていた】材質IDレンダで屋根の上端を列ごとに測り、
# 参考写真c_south_elevation_sunny.jpgに正規化格子を描いて読んだ値と並べると:
#   正規化x     0.40-0.55  0.55-0.60  0.60-0.65  0.65-0.80  0.80-0.95  0.95-1.00
#   写真の屋根   0.15-0.16  0.22       0.24       0.16-0.19  0.11-0.14  0.09
#   実機の屋根   0.33-0.36  0.33       0.34       0.27-0.34  0.13-0.23  なし
# t=0.36の地表に棟15mを足すと画面高さh=0.34(scratchpad/ht_table.py)で、実測のp90=0.341と
# 一致する。家は段の高さちょうどに建つので、樹木と違って換算表をそのまま使ってよい。
# 写真の中央値0.16と最大0.24のあいだを取ってh=0.20を狙うと t≒0.125。
# 段数も減らす: t=0.024〜0.125は岩の半径で約170m→150mの20mの帯で、家の奥行き(6〜12m)を
# 考えると3列でいっぱい。5段のままだと段が2mおきになり家が完全に重なる
#
# 【修正・下げすぎた結果、中央だけ登り足りなくなった】上の修正は「一律に高すぎる」状態を
# 直したもので、x方向の形までは合わせていなかった。屋根の上端を測り直すと:
#   正規化x     0.40-0.45  0.45-0.55  0.55-0.60  0.60-0.65  0.65-0.80  0.80-0.95
#   写真         0.150      0.160      0.220      0.240      0.16-0.19  0.11-0.14
#   実機         0.101      0.117      0.137      0.199      0.162      0.14-0.16
# **東側(x0.65以降)はもう合っていて、足りないのは中央(x0.40〜0.65)だけ**。
# 一律に上げると東が写真を超えるので、上端と一緒に「上の段ほど西へ寄る」ようにする
# (VILLAGE_TERRACE_CENTER_SHIFT_DEG)。実物のグランド・リュも、下は南東の王の門から
# 始まり、登るほど西の修道院の階段へ寄っていく。
# 目標は写真の最大 h=0.240(x0.60-0.65)。壁を低くしたので棟の高さは平均10.75mで、
# t=0.125の地表h=0.081に対し実測の屋根の上端が0.199 ——つまり棟が0.118ぶん持ち上げる。
# h=0.240 には地表h=0.122、ht_table.pyの逆引きで t≒0.185。
# 段数は radius が t=0.024で約169m・t=0.185で約139mの30mの帯になるので、
# 家の奥行き7〜11mに対し4列(段の間隔10m)がちょうど収まる
VILLAGE_TERRACE_COUNT = 4
# 【修正・西側斜面のシルエットが低かった】スカイラインの重ね合わせ(south_low/south_mid)で、
# 画像左(西)だけ緑(モデル)が赤(写真)より系統的に低い残差が残っていた。
# 参考写真c_south_elevation_hazy.jpgの西端を拡大すると、実物は城壁の上に建物が西端まで
# 連続しているのに対し、モデルはこの区間が樹木だけだった。屋根(城壁の上15〜25m)と
# 樹木(8〜14m)の高さの差が、そのまま残差になっていた。
# 集落の弧を西南西(-120度)から-150度まで広げて建物を届かせる。
# 城壁の弧(RAMPART_ARC_START_DEG=-195)の内側なので、城壁の無い区間へは出ない
# 【修正・写真では家が無い区間を家で埋めていた】参考写真の正規化x0.15〜0.40は、下から
# 順に「城壁 → 露出した花崗岩の崖 → 樹木 → 修道院の基礎」で、家が1軒も無い。
# 実機はこの区間に屋根の上端が0.21〜0.35で並んでいた。
# 方位thetaと画面のxの対応(scratchpad/ht_table.py --sweep)は
#   theta=-150度→x=0.137  -120度→x=0.211  -110度→x=0.288  -100度→x=0.379  -90度→x=0.479
# なので、開始を-100度にすると家はx=0.38から東だけになり、写真と揃う。
# 過去のパスがここを-120→-150へ広げたのは「西のスカイラインが低い」ためだったが、
# 実物のその区間は岩と樹木で、家で埋めるのは誤りだった(写真優先の判断により、
# skyline_rmsが悪化しても採る)。写真の西端(x0.00〜0.15)の建物群は、この集落ではなく
# 別に建てているガブリエル塔と棟(WEST_END_TOWER_*/WEST_END_LODGE_*)が担う
VILLAGE_ARC_START_DEG = -100.0
VILLAGE_ARC_END_DEG = 0.0
# 修正パス(コーディネーター指摘、段階2: 岩を細くした段階1に合わせて集落を斜面へ沿わせる):
# 岩が細くなった分、城壁とのすき間を詰めるため下端を0.16→0.10へ下げ、急斜面になった分
# 同じ半径差でもより高くまで登れるよう上端を0.44→0.50へ引き上げた。出典なしの決め値
# 修正パス(コーディネーター指摘、参考写真との並置から特定): t=0.10での岩の半径(約134m)と
# 城壁の半径(約153m)の間に幅19mの裸の岩の帯が残っていた。参考写真では家が城壁のすぐ
# 内側まで詰まっているため、下端をさらに0.10→0.04へ下げた。出典なしの決め値
# 【修正・城壁と家並みのあいだに裸地の帯が残っていた】参考写真c_aerial_se_goldenhour.jpgでは
# 家が城壁の内側の面から直に立ち上がり、あいだに裸地は一切無い。旧値0.06では最下段の
# 基準半径が140.8mで、城壁の基準線153.4mとのあいだに幅約12.6mの裸の帯ができていた。
# 家の半径方向の奥行き(VILLAGE_DEPTH_MIN/MAX=6〜12m)の半分を見込むと、外縁が城壁に
# 届く基準半径は約147.5m。_rock_radius(t, -90度)=147.5 を解くと t≒0.024
VILLAGE_TERRACE_HEIGHT_T_START = 0.024  # 最下段(城壁の内側の面に接する)
VILLAGE_TERRACE_HEIGHT_T_END = 0.21     # 最上段(VILLAGE_TERRACE_COUNTのコメント参照)
# 上の段ほど弧の中心を西へずらす量(度)。最下段で0、最上段でこの値。
# 【なぜ要るか】_village_terrace_arc は上の段ほど角度範囲を絞る(span_factor 1.0→0.5)が、
# 中心を全段共通にしていたため、上の段は弧の中心(-50度=南東)の周りにしか残らなかった。
# 画面のxとの対応は theta=-100度→x=0.379 / -90度→0.479 / -50度→0.82 なので、
# 中心-50度・半幅25度の最上段は x=0.38〜0.82 に届かず、**中央が登れない**。
# 最上段の中心を-75度へ寄せると西端がちょうど VILLAGE_ARC_START_DEG(-100度)に一致し、
# 中央(x0.38〜0.65)が上の段を持つ。東(x>0.82)は下の段だけが担うので今の高さのまま
VILLAGE_TERRACE_CENTER_SHIFT_DEG = -25.0
# 最上段が持つ角度幅(全幅に対する比)。最下段は1.0で、上の段ほどこの値へ線形に絞る。
# 【0.5では広すぎた】中心を西へずらしただけで幅を0.5のままにすると、最上段が
# theta=-100〜-50度(x=0.38〜0.82)を丸ごと覆い、写真では家が1軒も無い x0.15〜0.40 まで
# 家が伸びたうえ、もう合っていた東(x0.70〜0.80)を 0.162 → 0.218 と押し上げてしまった。
# 写真で家がいちばん高く登るのは x0.55〜0.65 の狭い窓(h=0.22〜0.24)だけで、
# 対応する方位は theta=-84〜-66度。全幅100度に対し半幅9度=比0.18なので0.15を採る。
# 値は scratchpad/fit_terraces.py で、射影だけを使って(段数, 上端t, ずらし, この幅)を
# 総当たりし、写真の手読みカーブとの平均絶対差が最小になる組を選んだもの
VILLAGE_TERRACE_SPAN_TOP = 0.15

# 各段内の角度方向の位置ジッター(機械的すぎない配置にするための決め値)。
# 修正パス(タスクC): 弧長に沿って家の幅ぶんずつ詰めて置く方式にしたため、ジッターは
# 隣接する家どうしの接触を壊してしまう(隙間や埋め込みが生じる)。0.0にして無効化した
VILLAGE_THETA_JITTER_DEG = 0.0

# 家の向き(水平面内のヨー角)にランダムなずれを加える範囲(度)。修正パス(コーディネーター
# 指摘、段階2): 各家が接線方向を向いて等間隔に並ぶだけだと屋根が同心円の輪に見えて
# しまうため、決定論的な擬似乱数(VILLAGE_SEED由来)で±20度のヨーを加え、雑然とした
# 実物の集落の印象に近づける。回転は水平面内(エンジンのXZ平面)のみで行い、屋根の稜線は
# 水平のままにする(傾けない)。出典なしの決め値
# 【修正】±20度は振りすぎだった。弧長に沿って幅ぶんずつ詰めて置いたあとに各棟を±20度
# 回すと、隣家との接触が壊れて隙間と重なりが不規則に生じ、遠目に「斜面にこぼれた箱」に
# 見えていた。参考写真c_south_elevation_hazy.jpgの集落は、高さや前後に細かな差はあっても
# 正面の線は連続している。±9度に抑えて連続性を戻す(同心円の輪に見えない程度は残す)
VILLAGE_YAW_JITTER_DEG = 9.0

# 岩の表面から棟の底面までの張り出し量のジッター幅(決め値)。同心円のテラス方式では
# 内側・外側の2列を区別する必要が無くなったため、小さなランダムオフセットのみにする。
# 修正パス(タスクC): 家並みを密着させる方式に合わせ、外向きへ張り出しすぎて隣家との
# 接続が不自然に見えないよう範囲を-0.5〜0.5へ縮小した
# 修正パス(コーディネーター指摘、段階2): 家の前後のばらつきを増やし、段々に張り出す
# 実物の印象に近づけるため-2.5〜2.5へ拡大した。出典なしの決め値
# 修正: ヨー角と同じ理由で、前後のばらつきも±2.5→±1.2へ縮める。
# 正面の線を保ったまま、段々に張り出す不揃いさだけを残す
VILLAGE_OUTWARD_OFFSET_MIN = -1.2
VILLAGE_OUTWARD_OFFSET_MAX = 1.2

# 1棟あたりの寸法の範囲(決め値)。幅=切妻の妻面方向(道と直交)、奥行き=棟線(道に沿う方向)。
# 【修正・1棟が写真の約2倍の幅だった】参考写真と実機の同じ区間(正規化x0.72〜0.92)を
# 同じ倍率で切り出して家の正面を数えると、写真は約16、実機は約9しか無かった。
# 正面に見える幅は、妻を通りに向ける棟ではVILLAGE_WIDTH、棟が通りと平行な棟では
# VILLAGE_DEPTHになる。平均は 0.55*7 + 0.45*9 = 7.9m。実物のグランド・リュの間口は
# 4〜6m程度なので、幅を絞り、かつ妻を通りに向ける割合を上げて正面幅を小さくする
VILLAGE_WIDTH_MIN = 4.0
VILLAGE_WIDTH_MAX = 6.0
VILLAGE_DEPTH_MIN = 7.0
VILLAGE_DEPTH_MAX = 11.0
# 修正パス(タスクC): 振れ幅が大きすぎる(5.0〜14.0)と隣り合う家の高さの差が激しく
# 「棒グラフ状」に見えてしまうため、範囲を7.0〜13.0へ縮小した
# 修正パス(参考写真c_village_roofs_walls.jpgの精査): 幅5〜9mの家に壁7〜13mでは壁が
# 支配的で、屋根が帽子程度にしか見えず「箱の集合」になっていた。写真のノルマンディの家は
# 2〜3階建てで、その上に全体の1/3ほどを占める急勾配の大きな切妻が載る。壁を低くする
# 【修正・屋根の絨毯に見えていた】参考写真c_south_elevation_hazy.jpgの集落を拡大して
# 壁(軒まで)と屋根(軒〜棟)の高さの比を実測すると約3.3:1で、明るい石灰岩・漆喰の壁が
# 帯の見た目を支配し、暗いスレートの屋根は上端の細い縁にしか見えない。
# 旧値は壁6〜11m(平均8.5)・屋根が幅の0.60〜0.85倍(平均5.2m)で比が1.6:1しかなく、
# 低い視点から見ても暗い屋根が一面に広がる「屋根の絨毯」になっていた。
# 壁を高く・屋根を浅くして比を約3.4:1へ寄せる。壁が高くなると手前の列が奥の列を隠すため、
# 段が何列も見えて奥行きが出すぎる問題も同時に軽くなる(出典なしの決め値)。
# 注意: 以前のパスが逆に壁を13→11mへ下げているが、それは見下ろすアングルの
# main_mid.png(カメラ高度60m)で判断したもので、実機カメラや参考写真の低い視点とは
# 屋根の見え方がまったく違う。判断は低い視点の絵で行うこと。
#
# 【修正・後から幅を変えたせいで、上で合わせた比が壊れていた】上の9〜15mは
# **当時のVILLAGE_WIDTH=5〜9m**を前提に決めた値である。屋根の高さは絶対値ではなく
# 幅への比(下のVILLAGE_ROOF_PITCH_RATIO)で決まるので、
#   当時 : 壁 平均12.0 / 屋根 平均7.0*0.50=3.5 → 比 3.4:1 (実測値3.3:1に一致)
# だったが、その後「1棟が写真の約2倍の幅だった」修正で幅を4〜6mへ絞ったため、
#   直前 : 壁 平均12.0 / 屋根 平均5.0*0.50=2.5 → 比 4.8:1
# となり、**壁だけを触っていないのに比が測定値から45%ずれていた**。
# 幅を変えた側のコミットはこの連動に気づいていない。
# 実測の3.3:1へ戻すため、屋根平均2.5mに対し壁の平均を 3.3*2.5=8.25m に置く。
# 振れ幅は「棒グラフ状」を避けるため上と同じ6mを保ち、5.5〜11.0(平均8.25)とする。
# 階高3.0m(VILLAGE_WINDOW_FLOOR_HEIGHT)に対し2〜3階建てになり、実物の
# グランド・リュの間口4〜6mに対する高さとしても無理がない
# (旧値の「幅5m・高さ12m」は4階建ての塔で、家の形をしていなかった)。
VILLAGE_WALL_HEIGHT_MIN = 5.5
VILLAGE_WALL_HEIGHT_MAX = 11.0
# 屋根の高さは絶対値ではなく妻方向の幅に対する比で決める。絶対値(2.0〜5.0m)だと、
# 幅の広い家では勾配が寝て平屋根に、狭い家では立ちすぎて不揃いになっていた。
# 比0.40〜0.60は勾配約39〜50度で、参考写真のノルマンディの切妻の範囲に収まる
VILLAGE_ROOF_PITCH_RATIO_MIN = 0.40
VILLAGE_ROOF_PITCH_RATIO_MAX = 0.60
# 弧長に沿って家を詰めて置く際の、隣り合う家どうしの隙間(ほぼゼロ。家どうしを接させる
# ための決め値)
VILLAGE_HOUSE_GAP = 0.3
# 棟を通りと直交させる(=切妻の妻を通りに向ける)棟の割合。
# 空撮c_aerial_se_goldenhour.jpgを真上から読むと、妻を通りに向ける家と、棟が通りと平行に
# 走る家がおよそ半々に混在している。どちらか一方に揃えると「同じ形の妻が並ぶ群れ」か
# 「屋根面だけの絨毯」のどちらかになり、実物のばらつきが出ない(出典なしの決め値)
# 【修正】0.55だと45%の棟が奥行き(7〜11m)を正面に向け、正面幅の平均を押し上げていた。
# 実物のグランド・リュは細い妻を通りに向ける棟が大半なので0.85へ上げる。
# これで平均の正面幅は 0.85*5.0 + 0.15*9.0 = 5.6m(旧7.9m)
VILLAGE_GABLE_TO_STREET_RATIO = 0.85

# --- 集落の家の窓(開口)。参考写真の暗い画素は正規化高さ0.1〜0.3(=集落と中腹)に
# 18〜22%集中していて、その正体は窓・扉・軒の陰。実機の家は無地の板で、
# 暗い材質のWindowGlass(0.020,0.022,0.028)は島の0.2%しか無かった。
# 実物のノルマンディの家の窓は幅0.8〜1.0m・高さ1.4〜1.6m・階高約3m(出典なしの決め値)。
# 600m先では1つ約5x8画素になり、遠景でも点として効く。
# カメラに向く面(半径方向の外側)にだけ置く。裏面は見えないので三角形を使わない ---
VILLAGE_WINDOW_WIDTH = 0.9
VILLAGE_WINDOW_HEIGHT = 1.5
VILLAGE_WINDOW_SPACING = 2.4          # 横方向の間隔
VILLAGE_WINDOW_PROTRUSION = 0.15      # 壁からのわずかな飛び出し(Booleanの代わり)
VILLAGE_WINDOW_SILL_FIRST = 2.2       # 1階の窓の下端(地面から)
VILLAGE_WINDOW_FLOOR_HEIGHT = 3.0     # 階高
VILLAGE_WINDOW_SKIP_PROBABILITY = 0.2  # 格子に見えないよう間引く割合
# 専用のrandom.Randomインスタンスを使う。グローバルのrandomを消費すると
# 既存の家・樹木の位置がすべて動いてしまうため(ABBEY_FACADE_WINDOW_SEEDと同じ理由)
VILLAGE_WINDOW_SEED = 20260806

# --- 軒の出と煙突。参考写真の家は例外なく、軒の下に濃い水平の影の線が入り、
# 屋根の稜線から煙突が突き出して屋根の線を刻んでいる。実機の家は屋根が壁と面一で、
# 稜線も一直線だった。どちらも数メートル規模の凹凸で、島の暗部(写真13%対実機2.8%)は
# こうした小さな陰の集まりでできている ---
VILLAGE_EAVES_OVERHANG = 0.6   # 軒が壁より外へ出る量。実物のノルマンディの家は0.3〜0.5m
VILLAGE_CHIMNEY_WIDTH = 0.9    # 煙突の平面寸法(正方形)
VILLAGE_CHIMNEY_HEIGHT = 2.2   # 棟から上へ出る高さ
VILLAGE_CHIMNEY_PROBABILITY = 0.85   # 煙突を持つ棟の割合(出典なしの決め値)


# --- 植生(vegetation)。600m先では葉の1枚1枚は見えず緑の塊のシルエットとしてしか
# 視認されないため、木1本のジオメトリは低ポリの円柱(幹)+潰したUV球(樹冠)で済ませる ---
VEGETATION_SEED = 20260805

# 木1本のジオメトリ(出典なしの決め値)
VEGETATION_TRUNK_RADIUS = 0.4
VEGETATION_TRUNK_SEGMENTS = 8
VEGETATION_TRUNK_HEIGHT_RATIO = 0.3  # 木全体の高さに対する幹の高さの割合
VEGETATION_CROWN_U_SEGMENTS = 8
VEGETATION_CROWN_V_SEGMENTS = 6
VEGETATION_CROWN_SQUASH = 0.75  # 樹冠(UV球)の縦方向の潰し率(1.0で真球)
VEGETATION_CROWN_OVERLAP = 0.3  # 樹冠が幹の上端にめり込む量(接続を自然に見せるための決め値)

# --- 樹冠を1本ごとに崩すためのばらつき(出典なしの決め値) ---
# 【なぜ要るか】947本すべてが「同じ向きに縦へ潰した真球」だったため、参考写真と並べると
# 樹林ではなく**球が並んでいる**ように見えた(c_north_whole_lowtide.jpgの樹林は
# 連続した塊で、個々の樹冠は縁でようやく見分けられる程度)。
# 1本ごとに変わっていたのは高さと樹冠半径だけで、形も向きも全部同じだった。
#
# 【真球のままでは回転しても無駄】縦に潰しただけの回転体は鉛直軸まわりに対称なので、
# 向きを振っても見た目は1ミリも変わらない。**先に水平断面を楕円にしてから回す**必要がある。
VEGETATION_CROWN_ASPECT_MIN = 0.72  # 水平方向の2軸の伸縮率(1.0で円)。楕円の扁平さ
VEGETATION_CROWN_ASPECT_MAX = 1.28
VEGETATION_CROWN_TILT_MAX_DEG = 12.0  # 樹冠の軸の傾き(斜面に立つ木は真上を向かない)
# 樹冠の頂点を半径方向へ押し引きする量(半径に対する比)。輪郭をでこぼこにする。
# これが「球に見える」を一番強く壊す
VEGETATION_CROWN_NOISE = 0.22

# 【注意】この値は木の全高ではなく**幹の高さ**を決める(幹=height×0.3)。樹冠は
# その上に載るので、実際の木の天端は 0.3*height + 1.7*crown_radius*CROWN_SQUASH。
# 17〜23なら実際の天端は約8.6〜11.5mで、写真の樹林として妥当な高さになる。
# 樹冠を写真に合わせて小さくしたとき、樹冠の縦の広がりが減って**樹林の天端が1.4m
# 下がり**、3組の指標が0.0306→0.0312と揃って悪化した。木の高さは出典が無い値なので、
# スカイラインに決めさせた(3組平均):
#   8/14  0.0312 (樹冠を小さくした直後)
#  11/17  0.0310
#  14/20  0.0308
#  17/23  0.0306  ← 採用。樹冠を小さくする前の水準に戻る
#  20/26  0.0305  (改善は頭打ちで、south_lowは0.0213→0.0215と悪化に転じる)
# 20/26以上は平均の伸びが止まる一方で主ビューが悪化し、さらに木の頭が修道院基礎の
# 擁壁を隠す領域(過去にそれで上限を下げた経緯がある)へ入るため、17/23で止める。
VEGETATION_HEIGHT_MIN = 17.0
VEGETATION_HEIGHT_MAX = 23.0
# 【写真から測り直した樹冠の大きさ】旧値は直径6〜10m。c_north_whole_lowtide.jpgの
# 樹林の斜面を拡大して測ると、島の幅1431px≒340m(4.21px/m)の尺度で個々の樹冠は
# 19〜30px = **4.4〜7.1m** しかなく、モデルは1.2〜2倍大きかった。
# 樹冠が大きすぎると、1本1本が絵の上で15〜20pxの塊として分離して見えてしまい、
# 写真のような「細かい粒が連続した樹林」にならない。
VEGETATION_CROWN_RADIUS_MIN = 2.2  # 樹冠の直径4.4〜7.2mの半分
VEGETATION_CROWN_RADIUS_MAX = 3.6

# 修正パス(参考写真c_aerial_se_lowtide.jpg/c_aerial_sw_daylight.jpgの精査): 木を斜面に
# 等間隔にばらまく方式では「白い斜面の水玉模様」に見えると指摘されたため、塊(クラスタ)
# ごとに木をまとめて生やす方式へ置き換えた。木は塊をなして樹冠どうしが重なり、地面が
# 透けて見えないようにする。旧VEGETATION_DENSE_*/VEGETATION_SPARSE_*(密/疎の一様
# スキャッタ)はこの方式に置き換えて削除した
# 修正パス(コーディネーター指摘、段階3: 参考写真との並置から、樹木が島の上半分をほぼ
# 一様に覆う「緑の毛布」に見えると指摘された。実物は西〜北西の斜面と中腹の一部にしか
# 木が無いため、塊の数を46→30へ減らした。出典なしの決め値
# 修正パス(コーディネーター指摘、副作用の是正): 段階3の削減が行き過ぎて樹木が西側の
# 一塊になり他が裸の岩になってしまったため、角度範囲(移動自体は正しいので維持)は
# そのままに、塊の数を30→40・下草を40→55へ戻して量を増やした。出典なしの決め値
# 修正: 上の2つで塊を撒く面積が約1.8倍(角度255/195度 × 高さ0.54/0.40)になったため、
# 密度を保つよう塊の数も40→70へ増やす
# 【修正・樹林が写真の2倍濃かった】参考写真の植生を「G>R+2 かつ G>=B」(日陰の樹冠も拾う。
# photo_green_loose.pngで描き戻して検証済み)で数えると島の13.5%。実機は28.8%だった。
# 形(x0.1〜0.4に多く、x0.8以東は無い)は合っているので、1塊の濃さは変えずに塊の数を
# 減らして隙間を作る(写真の樹林は「濃い塊と裸地が交互」で、一様な薄い緑ではない)。
# あわせて角度範囲を東(-30度)まで広げる。集落の上端を0.125へ下げたので、
# _theta_deg_in_village_lower_arcが集落の帯だけを避けてくれる。
# 面積あたりの密度は 45塊/330度 対 70塊/265度 = 0.52倍
# 【追いこみ】45塊→32塊にしても被覆は0.198→0.195とほとんど動かず、x方向の分布だけが
# 大きく入れ替わった(x0.4-0.5が0.052→0.184など)。塊が数十個しかないと1回の実現値の
# ばらつきが支配的になり、分布を追いかけてもノイズを追うことになる。
# 「小さい塊を多数」へ変える。参考写真の樹木の連続長は中央で島幅の0.0106しかなく、
# 実物も大きな塊ではなく小さな群れの集合なので、こちらのほうが形も近い
# 上限を0.45→0.52へ上げた際、本数を据え置くと同じ塊数がより高い帯へ薄く散り、
# x0.65-0.70の樹冠の上端が0.312→0.053と穴が開いた。**面積あたりの密度**を保つため、
# 帯の高さの比 0.496/0.426 だけ本数を増やす(55→64)。画面上の濃さは変えない意図
VEGETATION_CLUSTER_COUNT = 64           # 塊の数
# 【樹冠を小さくしたぶん本数を増やす】VEGETATION_CROWN_RADIUS_*を写真に合わせて
# 平均4.0m→2.9mへ絞ったので、1本が覆う面積は (2.9/4.0)^2 = 0.53倍になる。
# 同じ被覆を保つだけで1/0.53≒1.9倍、さらに樹冠どうしを重ねて連続した塊に
# 見せたいので2.2倍にする(下草・中腹の帯・海際の本数も同じ倍率で揃える)
# 【修正・塊が融合して緑の壁になっていた】水平線に沿って樹木の連続長を測ると
#   参考写真   中央=0.0106(島幅比) p75=0.0190 p95=0.0444
#   実機veg3   中央=0.0536         p75=0.1467 p95=0.3265
# で、実機は「島の1/3を横切る連続した緑の塊」になっていた。原因は本数ではなく
# 1塊の広がり: VEGETATION_CLUSTER_THETA_SPREAD_DEG=7.0は半径140mで約34mあり、
# 塊どうしの間隔(330度÷45塊=7.3度)と同じだったため必ず隣と融合していた。
# 1塊の本数も、狭くしたぶん減らす(11〜24本を3度の広がりに詰めると団子になる)
# 3〜7本にした時点で被覆は0.326→0.183(写真0.135)。もう一段だけ減らす
VEGETATION_TREES_PER_CLUSTER_MIN = 1
VEGETATION_TREES_PER_CLUSTER_MAX = 3
# 修正パス(コーディネーター指摘、段階3): thetaの規約はatan2(engine_z, engine_x)
# (+X=東=0°, +Z=北=90°, -X=西=180°, -Z=南=-90°=270°)。旧範囲(-200.0〜110.0)は
# 310度分でほぼ全周を覆っていたため、参考写真で樹木が見られる「北→西→南南西」
# (95°〜250°)だけへ絞り、東側・南側の大半から樹木を無くした。出典なしの決め値
# 修正パス(コーディネーター指摘、副作用の是正): 塊が1か所に固まらないよう、角度範囲を
# 東北東〜北〜西〜南南西(70.0°〜265.0°)へ少し広げた。出典なしの決め値
# 【修正】集落の弧は-120〜0度(=240〜360度)なので、開始を70度にすると
# 0〜70度(東〜東北東)が集落にも樹木にも属さない空白の扇形として残っていた
# (真上からの絵で確認)。集落の弧の終端(0度)に合わせて隙間なく繋げる
# 【修正】265度(=-95度)で切ると、画面の正規化x0.42より東に木が1本も置けず、
# 参考写真でx0.4〜0.7に見える「家並みのあいだの木」を中腹の帯(全周)だけで賄うことに
# なっていた。集落の上端を下げたので、東(-30度=330度)まで広げてよい
VEGETATION_CLUSTER_THETA_START_DEG = 0.0
# 330度(=-30度)まで広げたら画面のx0.7〜0.8が0.198になった(写真は0.054)。
# 集落の東半分の上に木が乗りすぎるので315度(=-45度、x≒0.79)まで戻す
# 315度でもx0.7〜0.8が0.230(写真0.054)残ったので300度(=-60度、x≒0.73)まで戻す
VEGETATION_CLUSTER_THETA_END_DEG = 300.0
# 修正パス(修道院の量塊を実測比に合わせる対応): 参考写真では木が修道院の石積みの
# はるか下で止まっているが、モデルでは木が修道院の足元まで覆って基礎構造を隠して
# いたため、密な植生帯の上限を0.80→0.66へ下げた(出典なしの決め値)。
# 修正パス(タスクB): 参考写真c_north_whole_lowtide.jpg/c_northeast_whole_lowtide.jpgでは
# 島の東半分が砂地の高さから島の高さの約6割まで途切れない森の塊になっている一方、
# モデルは裸の岩肌に木がまばらな中腹の帯しか無かったため、下限を0.50→0.10へ下げ、
# 砂地のすぐ上から木を生やせるようにした(上限0.66は修道院を木が飲み込むのを防ぐため
# 変更しない)
# 修正パス(コーディネーター指摘、段階3): 段階1で岩を細くしたことに合わせ、植生の上限を
# さらに0.66→0.60へ下げた。出典なしの決め値
# 修正パス(コーディネーター指摘、副作用の是正): 集落の上端を0.44へ戻し、その上の中腹
# (擁壁・庭の層)へ樹木を押し上げるため、下限を0.10→0.20・上限を0.60→0.68へ引き上げた。
# 参考写真の4層構造(城壁/集落/擁壁と庭と樹木/修道院)に合わせた出典なしの決め値
# 修正パス(コーディネーター指摘、参考写真との並置から特定): 木の頭(高さ8〜14m)を足すと
# 修道院基礎の擁壁(天端はCHURCH_FLOOR_Y=80m)の下半分を隠していた。参考写真では樹木は
# 壁のはるか下で止まり壁の高い明るい面が見えているため、上限を0.68→0.60へ下げた。
# 出典なしの決め値
# 【修正・裾が全周で裸だった】南北の反転を直して初めてまともに評価できるようになり、
# 真上からの絵で t<0.20 の裾が全周で裸の岩のままだと分かった。集落(t=0.06〜0.36)が
# 埋めているのは南東側だけで、北・西では城壁までの幅約35mの帯が空いていた。
# 参考写真(c_north_whole_lowtide.jpg / c_aerial_sw_daylight.jpg)では、島は建物・樹木・
# 石垣で覆われ裸の岩は西の断崖だけなので、下限を集落と同じ0.06まで下げて裾を埋める。
# 過去のパスがここを0.10→0.20へ上げているが、それは集落のある南東側だけを見た判断で、
# 集落の無い北・西では裾が空くという副作用に気づいていなかった。
# 集落の弧の下部へは_theta_deg_in_village_lower_arcの引き直しが効くので侵入しない。
# 修正: 集落を城壁の内側の面まで下ろした(VILLAGE_TERRACE_HEIGHT_T_START参照)のに合わせ、
# 樹木側も同じ下限へ揃える。0.06のままだと集落の無い北・東で、城壁と樹木のあいだに
# 同じ幅約12.6mの裸の帯が残ってしまう
# 【修正・樹冠が写真より0.10〜0.15高い所まで登っていた】材質IDレンダ(--material-id)で
# 実機の樹木の上端を列ごとに測り、参考写真c_south_elevation_sunny.jpgに正規化格子を
# 描いて読んだ値と並べると:
#   正規化x     0.15-0.30  0.30-0.45  0.45-0.60  0.60-0.70
#   写真の樹冠   0.26       0.30       0.34       0.29
#   実機の樹冠   0.29-0.41  0.43-0.46  0.43-0.45  0.41
#   参考写真の樹冠の上端(列ごとの上端の分布) p50=0.311 p90=0.373
#   上限0.60のとき                            p50=0.393 p90=0.440
#   上限0.30まで下げたとき(下げすぎ)          p50=0.245 p90=0.274
# 2点から傾きは約0.55(画面高さ/単位t)。p90=0.373に当たるのはt≒0.48、p50=0.311では
# t≒0.43なので、あいだを取って0.45にする。
# 【解析だけでは決められない理由】クラスタの中心は[下限,上限]の一様乱数で、木が上限
# ちょうどに立つことはめったに無い。「t=0.30の地表に樹高20mを足すとh=0.346」という
# 換算表の値をそのまま上限にすると、実測は0.274にしかならなかった。上限は実測の
# 2点から決める(推測で決めない)
# 【修正・樹冠の上端が中央〜東で届いていなかった】写真の手読みカーブと突き合わせると
# (x区間ごとのp90。scratchpad/curve_vs_photo.py):
#   x0.35-0.40 写真0.424 対 実機0.251 / x0.55-0.60 0.414 対 0.332 / x0.60-0.65 0.389 対 0.343
# 上限0.45は「p90=0.373に当たるのがt≒0.48、p50=0.311ではt≒0.43」の中間として決めたが、
# その2点は集落を低く抑えていた頃の実測で、集落の上端を0.125→0.21へ上げたことで
# 木を集落の上へ追い出す抽選の境界も動いた。密度(塊の数・1塊の本数)はそのままに、
# 上限だけ上げる。h0.4-0.5の樹冠の占有率(写真0.02)を戻りの見張りに使う
VEGETATION_CLUSTER_HEIGHT_T_MIN = 0.024
VEGETATION_CLUSTER_HEIGHT_T_MAX = 0.52
# 修正パス(タスクB): 集落がある南〜東(VILLAGE_ARC_START_DEG〜END_DEG)の下部
# (height_t < VILLAGE_TERRACE_HEIGHT_T_END)には木を密に生やしたくない(家と重なるため)。
