VEGETATION_CLUSTER_THETA_SPREAD_DEG = 3.0
VEGETATION_CLUSTER_HEIGHT_T_SPREAD = 0.04
# 密な植生帯だけ、木同士が重なって見えるよう岩の表面からの張り出しをランダムに振って
