VEGETATION_CLUSTER_OUTWARD_OFFSET_MIN = -2.0
VEGETATION_CLUSTER_OUTWARD_OFFSET_MAX = 2.0

# 集落の隙間・城壁の内側に生える低い植生(下草)。thetaの範囲はクラスタと同じ
