VEGETATION_SHORE_HEIGHT_T_MAX = 0.30

# --- 教会本体(修道院の中心にある聖堂)。実物の根拠は「床の海抜80m」「プラットフォーム長
# 80m」(修道院公式サイト)、「元7ベイのうち西3ベイが1776年に破壊され現在4ベイ」
# (Catholic Encyclopedia)、「内陣は周歩廊と放射状礼拝堂を持つ半円形の後陣」(Catholic
# Encyclopedia/fr.wikipedia)のみで、高さ・平面寸法・配置座標は出典なしの決め値。
# 600m先では周歩廊・放射状礼拝堂は見えないため、後陣は単純な半円柱として簡略化する。
#
# 実物の教会は典礼上の東西方向を軸に建つ(身廊が西、内陣・後陣が東。aerial12.jpgで
# 交差部の尖塔を挟んで身廊が西南西へ、内陣が東北東へ伸びているのが確認できる)。
# 当初はZ軸(南北)を主軸に配置しており90度誤っていたため、X軸を主軸(身廊が-X側=西、
# 交差部が中央、内陣・後陣が+X側=東)、翼廊がZ軸(南北)方向へ張り出す配置に組み替えた。
# 定数名も軸に合わせてリネームした(CHURCH_SOUTH_Z→CHURCH_WEST_X、NAVE_NORTH_Z→
# NAVE_EAST_X、CHURCH_APSE_CENTER_Z→CHURCH_APSE_CENTER_X)。値自体は変更していない ---
CHURCH_FLOOR_Y = ROCK_PLATEAU_Z  # =92.0。教会は岩の頂上そのものに建つ(修道院公式サイト)
# 修正パス: 実物の修道院教会の全長は約80mだが、旧値(-5.0, NAVE_BAY_COUNT=4)では
# 身廊込みの全長が約51mしかなく、参考写真c_aerial_sw_daylight.jpgで教会が島の上半分を
# 占有していることに対して小さすぎた。交差部(CROSSING_CENTER_X)の位置を動かさずに
# 身廊だけを西へ伸ばして51m→66mへ近づけるため、NAVE_BAY_COUNTの変更(4→6)と
# セットで-5.0→-20.0へ変更した(NAVE_EAST_X=CHURCH_WEST_X+NAVE_BAY_DEPTH*NAVE_BAY_COUNT
# =-20+7.5*6=25.0で、変更前の25.0と一致するため交差部・鐘楼・尖塔・像・翼廊・後陣の
# 位置は一切動かない)
#
# 【修正・交差部を岩の頂上へ載せる】上記の経緯で交差部はずっとx=+25.0に置かれていたが、
# 岩の頂上台地(ROCK_PLATEAU_*)は原点中心なので、尖塔が岩の頂上から25m東へ外れていた。
# 実物の修道院教会は交差部が岩の頂上の真上に建っている(内陣・交差部が頂上を覆う)ため、
# これは構造的な誤り。書き出したglTFの実測でも、島の輪郭の東西中心がx=+3.29mなのに対し
# 最高点(尖塔)がx=+25.00mで、中心より21.7m東にあった。
# CHURCH_WEST_Xを-20.0→-45.0へ動かしてNAVE_EAST_X=CROSSING_CENTER_X=0.0とし、
# 教会群全体を西へ25m平行移動する(身廊の全長45mは変えない)。
# 付属建築・ラ・メルヴェイユの絶対X座標も、同じずれが再発しないようCROSSING_CENTER_Xからの
# 相対で書き直した(ABBEY_BLOCKS/MERVEILLE_X_*/ABBEY_CHATELET_TURRET_CENTERS参照)。
CHURCH_WEST_X = -45.0  # 身廊入口側(西)

# レビューで「修道院が岩の頂上台地(半径45m)に対して小さすぎる」との指摘を受け、
# 実物の「プラットフォーム長80m」(修道院公式サイト)に近づける意図で身廊・翼廊・後陣の
# 寸法を拡大した(いずれも出典なしの決め値)。NAVE_BAY_COUNTは上記CHURCH_WEST_Xの
# コメントのとおり4→6へ変更した(セット変更、交差部の位置は不変)
NAVE_BAY_DEPTH = 7.5
NAVE_BAY_COUNT = 6
# 修正パス(参考写真sw_high__c_aerial_sw_daylight.jpgの並置画像を実測した結果、修道院の
# 石の塊の幅/島の幅が参考写真0.41に対しモデル0.27、高さ/島の高さが参考写真0.49に対し
# モデル0.39と、実物比でおよそ1.5倍小さいと判明したための対応。NAVE_WIDTH・
# NAVE_WALL_HEIGHTを拡大して量塊を稼ぐ(出典なしの決め値、実物の身廊は側廊を含めると
# この程度という目安)。NAVE_BAY_DEPTH/NAVE_BAY_COUNT/CHURCH_WEST_Xは変更しない
# (前回のパスで身廊を66mに伸ばしたばかりのため、今回は幅と高さだけを触る)
NAVE_WIDTH = 26.0
# 修正パス(参考写真c_abbey_south_closeup.jpgの実測): 幅26mに対し屋根の高さ5.0mでは
# 勾配が21度しかなく、ほぼ平屋根だった。写真の身廊の屋根は棟の高さが半幅の約0.75倍
# (=約37度)の急勾配で、暗いスレートの大きな面としてはっきり見えている。
# さらに、以前のパスでNAVE_WALL_HEIGHTを18→24へ上げたことで棟線が103m→109mまで上がり、
# 交差部の鐘楼の石造部が11.7m→5.7mに潰れていた(写真の石造の塔は約11.5m)。
# 棟線を103mへ戻したうえで屋根を厚くし、鐘楼の高さを回復させる(出典なしの決め値)
#
# 【修正・塔が小塔に見えていた】参考写真c_abbey_south_closeup.jpgで比率を実測すると、
# 交差部の石造の塔は身廊の屋根の高さの約2.1倍そびえている(塔の天端〜身廊の棟 ≒ 125px、
# 身廊の棟〜軒 ≒ 60px)。旧値では 鐘楼11.7m / 身廊の屋根10.0m = 1.17倍しかなく、
# 塔が屋根に埋もれて「小さな小塔」に見えていた。塔の天端(BELFRY_TOP_Y=126.70m)は
# 出典で固定されているため、比率を合わせるには身廊を下げるしかない。
# 壁13.0→10.0、屋根10.0→8.0で棟線は115.0→110.0m、鐘楼は11.7→16.7mになり、
# 16.7/8.0=2.09倍で写真と一致する。屋根の勾配(棟の高さ/半幅)は変えていない
NAVE_WALL_HEIGHT = 10.0
NAVE_ROOF_HEIGHT = 8.0
NAVE_EAST_X = CHURCH_WEST_X + NAVE_BAY_DEPTH * NAVE_BAY_COUNT  # =25.0(交差部、変更前と同じ)

# 修正パス(コーディネーター指摘): 身廊を幅26m・壁高24mにしたことで、南西から見たときに
# 身廊の妻壁(西正面)が「のっぺりした一枚の板」に見えてしまう不具合が出た。身廊より
# 幅が狭く・背が低い前室(ナルテックス)状の塊をCHURCH_WEST_Xのさらに西に1つ足し、
# 妻壁が一枚の平面として立たないよう段差を付ける(出典なしの決め値)。
# CHURCH_WEST_X自体は変更しない(NAVE_EAST_X/CROSSING_CENTER_Xの関係を壊さないため)
CHURCH_WEST_BLOCK_DEPTH = 8.0
CHURCH_WEST_BLOCK_WIDTH = NAVE_WIDTH - 8.0            # =18.0
# 【修正・相対式で静かに潰れていた】以前は NAVE_WALL_HEIGHT - 7.0 と書かれており、
# コメントの「=17.0」は NAVE_WALL_HEIGHT=24.0 だった頃の値。その後 24→13→10 と
# 身廊を下げるたびに前室も 17→6→3m へ縮み、教会の西正面が事実上消えていた
# (どちらの変更もこの行を見ていない。相対式は連鎖して壊れるうえ、コメントの数値が
#  実際の値と食い違っても誰も気づかない)。絶対値にして連鎖を断つ。
# 7.0+5.0=12mで天端は CHURCH_FLOOR_Y+12=104m。身廊の棟線110mより6m低く、
# 「身廊より背が低い前室」という当初の意図どおりの段差になる(出典なしの決め値)
CHURCH_WEST_BLOCK_WALL_HEIGHT = 7.0
CHURCH_WEST_BLOCK_ROOF_HEIGHT = 5.0

# タスク4: 参考写真c_abbey_south_closeup.jpgで身廊の手前(南)に見える、身廊より低い
# 付属棟(実物の修道院長の館などにあたる)。屋根面を重ねてのっぺり感を消すための
# 出典なしの決め値
# 【修正・背が高すぎて教会と競合していた】旧値(幅16m・壁15m・屋根4m)は棟線が
# 92+15+4=111mで、**身廊の棟線110mより高かった**。しかも身廊(z=0)より手前(z=-19)に
# あるぶん画面ではさらに上に出るため、この付属棟がシルエットを作ってしまっていた
# (skyline.pyでx0.4-0.5の実機が写真より+0.036高い件の一因)。
# 参考写真c_abbey_south_closeup.jpgの南面の大きな棟は、教会より明らかに低く、
# 幅が広く、屋根の勾配が急で暗い面が大きい。幅44m・壁5m・屋根9m(棟線106m)に改める。
# 【高さは身廊のすぐ下ぎりぎりに置く】棟線を104mまで下げたら、skyline.pyのx0.5-0.6で
# 実機が写真より低い差が -0.020 → -0.026 と広がった。この付属棟はその区間の稜線を
# 作っていたので、下げすぎると穴があく。手前(z=-20、カメラから580m)にあるぶん
# 画面では上に出るので、身廊の棟線(110m、z=0、600m)と同じ画面高さになるのは
#   y = (110-1.6)/600 * 580 + 1.6 = 106.4m
# ここを上限として106mに置く。これで身廊を越えず、かつ稜線を落とさない。
# 棟に直交する幅14mに対して屋根9mで勾配52度
ABBEY_SOUTH_ANNEX_X_MIN = -20.0
ABBEY_SOUTH_ANNEX_X_MAX = 24.0
ABBEY_SOUTH_ANNEX_DEPTH = 14.0     # 身廊の南壁からさらに-Z方向へ張り出す量
ABBEY_SOUTH_ANNEX_WALL_HEIGHT = 5.0
ABBEY_SOUTH_ANNEX_ROOF_HEIGHT = 9.0

# --- 鐘楼・尖塔・像の配置基準(X/Z)。教会・翼廊の交差部の真上(承認済み計画の目安値)。
# CROSSING_CENTER_XはNAVE_EAST_X(身廊東端=交差部)の変更に、CROSSING_CENTER_Zは身廊の
# 中心線(=0、身廊はNAVE_WIDTHの分だけZ=0を中心に左右対称に配置される)にそれぞれ
# 追随させる(以下の翼廊・後陣・ラ・メルヴェイユの配置もこの2値を基準に組み立てるため、
# ここで先に定義する) ---
CROSSING_CENTER_X = NAVE_EAST_X
CROSSING_CENTER_Z = 0.0

# 修正パス(修道院の量塊を実測比に合わせる対応。NAVE_WIDTH/NAVE_WALL_HEIGHTのコメント参照)
TRANSEPT_EXTENT = 16.0        # 交差部中心線(Z)からの南北の張り出し量
TRANSEPT_DEPTH = NAVE_WIDTH   # X方向の厚み(交差部の厚み。身廊の幅と同じ数値を流用する決め値)
# 翼廊は交差部中心線(CROSSING_CENTER_Z)を挟んで南北対称に張り出す配置
TRANSEPT_SOUTH_Z = CROSSING_CENTER_Z - TRANSEPT_EXTENT  # =-16.0
TRANSEPT_NORTH_Z = CROSSING_CENTER_Z + TRANSEPT_EXTENT  # =16.0

# タスク3(内陣を身廊と同等以上に高く見せる修正パス): 参考写真c_abbey_south_closeup.jpg/
# aerial8.jpgでは内陣(後陣)が身廊と同等以上に高く、小尖塔が林立して見えるが、旧値では
# 低く目立たなかった。壁・屋根を引き上げ、壁上端に小尖塔を回す(出典なしの決め値)
APSE_RADIUS = 11.0
# 修正パス(参考写真c_abbey_south_closeup.jpgの実測): 身廊と同様に屋根が浅すぎたため、
# 身廊の棟線(103m)よりわずかに低い101mに収まる範囲で急勾配へ振り直した(出典なしの決め値)
# 修正: 身廊を下げた(NAVE_WALL_HEIGHTのコメント参照)のに合わせて内陣も下げる。
# 実物の内陣はゴシックで、ロマネスクの身廊よりわずかに高い。壁9.0+屋根8.0で棟は109.0mとなり、
# 身廊(110.0m)とほぼ同じ高さに揃う(その上に小尖塔が立ち上がって高く見える)
APSE_WALL_HEIGHT = 9.0
APSE_ROOF_HEIGHT = 8.0
# 後陣(半円の直径線)の中心X。交差部からさらに東へ「すぐ先」に置く決め値(旧
# CHURCH_APSE_CENTER_Zと同じオフセット量10.0mを、軸の組み替えに伴いX軸へ転用した)
CHURCH_APSE_CENTER_X = CROSSING_CENTER_X + 10.0  # =35.0

# 修正(参考写真c_abbey_south_closeup.jpgの内陣を拡大して実測): 実物の内陣は、外側に立つ
# 控え柱の上の細長い小尖塔が屋根の棟より4〜5m高く突き出し、空に対して棘状の縁を作っている。
# 旧値では柱の天端が102m・小尖塔の先端が105mで、内陣の棟(109m)より4m低く完全に隠れていた。
# 【本数を増やしても見える本数が増えなかった理由】飛梁は後陣の半円に沿って
# angle = -90°〜+90° を u=(i+0.5)/N で等分して置いている。この並びは angle=0(真東)に対して
# **対称**なので、真南から見ると北半分の柱が南半分の柱の真後ろに重なり、
# 画面上の相異なるX位置は N の半分しか出ない。9本置いても稜線の突起は5本しか立たない
# (材質IDレンダで実測。写真の同じ区間は9本)。
# 実物の飛梁も左右対称なので重なること自体は正しく、密度を上げるには本数を増やすしかない。
# 15本にすると相異なるXは8つ(X=36.7〜51.0m、間隔約1.8m)になり、
# 参考写真c_abbey_south_closeup.jpgの林立(約25mに12本前後=間隔2m)とほぼ同じ密度になる
FLYING_BUTTRESS_COUNT = 15
FLYING_BUTTRESS_PIER_HEIGHT = 14.0    # 柱の天端=CHURCH_FLOOR_Y+14=106m
FLYING_BUTTRESS_PIER_THICKNESS = 1.0
FLYING_BUTTRESS_PIER_OFFSET = 5.0
FLYING_BUTTRESS_BEAM_WIDTH = 0.5      # 出典なしの決め値(斜めの薄い板の幅)
# 斜めの梁が柱に取り付く高さを、柱の天端からどれだけ下げるか。
# 【修正】旧実装は梁を柱の「天端」に取り付けていたため、梁が壁(101m)から柱(102m)へ
# 上り勾配になっていた。実物のフライング・バットレスは壁側が高く外側へ下る。
# 柱は梁の取り付き点よりさらに上へ伸び、その上に小尖塔が載る構造にする
FLYING_BUTTRESS_BEAM_PIER_DROP = 8.0  # 柱側の取り付き=106-8=98m(壁側101mより低い)

# 後陣の壁面に放射状に並べる窓の本数(出典なしの決め値)。両端の平らな背面(翼廊との
# 接続部)付近を避け、-60°〜+60°の範囲に均等配置する
APSE_WINDOW_COUNT = 5

# タスク3: 後陣の壁上端(曲面部)に沿って並べる小尖塔の本数(出典なしの決め値)。
# 飛梁と同じ理由(FLYING_BUTTRESS_COUNTのコメント参照)で真南からは半分しか見えないので、
# 飛梁に合わせて増やす。半径11mに11本なら弧の間隔3.14mで、基部1.0mとは干渉しない
APSE_PINNACLE_COUNT = 11
# 飛梁の環(半径16m)と後陣の壁の環(半径11m)は、どちらも同じ角度の刻み方をしているため、
# 画面上のX位置が近い場所へ重なって「2重の同じ列」に見えてしまう。
# 壁側だけ半区間ずらして、投影したときに飛梁の小尖塔のあいだへ入るようにする
APSE_PINNACLE_ANGLE_STAGGER = 0.5
# 内陣専用の小尖塔の寸法。既定のPINNACLE_*(1.2×3.0m)はラ・メルヴェイユの控え壁の上でも
# 使っており、そちらは実物も小さいので変えない。内陣のゴシックの小尖塔だけ細く高くする。
# 柱の天端106m+7.0=113mとなり、内陣の棟(109m)より4m高く突き出て写真と一致する
APSE_PINNACLE_BASE_SIZE = 1.0
APSE_PINNACLE_HEIGHT = 7.0
# 小尖塔の高さを、後陣の先端(東)へ向かってどれだけ落とすか。
# 【なぜ要るか】柱の高さが全部同じだと小尖塔の先端も一直線に並び、遠景では
# **同じ長さの棒が等間隔に並んだ櫛**に見える(spikes_eng.pngで確認)。
# 参考写真c_abbey_south_closeup.jpgの林立は、交差部に近い西側がいちばん高く、
# 後陣の先端へ向かって段々に下がっていく。写真で実測すると、西端の小尖塔の先端が
# 天端から約8.5m、東端が約4mで、比はおよそ0.47。
# 高さは APSE_PINNACLE_HEIGHT * (1 - TAPER * cos(angle)) で与える
# (angle=0が後陣の先端=東、angle=±90°が交差部側=西)
APSE_PINNACLE_EAST_TAPER = 0.53

# --- ラ・メルヴェイユ。高さ40m・3階建て(出典: fr.wikipedia)。史実どおり教会の北側
# (+Z方向、翼廊の北端に接続)へ配置する(fr.wikipediaの記述とも一致)。カメラは島の南
# から見るため実際には教会の陰にほぼ隠れて見えなくなるが、実物の南からの空撮
# (aerial11.jpg/pexels1.jpg)でもそうなっているため、これが正しい挙動と判断した ---
# 幅約35m×奥行約25m(いずれも出典なしの決め値)。
# 修正: 教会群を西へ25m動かした際に取り残されないよう、CROSSING_CENTER_Xからの相対にした
# (値そのものは変えていない。旧: -5.0 / 30.0 で当時のCROSSING_CENTER_X=25.0)
MERVEILLE_X_MIN = CROSSING_CENTER_X - 30.0
MERVEILLE_X_MAX = CROSSING_CENTER_X + 5.0
MERVEILLE_Z_MIN = TRANSEPT_NORTH_Z         # 翼廊の北端に接続(TRANSEPT_EXTENT変更により16.0)
MERVEILLE_Z_MAX = MERVEILLE_Z_MIN + 25.0
# ラ・メルヴェイユの基準面(建物の足元のY座標)。実物は北側の断崖に張り付いて建っており、
# 建物自体は40m級でも屋根は教会より低い(参考写真c_north_merveille_detail /
# c_north_whole_lowtideで、教会の屋根と鐘楼が必ず上にあることが確認できる)。
# 以前はCHURCH_FLOOR_Y(80m)を足元にしていたため天端が126m・屋根が129mとなり、
# 鐘楼(BELFRY_TOP_Y=114.70m)より15m高くそびえて教会を隠していた。
# 誤っていたのは高さではなく基準面のほうだった(出典なしの決め値)。
# 修正: 岩の台地が80m→92mになった際に取り残されないよう、岩の高さパラメータt
# (このスクリプト共通の y = t * ROCK_PLATEAU_Z)で表す。t=0.625は旧値50.0/80.0と同じ
MERVEILLE_BASE_Y = ROCK_PLATEAU_Z * 0.625   # =57.5(旧: 50.0。岩が80m台地だった頃の値)
# 修正パス(修道院の量塊を実測比に合わせる対応): 修道院全体の量塊を稼ぐため40→46へ拡大
# 修正パス(身廊の棟線を103mへ戻した対応): 46mだと屋根の頂が105mとなり身廊の棟線(103m)を
# 超えてしまう。参考写真では教会の屋根が必ずラ・メルヴェイユより上にあるため、
# 出典のある40m(fr.wikipedia)へ戻す。屋根の頂は50+40+9=99mで身廊より4m低くなる
MERVEILLE_HEIGHT = 40.0

# 修正パス: build_abbey_substructure()が参照する外接矩形(MERVEILLE_X_MIN/MAX/Z_MIN/MAX)は
# 変えず、build_merveille()の内部だけでX方向に2つの塊へ分割する。実物は高さの違う複数の棟が
# 並ぶ(参考写真c_aerial_sw_daylight.jpg)ことに合わせた決め値
MERVEILLE_SPLIT_X = CROSSING_CENTER_X - 12.0   # 西側の塊と東側の塊の境界X座標(旧: 13.0)
MERVEILLE_EAST_HEIGHT_DROP = 6.0   # 東側の塊の高さをMERVEILLE_HEIGHTからどれだけ低くするか

# 修正パス(コーディネーター指摘): 窓のあいだの縦のリズムを強くするため5→7へ増やした
MERVEILLE_BUTTRESS_COUNT = 7   # 4〜5本の範囲内の決め値だったが7へ変更(縦のリズム強化)
# 【修正・リブがパネルに見えていた】参考写真c_northeast_whole_lowtide.jpg /
# c_north_merveille_detail.jpgのラ・メルヴェイユは、細い縦のリブが密に走る高い一枚壁で、
# リブの幅と間隔の比はおよそ0.3。旧値は幅3.0m・間隔約4mで比0.6あり、リブではなく
# 「幅の広い浅いパネル」に見えていた。細く・深くして縦のリズムを立てる。
MERVEILLE_BUTTRESS_WIDTH = 1.8    # 控え壁自体の幅(側面に沿う方向)
MERVEILLE_BUTTRESS_DEPTH = 3.2    # 控え壁の出っ張り量
# 【修正・北面にリブが1本も無かった】控え壁は西面・東面(Z方向に並ぶ)にしか付いておらず、
# 北から見える北面(Z=MERVEILLE_Z_MAX)は窓だけの平らな壁だった。北面こそ参考写真で
# リブが密に走る面なので、そこにも等間隔で付ける。塊の幅に応じて本数を決める
MERVEILLE_NORTH_BUTTRESS_SPACING = 4.0   # 北面のリブの間隔(m)

# 修正パス(コーディネーター指摘): 参考写真c_north_merveille_detail.jpg/c_north_wall_detail1.jpg
# では、細く背の高い開口が太い控え壁のあいだに縦長に並ぶ。既定の窓(WINDOW_WIDTH/HEIGHT=
# 1.5x5.0)を3段並べると窓が横長・小さすぎてオフィスビルの窓格子に見えるため、ラ・メルヴェイユ
# 専用に縦長の寸法を持たせる(出典なしの決め値。WINDOW_WIDTH/WINDOW_HEIGHTは他の場所でも
# 使うため変更しない)
MERVEILLE_WINDOW_WIDTH = 1.1
MERVEILLE_WINDOW_HEIGHT = 7.5

# 修正パス(参考写真c_aerial_sw_daylight.jpg/c_abbey_south_closeup.jpgの精査): 陸屋根の
# 平らな天面では北から見たときに「窓が格子状に並んだ平らな箱」に見えてしまうと指摘された
# ため、急勾配のスレート葺きの切妻屋根を載せる。棟がX方向(東西)に走る向きにする。
# MERVEILLE_HEIGHTは引き続き壁の高さとして使い、屋根はその上に積む(全体高さは
# MERVEILLE_HEIGHT+MERVEILLE_ROOF_HEIGHT=49mになる)
MERVEILLE_ROOF_HEIGHT = 9.0    # 棟の高さ(急勾配に見せるための決め値)

# --- 修道院の付属建築。実物は身廊・内陣・ラ・メルヴェイユのほかに、南東の修道院長舎/シャトレ/
# 裁治館、西のソー・ゴーティエ棟/ペリーヌ塔、ラ・メルヴェイユ上の回廊が積み重なっており、
# 屋根面が複雑に交差する。手続き生成では表現しにくいので座標を直書きする。
# (名前, x_min, x_max, z_min, z_max, 棟の向き('X'または'Z'), 基準の高さ, 壁の高さ, 屋根の高さ, 南面に窓を付けるか)
# 寸法はすべて参考写真(c_abbey_south_closeup / c_aerial_se_goldenhour / c_aerial_sw_daylight)から
# 目視で決めた出典なしの決め値。Cloitre(回廊)だけは基準の高さが特別で、ラ・メルヴェイユの
# 西半分の天端(MERVEILLE_BASE_Y + MERVEILLE_HEIGHT = 50+46 = 96m)に載る
# (修正パス: 当初126.0=CHURCH_FLOOR_Y+MERVEILLE_HEIGHTとしていたが、ラ・メルヴェイユの
# 基準面をCHURCH_FLOOR_Y→MERVEILLE_BASE_Yへ修正したのに合わせて96.0へ変更した) ---
# 修正: X座標はCROSSING_CENTER_Xからの相対で書く。以前は絶対値で直書きしていたため、
# 教会群を西へ25m動かしたときに付属建築だけ取り残されて教会から分離してしまう。
# 下の _CX + n の n は、旧実装の絶対値から当時のCROSSING_CENTER_X(=25.0)を引いた値で、
# 教会との相対配置は一切変わっていない
# 基準の高さも同じ理由で、岩の高さパラメータt(y = t * ROCK_PLATEAU_Z)で表す。
# t=0.6875 / 0.725 は、岩の台地が80mだった頃の旧値 55.0 / 58.0 と同じ位置を指す
_CX = CROSSING_CENTER_X
_BY_LOW = ROCK_PLATEAU_Z * 0.6875   # =63.25(旧: 55.0)
_BY_MID = ROCK_PLATEAU_Z * 0.725    # =66.70(旧: 58.0)
ABBEY_BLOCKS = [
    ("LogisAbbatial",  _CX - 9.0, _CX + 5.0, -27.0, -13.0, 'X', _BY_LOW, 33.0, 10.0, True),
    ("Chatelet",       _CX + 5.0, _CX + 17.0, -30.0, -17.0, 'X', _BY_LOW, 27.0,  7.0, True),
    ("Officialite",    _CX + 15.0, _CX + 25.0, -24.0, -12.0, 'X', _BY_MID, 22.0,  6.0, False),
    ("SautGaultier",   _CX - 59.0, _CX - 45.0, -16.0,  -2.0, 'Z', _BY_LOW, 31.0,  9.0, True),
    # 修正パス(身廊の棟線を103mへ戻した対応): 壁37mでは棟が103mとなり身廊と同高になって
    # しまうため30mへ下げた。実物のペリーヌ塔は教会より明らかに低い
    ("TourPerrine",    _CX - 57.0, _CX - 47.0,  -2.0,   8.0, 'Z', _BY_LOW, 30.0, 11.0, False),
    ("SouthWestLodging", _CX - 43.0, _CX - 29.0, -28.0, -14.0, 'X', _BY_LOW, 29.0,  8.0, True),
    # 回廊はラ・メルヴェイユの西半分の天端(MERVEILLE_BASE_Y + MERVEILLE_HEIGHT)に載る
    ("Cloitre",        _CX - 29.0, _CX - 13.0,  14.0,  26.0, 'X',
     MERVEILLE_BASE_Y + MERVEILLE_HEIGHT, 5.0,  3.0, False),
]

# --- 西端の建築(ガブリエル塔と、その内側に建つ大きな棟) ---
# 【追加の根拠】西〜北西の建築量が足りないことを、独立した2方向の計測で確認した:
#   ・south_low / south_mid のスカイライン重ね合わせで、画像左(西)だけ緑が赤より低い
#   ・ne_low(新規に計測へ組み込んだ北東からの写真)で、画像右(西北西)の赤が高く
#     保たれるのに対し緑は急に落ちる
# 同じ欠陥を別角度から見たもの。書き出したglTFの実測でも engine_x=-130..-90 は
# 樹木だけで最高47mしかなく、その西の x=-84..-50 で修道院の西テラスが93.5mへ
# 40mの段差で立ち上がる、という不連続になっていた。
#
# 参考写真c_southwest_elevation.jpgの西端に明確に写っているものだけを足す:
#   ・ガブリエル塔 — 城壁の西端に立つ円錐屋根の丸い塔
#   ・その内側の大きな棟 — 4階建て、淡い壁に灰色の屋根
# どちらも足元は岩の表面に合わせる(_find_rock_t_for_radiusで逆算)。寸法は写真から
# 目分量で決めた出典なしの決め値。
# 【修正・南面からまったく見えていなかった】172度はエンジンのz=+20.5m、つまり島の
# 中心より北側で、南のカメラからは岩の裏に隠れていた(材質地図の画面x0.0〜0.1に
# 集落系の材質が0%だったことで判明)。参考写真c_south_elevation_sunny.jpgでは
# 正規化x0.02〜0.05に円錐屋根の丸い塔がはっきり写っている。
# -170度にするとz=-26m(中心より南)になり遮られず、画面x=0.037に出る。
# 高さも直す: 天端27.9mでは画面高さh=0.174になるが、写真の塔の天端はh≒0.115。
# 換算(scratchpad/ht_table.py)では18mでh=0.113
WEST_END_TOWER_THETA_DEG = -170.0
WEST_END_TOWER_RADIUS = 7.0
WEST_END_TOWER_BODY_HEIGHT = 14.5
WEST_END_TOWER_ROOF_HEIGHT = 3.5
WEST_END_TOWER_SIDES = 12            # 丸い塔に見せるため城壁の塔(TOWER_SIDES)より多く割る
# 大きな棟。城壁のすぐ内側に置きたいので、岩の表面から少しだけ内側(半径を縮める)
# 【修正】塔と同じ理由(163度はz=+38mで岩の裏)。-160度でz=-45m・画面x=0.098になり、
# 参考写真の「塔の内側に並ぶ大きな棟」(正規化x0.06〜0.15、屋根の上端h≒0.12)と揃う。
# 棟線22m(壁15+屋根7)では画面高さ0.136になるので18m(壁13+屋根5)へ下げる
WEST_END_LODGE_THETA_DEG = -160.0
WEST_END_LODGE_RADIUS_INSET = 12.0   # 岩の裾(t=0)の半径からこれだけ内側
WEST_END_LODGE_WIDTH = 16.0          # 接線方向(妻の幅)
WEST_END_LODGE_DEPTH = 12.0          # 半径方向(棟の長さ)
WEST_END_LODGE_WALL_HEIGHT = 13.0    # 4階建て相当
WEST_END_LODGE_ROOF_HEIGHT = 5.0

# シャトレ双塔(実物の入口の左右にある円塔)。既存の_add_octagon_turret_to_bmeshを流用する。
# sides=8はBELFRY_TURRET_SIDESと同じ慣例に合わせた出典なしの決め値
# (X座標はABBEY_BLOCKSと同じくCROSSING_CENTER_Xからの相対。旧: 30.0 / 42.0)
ABBEY_CHATELET_TURRET_CENTERS = [(_CX + 5.0, -30.0), (_CX + 17.0, -30.0)]
ABBEY_CHATELET_TURRET_BOTTOM_Y = _BY_LOW   # シャトレ本体と同じ基準の高さ(旧: 55.0)
ABBEY_CHATELET_TURRET_BODY_HEIGHT = 30.0
ABBEY_CHATELET_TURRET_ROOF_HEIGHT = 8.0
ABBEY_CHATELET_TURRET_RADIUS = 3.5
ABBEY_CHATELET_TURRET_SIDES = 8

# --- ゴシックの尖頭アーチ窓。参考写真aerial6.jpg/village3.jpgで、縦長の窓が規則正しく
# 並ぶことがゴシック建築らしさの説得力の大部分を占めることを確認したため追加する。
# Booleanで壁に穴を開けると処理が重く破綻しやすいため、壁面から浅く外側へ飛び出す
# 「窓枠」の薄い箱として表現する(承認済み計画の方針。単色プレビューでも凹凸のパターン
# として視認できればよい)。寸法・間隔はいずれも出典なしの決め値 ---
WINDOW_WIDTH = 1.5
WINDOW_HEIGHT = 5.0
WINDOW_PROTRUSION = 0.4
WINDOW_HORIZONTAL_SPACING = 3.5

# --- 控え壁の上のピナクル(小尖塔)。実物のゴシック建築の特徴(出典: French Moments、
# 「控え壁の上にピナクルがあり石の花で装飾される」)。石の花の装飾は600m先では見えないため
# 省略し、単純な四角錐で表現する ---
PINNACLE_BASE_SIZE = 1.2
PINNACLE_HEIGHT = 3.0

# --- 鐘楼の隅の小塔。正方形の塔の4隅すべてに、細い多角形の小塔を追加する ---
# 【寸法を写真に合わせる修正】旧値(半径1.0=直径2.0m、天端より4.0m突き出す)は、
# c_abbey_south_closeup.jpgと並べると明らかに太く高すぎ、塔の錐屋根の下半分を隠して
# 屋根を潰れて見せていた。写真では隅の小塔は塔の幅(13.3m)の1/10ほどの細さで、
# 天端から2〜3m出る程度。半径0.6(直径1.2m=塔幅の1/11)・突き出し2.5mへ改める
# 【修正・屋根の急勾配を隠していた】隅の小塔は天端より2.5m突き出し半径0.6mあったため、
# 鐘楼の天端から約4mの高さまで幅15mの塊になり、その上の錐屋根が「低いドーム」に見えていた。
# 参考写真(spire_ref.png)では小塔は細く低く、屋根の三角形が塔の顔になっている
BELFRY_TURRET_RADIUS = 0.45
BELFRY_TURRET_SIDES = 8
BELFRY_TURRET_ABOVE_TOP = 1.0  # 鐘楼の天端より高く突き出す量(屋根を隠さない高さ)
BELFRY_TURRET_EMBED = 3.0      # 鐘楼本体に埋め込む量(接続を自然に見せるための決め値)
BELFRY_TURRET_ROOF_HEIGHT = 1.5
BELFRY_WINDOW_FACE_COUNT = 4    # 窓を付ける面数(BELFRY_SIDES=4なので4面すべて)

# --- 鐘楼のアーチ列(ロマネスクの鐘楼で最も目を引く部分)---
# 旧実装は1面あたり窓1つ(WINDOW_WIDTH=1.5×WINDOW_HEIGHT=5.0)で、遠景の並置
# (zoom_belfry.png)では塔の胴が「細い黒い切れ込みが1本あるだけの無地の塊」に見えていた。
# 参考写真では胴に3連のアーチ開口が並び、その下にもう1段2つの小さい開口がある。
#
# 寸法は c_abbey_south_closeup.jpg を6倍に拡大して実測した(belfry_arcade_ref.png)。
# 尺度は既存の実測と同じ 0.1154m/px(BELFRY_HALF_WIDTHのコメント参照)で、
# 塔の左右の縁 x=631/751px(=13.85m。既実測の13.3mと1画素以内で一致)を基準にした:
#   上段の開口 幅  10.8px → 1.25m  高さ 46.7px → 5.39m  中心間隔 26.7px → 3.08m
#   上段の頭は天端(コーニス y=364px)から 21px → 2.4m 下
#   下段の開口 幅   8.3px → 0.96m  中心間隔 58.3px → 6.7m  頭は天端から 101px → 11.65m 下
# 下段は実物では手前の屋根に切られて下端が見えないため、高さは出典なしの決め値(3.5m)。
#
# 【入るかどうかを先に確かめた】胴の高さは BELFRY_TOP_Y(126.70) - 身廊の棟
# (CHURCH_FLOOR_Y+NAVE_WALL_HEIGHT+NAVE_ROOF_HEIGHT=110.0) = 16.7m ある。
# 上段の敷居は118.9m、下段の敷居は111.55mで、どちらも胴に収まる
# (build_belfry内のコメントに「高さは5.7mしかない」とあるのは身廊を下げる前の古い記述)
BELFRY_ARCADE_COUNT = 3
BELFRY_ARCADE_WIDTH = 1.25
BELFRY_ARCADE_HEIGHT = 5.39
BELFRY_ARCADE_SPACING = 3.08
BELFRY_ARCADE_HEAD_BELOW_TOP = 2.4     # 天端から開口の頭までの下がり
BELFRY_LOWER_ARCADE_COUNT = 2
BELFRY_LOWER_ARCADE_WIDTH = 0.96
BELFRY_LOWER_ARCADE_HEIGHT = 3.5       # 出典なしの決め値(実物は手前の屋根に切られて見えない)
BELFRY_LOWER_ARCADE_SPACING = 6.7
BELFRY_LOWER_ARCADE_HEAD_BELOW_TOP = 11.65
# 開口の飛び出し量。既定のWINDOW_PROTRUSION(0.4m)は「壁から飛び出す薄い箱」で窓を
# 表現するための量だが、アーチ列は**奥まった開口**で、飛び出させると600m先では
# 明るい縦縞になって逆効果になる(_add_window_to_bmeshのコメントにある過去の指摘と同じ)。
# 面より内側へ引っ込める向きには作れない実装のため、飛び出しを最小にして、
# 材質は既定のWindowGlass(0.020,0.022,0.028。全材質で最も暗い)のまま暗さを出す
BELFRY_ARCADE_PROTRUSION = 0.05

# --- 修道院の垂直基礎構造(教会+ラ・メルヴェイユの平面輪郭を、岩の斜面まで垂直に
# 落とす花崗岩の壁の塊)。aerial12.jpg/aerial11.jpg/aerial6.jpgのいずれでも、教会は
# なだらかな岩の頂上台地に直接載っておらず、岩の斜面から垂直な壁が20〜40mにわたって
# 立ち上がり、その天端に教会が載っているのが確認できる。旧CRYPT_*によるクリプト擁壁
# (教会・ラ・メルヴェイユそれぞれの平面投影の外周をなぞる薄い帯)はこの新パーツに
# 統合して置き換えた(重複を避けるため呼び出しを外し、CRYPT_HEIGHT/CRYPT_THICKNESSは
# 削除した)。輪郭は厳密でなくてよいため、教会+ラ・メルヴェイユを合わせた外接矩形を
# 少し膨らませた多角形(超楕円で角を丸めた矩形として近似する)で表現する
# (出典なしの決め値) ---
ABBEY_SUBSTRUCTURE_MARGIN = 5.0        # 外接矩形を膨らませる量
ABBEY_SUBSTRUCTURE_SIDES = 16          # 輪郭の分割数(12〜16角形の範囲内の決め値)
ABBEY_SUBSTRUCTURE_SUPERELLIPSE_EXPONENT = 4.0  # 角を丸めた矩形にするための超楕円の指数
# 【修正・基礎が一枚の平らな壁に見えていた】参考写真c_abbey_south_closeup.jpgの下半分を
# 拡大すると、実物の基礎は「壁+細い刳形」ではなく、奥行きの違う幅の広い塊が並んで
# 互いに濃い影を落とす構成になっている。旧値は幅2.0m・出1.5mで、幅60m級の壁に対して
# 細すぎて陰影がまったく出ず、のっぺりした一枚壁に見えていた。
# 写真の縦の塊はおよそ幅8〜14m・出3〜6mなので、そこへ寄せる(出典なしの決め値)。
# 以前のパスが「控え壁が密に並びすぎて刳形に見える」として間隔を8→18mへ広げたのは、
# 幅と出が足りないまま本数だけ減らしたため、平らさが増す方向に働いていた。
# 【修正・分節が足りず一枚壁に見えていた】参考写真の壁を拡大すると、見えている変動の
# 主成分は控え壁の縦の陰影(zoom_ref_wall.png)。実機の同じ場所は平らな面だった。
# 太陽を真南西(225度)に置くと、控え壁の西を向く側面は順光・南を向く壁面は斜光になり、
# 影の描画に頼らずに明暗の縦縞が出る。出っ張りを深く、間隔を詰めて縞を増やす。
# 600m先では 幅5m=27px・間隔10m=53px(島の幅1464px)で、遠景でも縞として読める
ABBEY_BUTTRESS_WIDTH = 5.0             # 控え壁自体の幅(壁面に沿う方向)
ABBEY_BUTTRESS_PROTRUSION = 6.0        # 控え壁の出っ張り量
ABBEY_BUTTRESS_SPACING = 10.0          # 控え壁の配置間隔(周長に沿った距離、出典なしの決め値)
# コーニスも同じ理由で出っ張りを増やし、水平の影の線がはっきり出るようにする
ABBEY_CORNICE_HEIGHT = 1.8             # 天端近くの水平の帯(コーニス)の高さ
ABBEY_CORNICE_PROTRUSION = 1.6         # コーニスの出っ張り量
# 参考写真(c_aerial_sw_daylight.jpg/c_aerial_se_goldenhour.jpg)では基礎が一枚壁・
# 二段ではなく、外へ広がりながら何段も下りる「階段ピラミッド」になっているため、
# 上段(教会の輪郭。ABBEY_TIER_DROP_FRACTIONの係数で第0段として扱う)+
# ABBEY_TERRACE_OUTSETSの各段の多段構成にする(出典なしの決め値)
# 上段(教会の輪郭)に対する各下段の張り出し量(上段基準の絶対値。累積ではない)。
# 修正パス: 岩を細くした(ROCK_SOUTH_GENTLE_EXPONENT 2.2→1.25)ことで基礎を外・下へさらに
# 伸ばせる余地ができたため、最外段(42.0)を追加した。最外段はhalf_x+42/half_z+42で
# 半径70m前後になり、岩の表面ではおよそy=55mに相当する。これは植生クラスタの下端
# (VEGETATION_CLUSTER_HEIGHT_T_MIN=0.50 → y=40m)に近く、石と緑が繋がって
# 参考写真c_aerial_se_goldenhour.jpgで見られるような裸の岩肌の帯が消えることを狙った決め値
# 修正パス(コーディネーター指摘): 参考写真(c_aerial_sw_daylight.jpg/c_north_wall_detail1.jpg/
# c_north_merveille_detail.jpg)を精査すると、実物の基礎は浅い段が何段も連なる「階段」では
# なく、岩から直接立ち上がる高くて連続した石壁になっている。段数を4→2へ減らし
# (ABBEY_TIER_DROP_FRACTIONも引き上げ)、1段あたりの壁を高くした
# 【修正・基礎の下端が写真より高かった】材質地図では石積が支配的になるのは画面高さ
# h=0.4以上(h0.4-0.5で0.875)で、そこから下は岩と中腹の擁壁だった。参考写真の同じ
# 正規化x(0.30〜0.65)では、修道院の石壁がh≒0.28まで途切れずに下りている。
# 最下段は岩の表面まで届く(drop=1.0)ので、張り出しを一段足すと足元がそのぶん外・下へ伸びる
# 【行きすぎの是正】55.0の段を足したら、h0.4-0.5が石積100%・h0.3-0.4も0.838になり、
# 階段状の巨大な塊が島の上半分を飲み込んだ(樹木も0.147→0.114に隠された)。
# 参考写真の基礎は「浅い段が何段も」ではなく1枚の高い壁なので、段を増やさずに
# 外段の張り出しだけを30→40へ伸ばす
ABBEY_TERRACE_OUTSETS = [12.0, 40.0]
# 各段が「天端からその位置の岩の表面までの距離」のうち何割を下りるか。
# 1.0未満にすることで下の段へ引き継がれ、段状になる(最下段だけは1.0=岩まで届かせる)。
# 0.85に引き上げ、各段が岩の表面近くまで一気に下りる高い壁になるようにした
ABBEY_TIER_DROP_FRACTION = 0.85
ABBEY_TERRACE_STEP_GAP = 1.0           # 各段の天端を1つ上の段の下端よりどれだけ下げるか(視覚的な段差)

# --- 修道院の南面の下段の建物群(基礎の第2段の天端に載る棟の列)---
# 【なぜ要るか】材質IDレンダで測ると、南面は無地の花崗岩の一枚壁になっていた。
# 実行時のログで出した実際の値:
#   第0段 天端92.0m 下端89.3m ( 2.7m)
#   第1段 天端88.3m 下端82.4m ( 5.9m)
#   第2段 天端81.4m 下端63.1m (18.2m)  ← カメラに最も近く、視野を支配する
# 合計27mが窓以外なにも無い石の面で、その上に載る建物の屋根は94.7〜110mの15mの帯に
# 固まっている(島の見かけの高さの約1割)。参考写真の修道院は屋根がもっと広い範囲へ
# 散っており、暗いスレートと明るい壁が交互に重なって見える。
# 数値でも、修道院の区画(正規化x0.25〜0.65 / h0.30〜0.80、島の画素のみ)の
# 暗部が 参考写真29.7% に対して実機12.6%、CVが0.531に対して0.327しかない。
#
# 実物のこの高さには修道院の下部の南向きの建物群が建つ。第2段の天端(81.4m)に棟の列を
# 載せて、無地の壁を「壁+急勾配の暗い屋根」の重なりに置き換える。
# 寸法はすべて出典なしの決め値だが、根拠の軸は以下のとおり:
#   ・棟の高さは、天端81.4m+壁5.5+屋根8.0=94.9mで、上のテラス(92.0m)をわずかに
#     越える。参考写真でも下段の屋根は上段の建物の足元に少し掛かっており、
#     完全に下へ収めると建物どうしが重ならず「並んだ模型」に見える
#   ・棟に直交する幅16mに対して屋根の高さ8.0mで、勾配は45度。カメラの仰角
#     (600m先で高さ90m→約8.5度)より十分急なので、屋根面が大きく見える
# 【1回目は小さすぎた】幅11m・壁4.5m・屋根4.5mで作ったところ、屋根の見かけの高さが
# 20画素しかなく細い横棒に見えた。修道院の区画の暗部は12.6%→12.7%とほぼ動かなかった
# (追加した暗い面が区画のわずか4%にしかならないため)。奥行きと勾配を上げて面を稼ぐ
ABBEY_SOUTH_ROW_COUNT = 4
ABBEY_SOUTH_ROW_X_MIN = CHURCH_WEST_X + 5.0            # =-40.0
ABBEY_SOUTH_ROW_X_MAX = CROSSING_CENTER_X + 26.0       # =26.0
ABBEY_SOUTH_ROW_GAP = 2.5              # 棟と棟のあいだ(ここに影が落ちて分節して見える)
ABBEY_SOUTH_ROW_DEPTH = 16.0           # 棟に直交する方向の幅(屋根の勾配を決める)
ABBEY_SOUTH_ROW_WALL_HEIGHT = 5.5
ABBEY_SOUTH_ROW_ROOF_HEIGHT = 8.0
ABBEY_SOUTH_ROW_EDGE_INSET = 2.0       # 段の南端からどれだけ内側(北)へ引くか

# 南テラス(実物の「西のテラス」「ゴーティエの跳躍」に相当する張り出し)。教会の南側は
# 身廊・交差部が岩の中心付近(新ROCK_PLATEAU_RADIUS=20mの内側)にあるため上段・下段の壁が
# ほぼ0mになる問題への対応(出典なしの決め値)。南から見るカメラにこの区画の擁壁が
# 正面に見えるようにする。上に建物は載せず、天端は平らなテラス面+低い手すり壁にする
SOUTH_TERRACE_DEPTH = 25.0             # 教会の南辺からさらに-Z方向へ張り出す量
SOUTH_TERRACE_RAILING_HEIGHT = 1.5     # テラス縁の手すり壁の高さ
SOUTH_TERRACE_RAILING_THICKNESS = 0.4  # 手すり壁の厚み

# タスク2: 参考写真c_abbey_south_closeup.jpgの左端に見える、大きなアーチの台の上の
# 広い平らなテラス(実物の「西のテラス」)。南テラスと同じ作りをX方向へ流用する
WEST_TERRACE_DEPTH = 20.0

# タスク1: 参考写真c_abbey_south_closeup.jpgで、修道院の下部の巨大な石の壁に小さな窓が
# 点在しているのに合わせる。これが無いと擁壁にしか見えない(出典なしの決め値)
# 修正パス(コーディネーター指摘): 下段(-15.0)が壁の下端より下に来てスキップされる箇所が
# 多かったため下段を上げ、間隔も詰めて密度を上げた
# 各段の天端からの相対高さ。
#
# 【修正・格子に見えていた】以前は4段×間隔5.0mで、南面が「4行×約25列の均一な窓の格子」に
# なり、遠景で19世紀の兵舎や事務所ビルのように見えていた(main_mid.pngを拡大して確認)。
# 過去のパスは「写真では小さな窓が4〜5段に散っている」と読んで段数を2→4へ増やし間隔も
# 詰めたが、これは逆方向だった。参考写真c_abbey_south_closeup.jpgで実際に効いているのは
# 窓の「数」ではなく「不規則さ」で、実物は大きな無地の石壁が主体、開口はまばらで
# 行も列も揃っていない。段数と密度を落とし、決定論的な擬似乱数で間引き・高さのばらつきを
# 与えて格子を崩す(出典なしの決め値)。
ABBEY_FACADE_WINDOW_ROW_OFFSETS = [-6.0, -13.0]
ABBEY_FACADE_WINDOW_SPACING = 9.0                  # 輪郭に沿った窓の間隔(m)
ABBEY_FACADE_WINDOW_WIDTH = 1.2
ABBEY_FACADE_WINDOW_HEIGHT = 4.0                   # 幅に対して縦長にする(中世の開口の比率)
# 窓を間引く確率と、行の高さに与えるばらつきの幅(m)。列と行が揃うのを崩すための決め値。
# グローバルのrandomは集落・植生が固定シードで使っているため、こちらは専用の
# random.Randomインスタンスを使い、他の生成物の乱数列を一切動かさない
ABBEY_FACADE_WINDOW_SEED = 20260803
ABBEY_FACADE_WINDOW_SKIP_PROBABILITY = 0.40
ABBEY_FACADE_WINDOW_ROW_JITTER = 1.6

# --- 中腹の等高線状の擁壁(集落の上端と修道院基礎の間の斜面を段々にする)。
# 集落の上端は現在 VILLAGE_TERRACE_HEIGHT_T_END=0.36(以下の修正パスの記録に出てくる
# 0.44 / 0.56 はいずれも当時の値で、現在値ではない)。
# 参考写真c_aerial_sw_daylight.jpgで見える、水平方向に何本も走る石の擁壁の線に
# 対応する決め値。build_abbey_substructure()の階段ピラミッドとは別に、岩の斜面自体に
# 沿わせた開いた弧(閉じた輪ではない)として配置する ---
# 修正パス(コーディネーター指摘、参考写真c_aerial_se_goldenhour.jpg/c_aerial_sw_daylight.jpg
# との並置から特定): 集落上端から修道院基礎までの斜面が、擁壁2段だけでは「のっぺりした
# 裸の円錐」に見え、修道院が浮いて見えていた。参考写真では擁壁が何段も重なった段々に
# なっているため、2段→4段へ増やし、遠景でも段として見えるよう擁壁自体の高さも
# 3.5→5.0へ上げた。出典なしの決め値
# 修正パス(コーディネーター指摘、副作用の是正): 集落の上端を0.56→0.44へ戻したのに合わせ、
# 擁壁の帯を集落が退いた中腹(0.44〜修道院基礎の間)へずらした。出典なしの決め値
# 【修正・擁壁が修道院の基礎に埋もれていた】集落の上端を0.36→0.125へ下げたので、
# t=0.48〜0.72(画面の正規化高さ h=0.30〜0.44)はもう「集落と修道院のあいだ」ではなく
# 修道院基礎そのものの高さになっていて、材質地図でもその帯は石積0.749で埋まっている。
# 空いたのは h=0.15〜0.30 で、材質地図では岩(裸地)が h0.2-0.3 で0.531を占めていた。
# 参考写真の同じ帯には大階段(グラン・ドグレ)の擁壁と段々の庭の石垣が何本も走っており、
# 裸の斜面ではない。擁壁の帯を h=0.10〜0.29 に当たる t へ丸ごと下ろす
# (換算表 scratchpad/ht_table.py: t=0.16→h=0.105, 0.27→0.178, 0.38→0.247, 0.49→0.310,
#  0.60→0.369, 0.71→0.425)
# 【追加の修正】4段でt=0.16〜0.46まで下ろしたら、今度は h=0.30〜0.40 が裸の岩の丘に
# なった(岩 0.079→0.521)。参考写真のその帯は修道院の基礎の石壁で、裸地ではない。
# 段数を4→6に増やして、集落の上端(h≒0.15)から修道院の基礎(h≒0.43)まで切れ目なく
# 石が続くようにする
SLOPE_TERRACE_HEIGHT_TS = [0.16, 0.27, 0.38, 0.49, 0.60, 0.71]   # 岩の高さパラメータt
SLOPE_TERRACE_ARC_START_DEG = -200.0
SLOPE_TERRACE_ARC_END_DEG = 70.0
SLOPE_TERRACE_SEGMENTS = 60      # 弧の分割数
SLOPE_TERRACE_WALL_HEIGHT = 5.0  # 擁壁の高さ
SLOPE_TERRACE_THICKNESS = 1.5    # 擁壁の厚み(放射方向・外向き)

# --- 鐘楼・尖塔・像の高さ(出典あり)。このスクリプトのy=0は干潟の砂の面なので、
# 砂地基準の値で積み上げる:
#   岩の頂上(=教会の床)        92.00m  fr.wikipedia「Le Mont-Saint-Michel」
#                                       「cet îlot s'élève au-dessus d'une plaine
#                                        sablonneuse à 92 mètres d'altitude」
#   教会の床 → 塔の天端        +34.70m  同記事「celle du sol de l'abbatiale au sommet
#                                        de la tour fait 34,70 m」
#   塔の天端 → 尖塔の頂        +39.80m  下の170mから逆算(=170.00-92.00-34.70-3.50)
#   尖塔の頂 → 像の頂          + 3.50m  fr.wikipedia「Abbaye du Mont-Saint-Michel」
#                                       「Mesurant 3,5 m」(フレミエ作の聖ミカエル像)
#   合計                        170.00m  同記事「s'élevant à plus de 170 mètres」
#
# 【修正】以前はCHURCH_FLOOR_Yに海抜基準の78.60m(≒80)を使いながら、岩の高さには
# 砂地基準の92mを使っていたため、合計が158.50mと11.5m低かった。基準面の取り違え。
# 海抜基準で揃えれば 78.60+34.70+39.80+3.50=156.60 ≒ 出典の157.10m となり、
# どちらの基準面で揃えても内訳は同じであることが確認できる(理由はROCK_PLATEAU_Zのコメント)。
# 像の高さは出典どおり3.50m(以前の4.00mは出典なしの丸め)。
BELFRY_TOP_Y = CHURCH_FLOOR_Y + 34.70  # =126.70
SPIRE_TOP_Y = BELFRY_TOP_Y + 39.80     # =166.50
STATUE_TOP_Y = SPIRE_TOP_Y + 3.50      # =170.00

# 鐘楼(八角形の基部)。平面形状・半径は出典なしの決め値。底面は教会・翼廊交差部の屋根の
# 実際の高さに合わせ、隙間なくBELFRY_TOP_Yまで届くようbuild_belfry()内で高さを計算する。
# 【この記述は古かった】以前ここには「NAVE_WALL_HEIGHT+NAVE_ROOF_HEIGHT=29m、鐘楼の胴は
# 5.7mへ縮む」と書いてあったが、その後NAVE_WALL_HEIGHT/NAVE_ROOF_HEIGHTは10.0/8.0へ
# 下げられている(NAVE_WALL_HEIGHTのコメント「塔が屋根に埋もれて小さな小塔に見えていた」参照)。
# 現在の胴の底は CHURCH_FLOOR_Y+18 = 110.0m、胴の高さは 126.70-110.0 = 16.7m ある。
# アーチ列(BELFRY_ARCADE_*)が入るかどうかはこの値で判断している
# 【形を写真に合わせる修正】以前は八角柱(BELFRY_SIDES=8、外接円半径6.0)だったが、
# 参考写真c_abbey_south_closeup.jpg / c_belfry_spire_detail.jpg のどちらでも、実物の
# 交差部の塔は**正方形**である(平らな面が縦の稜線で交わり、4隅に小塔が立つ)。
#
# 寸法は c_abbey_south_closeup.jpg(望遠のほぼ正投影)から実測した。出典のある
# SPIRE_TOP_Y - BELFRY_TOP_Y = 39.80m を、写真上の「塔の天端のコーニス(y=355px)から
# 尖塔の先端(y=10px)」345pxに当てて 0.1154 m/px を得る。この尺度で:
#   塔の対面幅          115px → 13.3m   (旧モデルは八角形の対面幅で11.1m。細すぎた)
#   塔の天端→屋根の頂    97px → 11.2m   (旧BELFRY_ROOF_HEIGHT=10.5)
#   屋根の頂→尖塔の先端 248px → 28.6m   (旧29.3m)
#   尖塔の底面幅         40px →  4.6m   (旧SPIRE_BASE_RADIUS=2.2、直径4.4m)
# 高さの配分は元から概ね合っていたので、主に直すのは平面形。
BELFRY_HALF_WIDTH = 6.65   # 対面幅13.3mの半分(上記の実測値)
BELFRY_SIDES = 4           # 正方形。面は±X・±Z(教会の身廊はX軸方向)を向く
# 尖塔は八角錐のまま(写真でも尖塔は八角形)。鐘楼と辺の数が違うので定数を分ける
SPIRE_SIDES = 8
# 鐘楼の頂に載る急勾配のスレート屋根(四角錐台)。参考写真では交差部の石造の塔の上に
# 錐形のスレート屋根があり、尖塔はその頂から立ち上がっている。
# 高さは上記の実測(11.2m)に合わせた。SPIRE_BASE_Yがこの値で決まるため、尖塔の高さは
# 自動的に28.6mになり、そちらも実測と一致する。
# 出典のあるBELFRY_TOP_Y / SPIRE_TOP_Y / STATUE_TOP_Y は動かさない
BELFRY_ROOF_HEIGHT = 11.2
# 尖塔の底面。屋根の頂から立ち上がる(以前はBELFRY_TOP_Yから直接立ち上げていた)
SPIRE_BASE_Y = BELFRY_TOP_Y + BELFRY_ROOF_HEIGHT  # =137.90
# 尖塔の底面半径。c_abbey_south_closeup.jpgの塔まわりを拡大して測り直した値。
# 最初は「尖塔の底面幅40px→4.6m」と読んだが、拡大して見ると**その40pxは小尖塔の環まで
# 含んだ幅**で、尖塔そのものは2.8m(半径1.4m)しかない。小尖塔の環の差し渡しは別に
# 6.1m(SPIRE_PINNACLE_RING_RADIUS参照)。
# 尖塔が細くなるぶん、鐘楼の錐屋根はほぼ尖った四角錐になる。写真の錐屋根も鋭く尖って
# いてその頂に小尖塔の環と尖塔が載るので、こちらの方が写真に近い
SPIRE_BASE_RADIUS = 1.4
# 尖塔の輪郭のふくらみ。r = R * (1-t)^EXPONENT の指数(t=0で底面、t=1で先端)。
# 1.0なら直線の円錐。写真では尖塔が根元で急に細くなってから針のように立つ。
# 中間の高さ(t=0.5)での幅は写真で1.02m、直線の円錐なら1.4mなので
#   (0.5)^EXPONENT = 1.02/2.8 = 0.364  →  EXPONENT ≒ 1.46
SPIRE_PROFILE_EXPONENT = 1.46
# 尖塔の最小半径。**寸法の是正ではなく、遠景で消えないための下限**。
# 【なぜ要るか】実測どおり(底面半径1.4m・指数1.46)に作ると、上端に近い部分の直径は
#   t=0.83 で 0.21m しかない。600m先では約0.9画素で、画素中心をどの三角形も跨がず
#   ラスタライズから丸ごと落ちる。実際、最終画の行399〜439(標高156〜166m)は
#   周囲の空とまったく同じ輝度で、尖塔の上10.5mが1画素も描かれていなかった
#   (その結果、頂上の像だけが宙に浮いて見えていた)。
# 実カメラは画素の面積で積分するので0.5画素幅の暗い線でも写るが、点サンプリングの
# ラスタライザは落とす。遠景で「見えるべきものが見える」ことを優先して下限を設ける。
# 【先細りの下限は試して失敗した】下限自体を (1-t)^0.3 で細らせて「太さと先細りの両立」を
# 狙ったが、下限が定数より細くなるぶん消える範囲がむしろ広がった(消えた行 13→41行)。
# 点サンプリングのラスタライザでは、先端へ向かって0に収束する針はどう作っても必ず
# 1画素を切る区間ができる。太さを保つことを優先して定数の下限へ戻す。
# 0.40m(直径0.8m=約3.3画素)なら確実に残り、消えるのは先端の1.5mほどに収まる。
# 上半分が同じ太さの棒になるが、3画素幅では先細りは元々判別できない
SPIRE_MIN_RADIUS = 0.40
# 【先端の1区間の長さがそのまま「消える長さ」になる】最上段のリングから先端までは
# 1区間で0まで絞るので、その区間のうち1画素を切る部分が描かれない。
# 実測: 6分割(区間4.8m)で消える長さ4.4m、10分割(2.9m)で2.4m、30分割(1.0m)で下記。
# リングを増やす費用は三角形が数百枚だけなので、細かく割って先端の欠けを詰める
SPIRE_PROFILE_SEGMENTS = 30  # 高さ方向の分割数

# 尖塔の付け根を取り巻く小尖塔の環。c_belfry_spire_detail.jpgで最も目を引く部分で、
# 尖塔がいったんくびれてから小尖塔で広がり、また細く立ち上がる。これが無いと
# 「屋根から棒が生えている」ように見える。
# c_abbey_south_closeup.jpgの塔まわりを拡大して実測: 環の差し渡し6.1m(半径3.05m)、
# 小尖塔が立ち上がっている範囲の高さ約7.0m。
# 【太さの修正】最初は半径0.55(直径1.1m)で作ったが、8本を半径3.2mの円周(周長20m、
# 間隔2.5m)に並べると隙間より本体の方が目立ち、写真の透けた小尖塔群ではなく
# **金物の首輪**のように見えた。写真の1本は0.4m程度しかないので細くする
SPIRE_PINNACLE_COUNT = 8
SPIRE_PINNACLE_RING_RADIUS = 2.40
SPIRE_PINNACLE_RADIUS = 0.3     # 小尖塔1本の太さ(直径0.6m)
SPIRE_PINNACLE_SIDES = 6        # 600m先では輪郭しか出ないため辺は少なくてよい
# 屋根へ埋め込む量。**尖塔を細くして錐屋根がほぼ尖ったあとは、この値が効く**。
# 埋め込み1.0mで作ったときは、半径3.05mの環が尖った屋根の外側で宙に浮き、
# 小尖塔の下に影の隙間ができて「浮いた首輪」に見えた。
# 錐屋根は y=BELFRY_TOP_Y(126.70)で隅半径9.4m、y=SPIRE_BASE_Y(137.90)で1.4mまで
# 絞られるので、隅半径が3.05mになるのは y≒135.6m。そこまで下ろせば足元が屋根に埋まる
# (面の中心側は屋根がもっと内側にあるため、余裕を見て2.5mとする)
SPIRE_PINNACLE_EMBED = 2.5
# 本体+屋根の高さ。写真では錐屋根の頂から小尖塔群の先端まで約7.7m。
# 埋め込み2.5mを足して 6.4 + 3.8 = 10.2m とする
SPIRE_PINNACLE_BODY_HEIGHT = 3.5
SPIRE_PINNACLE_ROOF_HEIGHT = 2.0

# 鐘楼の隅(頂点)の角度。面の中心が±X・±Zを向くよう、頂点を半面ぶん(π/BELFRY_SIDES)
# 回した位置に置く。BELFRY_SIDES=4なら隅は45/135/225/315度、面の中心は0/90/180/270度で、
# 教会の軸(身廊はX軸方向)と平らな面が揃う
BELFRY_CORNER_ANGLE_OFFSET = math.pi / BELFRY_SIDES
# 隅までの距離(外接円半径)。対面幅の半分BELFRY_HALF_WIDTHから逆算する
BELFRY_CORNER_RADIUS = BELFRY_HALF_WIDTH / math.cos(math.pi / BELFRY_SIDES)

# 聖ミカエル像(簡略プレースホルダー)。600m先では2〜3pxにしかならないため、「翼を広げた
# 輪郭が分かる程度」の簡略形状にする(承認済み計画の方針)。寸法は出典なしの決め値。
# 胴体の高さは、承認済み計画の例示値(3.0m)ではなくSTATUE_TOP_Y(158.50)までちょうど
# 届く値(=4.0m)を採用する。像の最高点をSTATUE_TOP_Yに正確に一致させる方を優先した
# (glTF出力のPOSITION Y最大値の確認項目があるため)
STATUE_BODY_WIDTH = 1.0
STATUE_BODY_DEPTH = 1.0
STATUE_BODY_HEIGHT = STATUE_TOP_Y - SPIRE_TOP_Y  # =4.0
STATUE_WING_LENGTH = 2.0
STATUE_WING_WIDTH = 2.0
STATUE_WING_THICKNESS = 0.2
STATUE_WING_ANGLE_DEG = 30.0    # 出典なしの決め値(外側・上向きに開く角度)
STATUE_WING_ROOT_HEIGHT = 1.0   # 出典なしの決め値(胴体のうち翼の付け根の高さ)

# --- プレビューレンダリング共通設定 ---
PREVIEW_RESOLUTION_X = 960
PREVIEW_RESOLUTION_Y = 540
PREVIEW_SAMPLES = 16
PREVIEW_FOV_Y_DEGREES = 45.0
# KurenaiEngine側のカメラ(Scenes/MontSaintMichel.kscene)のPitch指定と同じ角度
PREVIEW_PITCH_DEGREES = 2.0

# --- 参考写真との比較レンダリング(--compare)専用の設定 ---
# 参考写真との突き合わせ用のため、プレビュー(PREVIEW_RESOLUTION_*)より高い解像度にする
# (出典なしの決め値)。サンプル数はPREVIEW_SAMPLESを流用する
COMPARE_RESOLUTION_X = 1200
COMPARE_RESOLUTION_Y = 800

# 修正パス(コーディネーター指摘): --compareのレンダに干潟の地面(PreviewGround)を
# 混ぜると、島の下側2/3が「空」ではなく「地面」を背景にしてしまい、
# compare_reference.py側のスカイライン抽出(上から走査して背景でない最初の行を探す方式)が
# 地面の水平線を拾って島を見失う不具合があった(south_high/sw_high/se_highでwidth_px_renderが
# 極端に小さくなる形で顕在化)。--compareでは地面を作らず、島に絶対に現れない色
# (マゼンタ)を背景にすることで「背景でないピクセル=島」を厳密に判定できるようにする
COMPARE_BACKGROUND_COLOR = (1.0, 0.0, 1.0)

# カメラの遠クリップ面(add_camera参照)。遠方からのほぼ正投影の較正ビュー(north_far、
# 距離6000m)を足したときに、Blenderの既定値では島がまるごとクリップされて背景単色の
# 画像が出力された。島は半径150m程度で深度精度が問題になる用途も無いため、
# どの距離からでも確実に写る値を一律で入れる(出典なしの決め値)
CAMERA_CLIP_END = 20000.0

# 比較用の各ビュー。方位角・仰角は参考写真から見積もった近似値(厳密に合わせる必要はない)。
# south_lowはScenes/MontSaintMichel.kscene側の実機カメラと同じ位置・画角(実機での
# 見え方の確認用)のため、positionとfov_yは変更しないこと。
# (name, position(エンジン空間), target(エンジン空間), fov_y_degrees, references)
#
# 【重要・trace_ref.pngの実測で判明】参考写真側のスカイライン自動抽出は、ここにある写真の
# ほぼ全てで破綻していた。空の輝度から求めた閾値で上から走査する方式のため、島の下半分の
# 背景が「空」ではなく対岸の陸地・干潟・海面である写真では、そこで走査が止まってしまい
# 修道院の上部しか島として拾えていなかった(水平線が水際よりはるか上に引かれる)。
# その結果「写真=修道院だけ vs レンダ=島全体」を比較しており、report.txtの参考写真側の
