def _clear_scene():
    """factory-startupの既定オブジェクト(Cube/Camera/Light)を含め、シーンを空にする。"""
    for obj in list(bpy.data.objects):
        bpy.data.objects.remove(obj, do_unlink=True)


def _link(obj):
    bpy.context.scene.collection.objects.link(obj)
    return obj


# _create_island_materials()で作ったマテリアルのキャッシュ。build_island()が複数回
# 呼ばれる場合(--exportと--previewを同時指定した場合など)でも、_clear_scene()は
# オブジェクトしか消さずbpy.data.materialsは残るため、素朴に毎回bpy.data.materials.new()
# すると同名重複("Rock.001"等)になってしまう。ここでキャッシュして1回だけ作る
_island_materials_cache = None


def _create_island_materials():
    """ISLAND_MATERIALSの順にPrincipled BSDFのマテリアルを作って、その順のリストを返す。

    同名マテリアルが既に存在する場合(_clear_scene()後の再実行など)は作り直さず
    bpy.data.materials.get(name)で既存を再利用する。結果はモジュール内でキャッシュし、
    2回目以降の呼び出しでは作成処理を行わずキャッシュをそのまま返す。
    """
    global _island_materials_cache
    if _island_materials_cache is not None:
        return _island_materials_cache

    if MATERIAL_ID_MODE and len(MATERIAL_ID_PALETTE) != len(ISLAND_MATERIALS):
        print(
            f"[ERROR] MATERIAL_ID_PALETTEの数({len(MATERIAL_ID_PALETTE)})が"
            f"ISLAND_MATERIALSの数({len(ISLAND_MATERIALS)})と一致しません",
            file=sys.stderr,
        )
        raise ValueError("MATERIAL_ID_PALETTEの数がISLAND_MATERIALSと一致しません")

    materials = []
    for slot_index, (name, color, roughness, metallic) in enumerate(ISLAND_MATERIALS):
        # 材質IDモードでは識別しやすいパレット色の単色にする(テクスチャは接続しない)。
        # ラフネス・メタリックも一様にして、アルベド以外の要因で色がぶれないようにする
        if MATERIAL_ID_MODE:
            color, roughness, metallic = MATERIAL_ID_PALETTE[slot_index], 1.0, 0.0
        try:
            mat = bpy.data.materials.get(name)
            if mat is None:
                mat = bpy.data.materials.new(name)
                mat.use_nodes = True
                bsdf = mat.node_tree.nodes.get("Principled BSDF")
                if bsdf is None:
                    raise RuntimeError(f"マテリアル({name})にPrincipled BSDFノードが見つかりません")
                bsdf.inputs["Base Color"].default_value = (color[0], color[1], color[2], 1.0)
                bsdf.inputs["Roughness"].default_value = roughness
                bsdf.inputs["Metallic"].default_value = metallic

                # MATERIAL_TEXTURE_FIELDSに載っているマテリアルは、手続き生成した変動場の
                # 画像をShaderNodeTexImageで作りBase Colorへ接続する。default_valueは接続後は
                # 使われなくなるが、念のためこれまでどおりの値を入れたままにしておく
                field_name = None if MATERIAL_ID_MODE else MATERIAL_TEXTURE_FIELDS.get(name)
                if field_name is not None:
                    field_func = msm_textures.FIELD_FUNCTIONS[field_name]
                    field = field_func()
                    tint_name = MATERIAL_TINT_FIELDS.get(name)
                    tint_field = (msm_textures.TINT_FIELD_FUNCTIONS[tint_name]()
                                  if tint_name is not None else None)
                    image = msm_textures.create_variation_image(
                        name, field, color,
                        tint_color_linear=MATERIAL_TINT_COLORS.get(name),
                        tint_field=tint_field,
                    )

                    tex_node = mat.node_tree.nodes.new("ShaderNodeTexImage")
                    tex_node.name = f"{name}_Variation"
                    tex_node.image = image
                    mat.node_tree.links.new(tex_node.outputs["Color"], bsdf.inputs["Base Color"])

                    # 法線マップ(msm_textures.NORMAL_MAP_STRENGTHSに載っている材質だけ)。
                    # 同じ変動場を高さとみなして法線を作るので、アルベドの暗いところと
                    # 凹みが一致する。理由と実測値はNORMAL_MAP_STRENGTHSのコメント参照
                    normal_params = msm_textures.NORMAL_MAP_PARAMS.get(field_name)
                    if normal_params is not None:
                        depth_meters, tile_meters = normal_params
                        # タイルの実寸は勾配をメートルで取るために要る。UV投影の値と
                        # 食い違うと起伏の深さが名目どおりにならないので突き合わせる
                        uv_tile = MATERIAL_UV_TILE_METERS.get(name)
                        if uv_tile is not None and abs(uv_tile - tile_meters) > 1e-6:
                            print(
                                f"[ERROR] {name}の法線マップのタイル実寸({tile_meters}m)が"
                                f"MATERIAL_UV_TILE_METERS({uv_tile}m)と違います。"
                                f"msm_textures.NORMAL_MAP_PARAMSを合わせてください",
                                file=sys.stderr,
                            )
                            raise ValueError(f"{name}の法線マップのタイル実寸が一致しません")
                        normal_image = msm_textures.create_normal_image(
                            f"{name}_Normal", field, depth_meters, tile_meters)
                        normal_tex = mat.node_tree.nodes.new("ShaderNodeTexImage")
                        normal_tex.name = f"{name}_NormalTex"
                        normal_tex.image = normal_image
                        normal_map = mat.node_tree.nodes.new("ShaderNodeNormalMap")
                        normal_map.name = f"{name}_NormalMap"
                        mat.node_tree.links.new(normal_tex.outputs["Color"],
                                                normal_map.inputs["Color"])
                        mat.node_tree.links.new(normal_map.outputs["Normal"],
                                                bsdf.inputs["Normal"])
            materials.append(mat)
        except Exception as error:  # noqa: BLE001
            print(f"[ERROR] マテリアル({name})の作成に失敗しました: ({error})", file=sys.stderr)
            raise

    _island_materials_cache = materials
    return materials


def _assign_material_slots(obj):
    """全パーツ共通の順序でマテリアルスロットを割り当てる。

    面のmaterial_indexはbmesh側(または個別に設定したmesh.polygons側)で設定済みのため、
    全オブジェクトが同じ順序のスロット列を持てば、build_island()の最後でjoinした後も
    正しいマテリアルが引かれる。

    注意: mesh.materials.clear()はスロットを消すだけでなく、既に設定済みの
    polygon.material_indexも一律0へリセットしてしまう(実測で確認済みの挙動)ため、
    「既にスロット入り」の2回目以降の呼び出しではclear()せず何もしない形にする
    (新規メッシュのmaterialsリストは常に空のため、初回は単純にappendするだけでよい)。
    """
    try:
        materials = _create_island_materials()
        if len(obj.data.materials) == len(materials):
            # 既に割り当て済み(2回目以降の呼び出し)。clear()するとmaterial_indexが
            # 0へリセットされてしまうため、何もせずそのまま返す
            return
        for mat in materials:
            obj.data.materials.append(mat)
    except Exception as error:  # noqa: BLE001
        print(f"[ERROR] マテリアルスロットの割り当てに失敗しました(obj={obj.name}): ({error})", file=sys.stderr)
        raise


def _material_index(material_name):
    if material_name not in MATERIAL_SLOTS:
        print(f"[ERROR] 未知のマテリアル名です: {material_name}(既知: {sorted(MATERIAL_SLOTS)})", file=sys.stderr)
        raise ValueError(f"未知のマテリアル名です: {material_name}")
    return MATERIAL_SLOTS[material_name]


def _tag_new_faces(bm, first_face_index, material_name):
    """first_face_index以降に追加された面へmaterial_indexを設定する。

    【重要】この方式が使えるのはbm.faces.new()で1面ずつ作った場合だけ。
    bmesh.ops.*(create_cone/create_uvsphere等)で作った面には_tag_faces_since()を使うこと
    (理由はそちらのdocstring参照)。
    """
    bm.faces.ensure_lookup_table()
    material_index = _material_index(material_name)
    for i in range(first_face_index, len(bm.faces)):
        bm.faces[i].material_index = material_index


def _tag_faces_since(bm, faces_before, material_name):
    """faces_beforeに含まれない面(=そのあと追加された面)へmaterial_indexを設定する。

    faces_beforeはbmesh.ops.*を呼ぶ直前に set(bm.faces) で取っておいた集合。

    【なぜインデックス方式ではだめか・実測で確定】bmesh.ops.create_cone等は、既に面が
    あるbmeshに対して「新しい面を必ず末尾に追加する」とは限らない。ensure_lookup_table()
    後のインデックス順で新旧が入り混じるため、_tag_new_faces(インデックス方式)では
    取りこぼしが出る。実測では、小塔1本を空のbmeshに作ると屋根は19面になるのに、
    鐘楼のbmesh(既に面がある)へ作ると16面しかタグ付けされず、残る3面が既定値の
    material_index=0(=Rock)のまま出力されていた。鐘楼だけで12面が岩のテクスチャで
    描かれていた(書き出したglTFで、高さ123.7/126.7/130.7/137.2mにRockの面を検出)。
    """
    material_index = _material_index(material_name)
    tagged = 0
    for face in bm.faces:
        if face not in faces_before:
            face.material_index = material_index
            tagged += 1
    if tagged == 0:
        print(f"[WARNING] _tag_faces_since: 新しい面が1つもありませんでした(material={material_name})")


def _rock_south_weight(theta):
    """0.0(北, +Z)〜1.0(南, -Z)の重み。"""
    return (-math.sin(theta) + 1.0) * 0.5


def _rock_north_weight(theta):
    """0.0(南, -Z)〜1.0(北, +Z)の重み。"""
    return (math.sin(theta) + 1.0) * 0.5


def _rock_profile_exponent(theta):
    """角度に応じた半径プロファイルの指数(北=急峻・南=緩やかの間を線形補間し、西だけ厚くする)。

    南北の補間だけだと西(theta=180度)は必ず北と南のちょうど中間(0.675)になり、
    中腹が痩せる。実測では半径95mの位置で岩が28mしかなく、南からのスカイライン重ね合わせ
    (south_low / south_mid)で画像左=西だけ緑が赤より低い残差が系統的に残っていた。
    北東からの計測ビュー(ne_low)でも、画面右=西北西が急に落ちる形で同じ欠陥が出る。

    ROCK_WEST_FULL_EXTRAで西寄りの指数だけ持ち上げる。指数が大きいほど根元付近の幅を
    保つ(=同じ半径での高さが上がる)。東側には効かせたくないので max(0, -cos) を使い、
    二乗して北・南への染み出しを抑える。
    """
    south_weight = _rock_south_weight(theta)
    exponent = (
        ROCK_NORTH_STEEP_EXPONENT
        + (ROCK_SOUTH_GENTLE_EXPONENT - ROCK_NORTH_STEEP_EXPONENT) * south_weight
    )
    west_weight = max(0.0, -math.cos(theta))   # 西で1.0、東・真北・真南で0.0
    return exponent + ROCK_WEST_FULL_EXTRA * (west_weight ** ROCK_WEST_FULL_FALLOFF_POWER)


def _rock_local_carve(theta):
    """ROCK_LOCAL_CARVESに列挙した各崖について、そこだけ半径を削るガウシアン減衰量の和を
    返す(高さtには依存させず、底面から頂上まで一律に削ることで、その範囲だけ垂直に近い
    険しい崖に見えるようにする。既存の南北非対称プロファイル(_rock_profile_exponent)には
    手を加えず、_rock_radiusの結果に追加で減算する項として扱う)。
    """
    total = 0.0
    for center_deg, sigma_deg, depth in ROCK_LOCAL_CARVES:
        center = math.radians(center_deg)
        sigma = math.radians(sigma_deg)
        # 角度差を±π範囲に正規化してから減衰量を求める(0°/360°境界をまたいでも連続に扱うため)
        delta = (theta - center + math.pi) % (2.0 * math.pi) - math.pi
        total += depth * math.exp(-(delta ** 2) / (2.0 * sigma ** 2))
    return total


# ROCK_LOCAL_CARVE_MIN_RADIUSのクランプが実際に効いた(削り込み後の半径が下限を下回った)
# 回数のグローバルカウンタ。build_rock()で岩を細くした副作用として頂上付近で頻発していないか
# 確認するため、build_rock()の呼び出し前後でスナップショットを取ってログに出す(修正パスの指示)
_rock_local_carve_clamp_count = 0


def _rock_base_radius(theta):
    """裾(t=0)の半径。ROCK_PLAN_ELONGATIONで南東側へ伸ばした平面形にする。

    cosの項なので全周の平均半径は変わらず、面積もほとんど変わらない
    (相対振幅eに対しておよそ1+e^2/2倍)。理由と根拠は定数のコメント参照。
    """
    if ROCK_PLAN_ELONGATION == 0.0:
        return ROCK_BASE_RADIUS
    axis = math.radians(ROCK_PLAN_ELONGATION_AXIS_DEG)
    return ROCK_BASE_RADIUS * (1.0 + ROCK_PLAN_ELONGATION * math.cos(theta - axis))


def _rock_radius(t, theta):
    """高さ方向の割合t(0=底面,1=頂上台地)と角度thetaから、その位置の半径を求める。

    t=1では常にROCK_PLATEAU_RADIUSになるので、平面形を伸ばしても岩の頂上と
    その上の修道院は原点のまま動かない(=修道院が相対的に北西寄りになる)。
    """
    global _rock_local_carve_clamp_count
    exponent = _rock_profile_exponent(theta)
    base = _rock_base_radius(theta)
    radius = base + (ROCK_PLATEAU_RADIUS - base) * (t ** exponent)
    radius -= _rock_local_carve(theta)
    if radius < ROCK_LOCAL_CARVE_MIN_RADIUS:
        _rock_local_carve_clamp_count += 1
    return max(radius, ROCK_LOCAL_CARVE_MIN_RADIUS)


def _rock_peak_offset(theta):
    """頂上リングの角度thetaにおける、台地からの盛り上がり量。

    以前は「80mの台地の北側だけ92mの峰まで盛り上げる」ための関数だったが、
    基準面の取り違えが判明し台地自体が頂上(92m)になったため、盛り上がりは無くなった
    (理由はROCK_PLATEAU_Zのコメント参照)。頂上リングの高さの式を変えずに済ませるため
    関数は残し、常に0を返す。
    """
    return 0.0


def _select_rock_noise_texture_type():
    """このBlenderで利用可能な手続き型ノイズテクスチャの種類を実行時に確認し、使用する種類を選ぶ。

    Blenderのバージョンによって'CLOUDS'が無い可能性があるため、優先順位リストの先頭から
    実際に利用可能なものを選ぶ(bpy.types.Texture.bl_rna.properties['type']で列挙する)。
    """
    available = {item.identifier for item in bpy.types.Texture.bl_rna.properties['type'].enum_items}
    preferred_order = ['CLOUDS', 'MARBLE', 'DISTORTED_NOISE', 'STUCCI', 'MUSGRAVE', 'NOISE', 'VORONOI']
    for candidate in preferred_order:
        if candidate in available:
            print(f"岩肌のディテール用テクスチャタイプ: {candidate} を使用します(利用可能: {sorted(available)})")
            return candidate

    print(f"[ERROR] 手続き型ノイズテクスチャが1つも見つかりませんでした(利用可能なテクスチャ種別: {sorted(available)})", file=sys.stderr)
    raise RuntimeError("岩肌のディテール用テクスチャタイプが見つかりません")


def _add_rock_surface_detail(obj):
    """岩の表面にDisplaceモディファイアを粗い/中間/細かいの3段重ねて自然な凹凸を加え、
    その場で適用(ベイク)してobj自身のメッシュへ焼き込む。

    build_island()では岩(Rock)をアクティブオブジェクトにしたままjoinするため、joinは
    アクティブオブジェクトのモディファイアだけを残し、結合後のメッシュ全体にそれを適用して
    しまう(joinは非アクティブ側オブジェクトのモディファイアを捨てて素のメッシュだけを
    取り込む一方、アクティブ側のモディファイアは結合後もそのまま残り、取り込まれた全頂点に
    効いてしまうため)。ここでDisplaceを城壁・修道院・尖塔よりも前に、岩オブジェクト単体の
    段階で確実に適用しておくことで、このノイズが岩以外のパーツに漏れないようにする。
    """
    texture_type = _select_rock_noise_texture_type()

    bpy.context.view_layer.objects.active = obj
    obj.select_set(True)

    for name, noise_scale, strength in ROCK_DETAIL_LAYERS:
        try:
            texture = bpy.data.textures.new(name=name, type=texture_type)
            if hasattr(texture, "noise_scale"):
                texture.noise_scale = noise_scale

            modifier = obj.modifiers.new(name=name, type='DISPLACE')
            modifier.texture = texture
            modifier.strength = strength
            modifier.mid_level = 0.5
            modifier.direction = 'NORMAL'
            modifier.show_viewport = True
            modifier.show_render = True

            bpy.ops.object.modifier_apply(modifier=modifier.name)
        except Exception as error:  # noqa: BLE001 - Blenderオペレータの例外型は多岐にわたるため広く捕捉する
            print(f"[ERROR] 岩肌のDisplaceモディファイア({name})の適用に失敗しました: ({error})", file=sys.stderr)
            raise


def build_rock():
    """岩。実物の寸法(周囲約960m→平均半径153m、教会が載る台地の海抜約80m、自然の最高点の
    海抜92m)に基づく非対称プロファイル(北側=修道院側は急峻、南側=カメラ側は緩やか)を、
    bmeshでリングを積んで直接組み立てる。primitive_cone_addでは角度ごとに指数を変える
    非対称な断面を表現できないため。

    リング数はROCK_RING_SEGMENTS+1(i=0が底面y=0、i=ROCK_RING_SEGMENTSが頂上y=80)。
    高さ方向は等間隔(t=i/ROCK_RING_SEGMENTS)。頂上リングだけ、北寄りの頂点を最大12m
    (海抜92mまで)持ち上げて自然の隆起を表現する。底面のキャップは水没して見えないため
    作らない(既存のTools/generate_msm_proxy.pyと同じ方針)。

    非対称プロファイルの角度thetaは、モジュールdocstringに書いたKurenaiEngine側の
    エンジン空間(X, Y=高さ, Z=奥行き。+Zが北)のXZ平面上でのatan2(z,x)として定義し
    (south_weight/north_weightの各ヘルパー関数もこのthetaを前提にしている)、頂点座標を
    作る最後の一歩でだけ、このスクリプト全体で使っているBlenderエクスポータの軸変換規則
    (gltf_x=blender_x, gltf_y=blender_z, gltf_z=-blender_y)の逆変換
    (blender_x=engine_x, blender_y=engine_z, blender_z=engine_y)を適用してBlenderの
    ネイティブ座標(Z-up、高さがZ)へ変換する(Xは反転せずZは反転する。理由は
    _engine_to_blenderのdocstring参照)。
    """
    bm = bmesh.new()

    # ROCK_LOCAL_CARVE_MIN_RADIUSのクランプが、この関数の頂点生成グリッド(リング×周方向)
    # の範囲でどれだけ効いたかを数えるため、呼び出し前後でグローバルカウンタのスナップショットを取る
    global _rock_local_carve_clamp_count
    clamp_count_before = _rock_local_carve_clamp_count

    rings = []
    for i in range(ROCK_RING_SEGMENTS + 1):
        t = i / ROCK_RING_SEGMENTS
        is_top = i == ROCK_RING_SEGMENTS
        ring_verts = []
        for j in range(ROCK_SIDES):
            theta = j / ROCK_SIDES * 2.0 * math.pi
            radius = _rock_radius(t, theta)
            engine_x = radius * math.cos(theta)
            engine_z = radius * math.sin(theta)
            engine_y = (ROCK_PLATEAU_Z + _rock_peak_offset(theta)) if is_top else (t * ROCK_PLATEAU_Z)
            blender_co = (engine_x, engine_z, engine_y)
            ring_verts.append(bm.verts.new(blender_co))
        rings.append(ring_verts)

    bm.verts.ensure_lookup_table()

    clamp_count_in_grid = _rock_local_carve_clamp_count - clamp_count_before
    total_grid_points = (ROCK_RING_SEGMENTS + 1) * ROCK_SIDES
    print(
        f"[INFO] 岩: ROCK_LOCAL_CARVE_MIN_RADIUS({ROCK_LOCAL_CARVE_MIN_RADIUS}m)のクランプが"
        f"効いた頂点: {clamp_count_in_grid}/{total_grid_points}"
    )

    # 側面(隣接リング・隣接角度を四角形でつなぐ。底面キャップは作らない)
    for i in range(ROCK_RING_SEGMENTS):
        for j in range(ROCK_SIDES):
            j_next = (j + 1) % ROCK_SIDES
            v_bl = rings[i][j]
            v_br = rings[i][j_next]
            v_tr = rings[i + 1][j_next]
            v_tl = rings[i + 1][j]
            bm.faces.new((v_bl, v_br, v_tr, v_tl))

    # 頂上台地を中心点への三角形ファンで塞ぐ(中心は南北の単純平均としてプラトー高さを使う)
    top_ring = rings[ROCK_RING_SEGMENTS]
    center = bm.verts.new((0.0, 0.0, ROCK_PLATEAU_Z))
    for j in range(ROCK_SIDES):
        j_next = (j + 1) % ROCK_SIDES
        bm.faces.new((center, top_ring[j], top_ring[j_next]))

    # 岩は全面Rockマテリアル
    _tag_new_faces(bm, 0, "Rock")

    # 巻き順が入力の周回向きに依存してしまうため、全体で向きが揃うよう外向きに正規化する
    bmesh.ops.recalc_face_normals(bm, faces=bm.faces[:])

    mesh = bpy.data.meshes.new("Rock")
    bm.to_mesh(mesh)
    bm.free()
    mesh.update()

    obj = bpy.data.objects.new("Rock", mesh)
    _link(obj)
    bpy.context.view_layer.objects.active = obj
    obj.select_set(True)

    # 自然の岩肌として滑らかにシェーディングする(城壁・修道院・尖塔は人工物のため
    # フラットシェーディングのままでよく、ここでは変更しない)
    bpy.ops.object.shade_smooth()

    # UV: build_island()側の_apply_box_projection_uv()が全パーツ結合後にワールド空間の
    # ボックス投影で作り直すため、ここでは何もしない(かつてはsmart_projectを呼んでいたが、
    # ボックス投影で上書きされるだけなので削除した)

    _add_rock_surface_detail(obj)

    return obj


def _engine_xz_to_blender_xy(engine_x, engine_z):
    """エンジン空間の水平座標(X, Z。+Zが北)を、このスクリプト全体で使っている
    Blenderエクスポータの軸変換規則の逆変換(blender_x=engine_x, blender_y=engine_z)で
    Blenderの水平面(X,Y)へ変換する(build_rockの頂点生成・_engine_to_blenderと同じ
    変換規則。Xは反転せず、Zは反転する。理由は_engine_to_blenderのdocstring参照)。
    """
    return engine_x, engine_z


def _rampart_radius(theta, extra_offset=0.0):
    """城壁関連パーツ(壁本体・天端の縁取り・持ち出し帯・塔・城門)に共通の半径基準。

    岩の表面(_rock_radius, t=WALL_REF_T)からWALL_OUTWARD_OFFSETだけ外側を城壁の基準線とし、
    extra_offsetでさらに外側(正の値)・内側(負の値)にずらす。
    """
    return _rock_radius(WALL_REF_T, theta) + WALL_OUTWARD_OFFSET + extra_offset


def _build_wall_merlons(name, z_bottom, thickness):
    """パラペットの上に狭間(クレネルの歯)を、弧に沿って等間隔に並べたオブジェクトを作る。

    z_bottom: theta(ラジアン)を受け取って歯の底面の高さを返す関数(パラペットの天端)。
    thickness: 壁と同じ厚み(Solidifyで内外へ均等に付ける)。

    弧長で等間隔に歩く(角度で等分すると、半径が場所によって違うため間隔が揃わない)。
    歯1つは弧に沿った4頂点の板をSolidifyで厚くしたもので、_build_wall_arc_stripと
    同じ作り方をする。歯の中は弧を細かく割って曲率に追随させる。
    """
    pitch = WALL_MERLON_WIDTH + WALL_MERLON_GAP
    if pitch <= 0.0 or WALL_MERLON_WIDTH <= 0.0:
        print(
            f"[ERROR] 狭間の寸法が不正です(幅={WALL_MERLON_WIDTH}m, 隙間={WALL_MERLON_GAP}m)。"
            f"WALL_MERLON_WIDTH/GAPを見直してください",
            file=sys.stderr,
        )
        raise ValueError("狭間の寸法が不正です")

    arc_start = math.radians(RAMPART_ARC_START_DEG)
    arc_end = math.radians(RAMPART_ARC_END_DEG)

    # 弧長を数値積分して、弧長 -> theta の対応表を作る
    samples = RAMPART_ARC_SEGMENTS * 8
    thetas = [arc_start + (arc_end - arc_start) * (i / samples) for i in range(samples + 1)]
    lengths = [0.0]
    for i in range(samples):
        r0, r1 = _rampart_radius(thetas[i]), _rampart_radius(thetas[i + 1])
        x0, z0 = r0 * math.cos(thetas[i]), r0 * math.sin(thetas[i])
        x1, z1 = r1 * math.cos(thetas[i + 1]), r1 * math.sin(thetas[i + 1])
        lengths.append(lengths[-1] + math.hypot(x1 - x0, z1 - z0))
    total = lengths[-1]

    def theta_at(length):
        # lengthsは単調増加なので線形探索で十分(samplesは高々数百)
        for i in range(samples):
            if lengths[i + 1] >= length:
                span = lengths[i + 1] - lengths[i]
                u = 0.0 if span <= 1e-9 else (length - lengths[i]) / span
                return thetas[i] + (thetas[i + 1] - thetas[i]) * u
        return thetas[-1]

    bm = bmesh.new()
    count = 0
    try:
        start = 0.0
        while start + WALL_MERLON_WIDTH <= total:
            # 歯1つを3分割して曲率に追随させる
            steps = 3
            bottom_verts = []
            top_verts = []
            for k in range(steps + 1):
                theta = theta_at(start + WALL_MERLON_WIDTH * k / steps)
                radius = _rampart_radius(theta)
                bx, by = _engine_xz_to_blender_xy(radius * math.cos(theta), radius * math.sin(theta))
                base_z = z_bottom(theta)
                bottom_verts.append(bm.verts.new((bx, by, base_z)))
                top_verts.append(bm.verts.new((bx, by, base_z + WALL_MERLON_HEIGHT)))
            for k in range(steps):
                bm.faces.new((bottom_verts[k], bottom_verts[k + 1],
                              top_verts[k + 1], top_verts[k]))
            count += 1
            start += pitch
    except Exception as error:  # noqa: BLE001
        print(f"[ERROR] 狭間の作成に失敗しました(#{count}): ({error})", file=sys.stderr)
        raise

    _tag_new_faces(bm, 0, "Masonry")
    bmesh.ops.recalc_face_normals(bm, faces=bm.faces[:])

    mesh = bpy.data.meshes.new(name)
    bm.to_mesh(mesh)
    bm.free()
    mesh.update()

    obj = bpy.data.objects.new(name, mesh)
    _link(obj)
    bpy.context.view_layer.objects.active = obj
    obj.select_set(True)

    modifier = obj.modifiers.new(name="Solidify", type='SOLIDIFY')
    modifier.thickness = thickness
    modifier.offset = 0.0
    modifier.use_rim = True
    try:
        bpy.ops.object.modifier_apply(modifier=modifier.name)
    except Exception as error:  # noqa: BLE001
        print(f"[ERROR] {name}のSolidifyモディファイアの適用に失敗しました: ({error})", file=sys.stderr)
        raise

    print(f"[INFO] 狭間: {count}個 (弧長{total:.0f}m 周期{pitch:.1f}m 歯{WALL_MERLON_WIDTH}m"
          f"/隙間{WALL_MERLON_GAP}m 高さ{WALL_MERLON_HEIGHT}m)")
    return obj


def _build_wall_arc_strip(name, extra_offset, z_bottom, z_top, thickness):
    """岩の表面沿いに、RAMPART_ARC_START_DEG〜RAMPART_ARC_END_DEGの弧・指定した高さ範囲・
    半径オフセット・厚みで帯状のジオメトリを1つ作る。城壁本体・天端の縁取り・持ち出し帯の
    3箇所で共通に使う。

    z_bottom/z_topはfloat定数、またはtheta(ラジアン)を受け取って高さを返す関数の
    どちらでもよい(壁の高さに緩急を持たせるWALL_HEIGHT_*用にbuild_rampart()から
    関数を渡せるようにするための拡張。天端の縁取り・持ち出し帯も、壁本体の高さが
    場所ごとに変わることに追従させたいため)。

    bmeshで弧に沿った2段(z_bottom, z_top)のリングを作って側面をつなぎ(ステップ2の
    build_rockと同じ要領)、Solidifyモディファイアで厚みを持たせる。閉じた円ではなく円弧
    なので、リングの両端(弧の始点・終点)は開いた境界のままになるが、Solidifyの
    リム(use_rim)が弧の両端・上下端をまとめて塞いでくれる。

    モディファイアはその場で適用してベイクする(build_rockのDisplaceと同じ理由: joinは
    アクティブオブジェクトのモディファイアを結合後のメッシュ全体に適用してしまうため、
    他パーツとjoinする前に確実に適用しておく必要がある)。
    """
    bm = bmesh.new()
    bottom_verts = []
    top_verts = []
    arc_start = math.radians(RAMPART_ARC_START_DEG)
    arc_end = math.radians(RAMPART_ARC_END_DEG)

    for i in range(RAMPART_ARC_SEGMENTS + 1):
        u = i / RAMPART_ARC_SEGMENTS
        theta = arc_start + (arc_end - arc_start) * u
        radius = _rampart_radius(theta, extra_offset)
        engine_x = radius * math.cos(theta)
        engine_z = radius * math.sin(theta)
        blender_x, blender_y = _engine_xz_to_blender_xy(engine_x, engine_z)
        zb = z_bottom(theta) if callable(z_bottom) else z_bottom
        zt = z_top(theta) if callable(z_top) else z_top
        bottom_verts.append(bm.verts.new((blender_x, blender_y, zb)))
        top_verts.append(bm.verts.new((blender_x, blender_y, zt)))

    for i in range(RAMPART_ARC_SEGMENTS):
        v_bl, v_br = bottom_verts[i], bottom_verts[i + 1]
        v_tl, v_tr = top_verts[i], top_verts[i + 1]
        bm.faces.new((v_bl, v_br, v_tr, v_tl))

    # 城壁本体・天端の縁取り・持ち出し帯はいずれも石造(Masonry)
    _tag_new_faces(bm, 0, "Masonry")

    bmesh.ops.recalc_face_normals(bm, faces=bm.faces[:])

    mesh = bpy.data.meshes.new(name)
    bm.to_mesh(mesh)
    bm.free()
    mesh.update()

    obj = bpy.data.objects.new(name, mesh)
    _link(obj)
    bpy.context.view_layer.objects.active = obj
    obj.select_set(True)

    modifier = obj.modifiers.new(name="Solidify", type='SOLIDIFY')
    modifier.thickness = thickness
    modifier.offset = 0.0  # 基準線に対して内外均等に厚みを付ける(決め値、内外の厳密な配分は不要)
    modifier.use_rim = True  # 弧の両端・上下端を塞ぐ
    modifier.show_viewport = True
    modifier.show_render = True

    try:
        bpy.ops.object.modifier_apply(modifier=modifier.name)
    except Exception as error:  # noqa: BLE001
        print(f"[ERROR] {name}のSolidifyモディファイアの適用に失敗しました: ({error})", file=sys.stderr)
        raise

    return obj


def _rampart_tangential_rotation_z(theta):
    """接線方向(弧に沿う向き)をローカルX軸に、半径方向をY軸に揃えるためのZ軸回りの回転角
    (ラジアン)。城門など、軸並行の直方体を弧の任意の角度に配置する際に使う。

    エンジン空間の接線ベクトルは(-sinθ, cosθ)(位置(r cosθ, r sinθ)のθ微分)。これを
    _engine_xz_to_blender_xyの規則(blender_x=engine_x, blender_y=engine_z)で変換すると
    そのまま(-sinθ, cosθ)になるので、Z軸回りの回転角はそのベクトルのatan2で求まる。

    【注意】この式は_engine_xz_to_blender_xyの符号と必ずセットで直すこと。
    過去に2回、軸変換の符号を変えたときにこの式の更新が漏れて門のカッターが
    ずれている(1回目はX反転の全廃時、2回目は南北の反転の修正時)。
    """
    return math.atan2(math.cos(theta), -math.sin(theta))


def _cut_gate(wall_obj, name, theta_deg, width, height):
    """指定角度theta_degの壁にBooleanで矩形の門を1つ抜く。

    theta=-90度(真南)はワールドの南(Blenderの+Y軸)と厳密に一致するため、カッター用の
    直方体を回転させずに軸並行のまま配置できるが、それ以外の角度(南東寄りの副次的な
    通用門など)では_rampart_tangential_rotation_zで弧の接線方向に合わせて回転させる
    必要がある。
    """
    theta = math.radians(theta_deg)
    radius = _rampart_radius(theta, 0.0)
    engine_x = radius * math.cos(theta)
    engine_z = radius * math.sin(theta)
    blender_x, blender_y = _engine_xz_to_blender_xy(engine_x, engine_z)
    rotation_z = _rampart_tangential_rotation_z(theta)

    # カッターの下端は壁本体のz_bottom(=WALL_BASE_Z_REF)ちょうどと一致させず、
    # 少し下まで延ばす(出典なしの決め値のマージン)。壁のz_bottomと厳密に同一平面上に
    # カッターの面を置くと、Booleanが同一平面の交差をうまく処理できず穴が実際には
    # 開かない(頂点だけ増えて面が残る)不具合が起きたため。GATE_BOTTOM_MARGIN分
    # 地面より下まで貫通させても、門は元々地面まで開いている想定のため見た目に影響しない
    z_bottom = WALL_BASE_Z_REF - GATE_BOTTOM_MARGIN
    z_top = WALL_BASE_Z_REF + height
    # 壁の厚み方向を確実に貫通させるための余裕を持った奥行き(出典なしの決め値)
    cutter_depth = WALL_THICKNESS * 4.0

    bpy.ops.mesh.primitive_cube_add(
        size=2.0,
        location=(blender_x, blender_y, (z_bottom + z_top) * 0.5),
    )
    cutter = bpy.context.active_object
    cutter.name = f"{name}Cutter"
    cutter.rotation_euler = (0.0, 0.0, rotation_z)
    cutter.scale = (width * 0.5, cutter_depth * 0.5, (z_top - z_bottom) * 0.5)

    modifier = wall_obj.modifiers.new(name=f"{name}Cut", type='BOOLEAN')
    modifier.operation = 'DIFFERENCE'
    modifier.object = cutter

    bpy.context.view_layer.objects.active = wall_obj
    try:
        bpy.ops.object.modifier_apply(modifier=modifier.name)
    except Exception as error:  # noqa: BLE001
        print(f"[ERROR] {name}のBoolean切り抜きに失敗しました: ({error})", file=sys.stderr)
        raise

    bpy.data.objects.remove(cutter, do_unlink=True)

    # Booleanが新しく作る切り口の面は、マテリアルを持たないカッター由来のため
    # material_index=0(=Rock)になる。城壁は全面Masonryなので、0の面を石造りへ付け直す
    # (実測で門1つあたり3面、計6面が岩のテクスチャで描かれていた)。
    # Booleanはメッシュを作り直すので面の同一性が失われ、_tag_faces_sinceは使えない
    masonry_index = _material_index("Masonry")
    retagged = 0
    for poly in wall_obj.data.polygons:
        if poly.material_index == 0:
            poly.material_index = masonry_index
            retagged += 1
    if retagged:
        print(f"[INFO] {name}: Booleanの切り口{retagged}面をMasonryへ付け直しました")


def _wall_height_control_points():
    """壁の弧(RAMPART_ARC_START_DEG〜RAMPART_ARC_END_DEG)をWALL_HEIGHT_SEGMENTS個の
    区間に分け、区間境界(WALL_HEIGHT_SEGMENTS+1個の点)ごとに固定シードの擬似乱数で
    WALL_HEIGHT_MIN〜MAXの高さを割り当てた制御点リストを返す。呼び出しのたびに同じ
    シードから生成するため、build_rampart()内で複数回呼んでも常に同じ結果になる。
    """
    rng = random.Random(WALL_HEIGHT_SEED)
    return [rng.uniform(WALL_HEIGHT_MIN, WALL_HEIGHT_MAX) for _ in range(WALL_HEIGHT_SEGMENTS + 1)]


def _wall_height_at(theta, control_points):
    """弧上の角度theta(ラジアン)における壁本体の高さを、区間境界の制御点から線形補間して
    求める(急激な段差を避け、区間境界でなめらかに繋がるようにするため)。
    """
    arc_start = math.radians(RAMPART_ARC_START_DEG)
    arc_end = math.radians(RAMPART_ARC_END_DEG)
    u = (theta - arc_start) / (arc_end - arc_start)
    u = min(max(u, 0.0), 1.0)

    segment_count = len(control_points) - 1
    scaled = u * segment_count
    index = min(int(scaled), segment_count - 1)
    local_u = scaled - index
    return control_points[index] + (control_points[index + 1] - control_points[index]) * local_u


def build_rampart():
    """城壁本体・天端の縁取り(パラペット)・持ち出し帯(マシクーリの簡略化)・城門2箇所の
    切り抜きをまとめて作る。塔は個別に名前を付ける必要があるためbuild_towers()で別に作る。

    壁本体の高さは場所ごとに緩急を持たせる(_wall_height_at参照)。天端の縁取り・
    持ち出し帯もこの高さに追従させ、壁本体から浮いたり埋まったりしないようにする。

    戻り値はbuild_island()でjoinする対象のBlenderオブジェクトのリスト。
    """
    # 修正パス確認用: 基準角度theta=-90°(南、カメラ側)での城壁の実際の半径・底面高さと、
    # 岩の水際(t=0)での半径との差(=城壁の外側に残る裸の岩の縁の幅の目安)をログに出す
    theta_ref = math.radians(-90.0)
    ref_wall_radius = _rampart_radius(theta_ref, 0.0)
    ref_rock_base_radius = _rock_radius(0.0, theta_ref)
    print(
        f"[INFO] 城壁: 基準角度theta=-90°(南)での半径={ref_wall_radius:.1f}m"
        f"(岩の水際t=0での半径={ref_rock_base_radius:.1f}m, 差={ref_rock_base_radius - ref_wall_radius:.1f}m)"
        f" 底面高さ(WALL_BASE_Z_REF)={WALL_BASE_Z_REF:.1f}m"
    )

    height_control_points = _wall_height_control_points()

    def wall_top(theta):
        return WALL_BASE_Z_REF + _wall_height_at(theta, height_control_points)

    wall = _build_wall_arc_strip(
        "Wall", 0.0,
        WALL_BASE_Z_REF, wall_top,
        WALL_THICKNESS,
    )
    _cut_gate(wall, "Gate", GATE_THETA_DEG, GATE_WIDTH, GATE_HEIGHT)
    _cut_gate(wall, "PosternGate", GATE2_THETA_DEG, GATE2_WIDTH, GATE2_HEIGHT)

    def ledge_top(theta):
        return wall_top(theta) + WALL_TOP_LEDGE_HEIGHT

    ledge = _build_wall_arc_strip(
        "WallTopLedge", 0.0,
        wall_top, ledge_top,
        WALL_THICKNESS,
    )

    # パラペットの上に狭間を並べる(WALL_MERLON_*参照)。歯と歯のあいだが空になり、
    # 天端が一直線ではなくなる
    merlons = _build_wall_merlons("WallMerlons", ledge_top, WALL_THICKNESS)

    def machicolation_bottom(theta):
        return wall_top(theta) - MACHICOLATION_BELOW_TOP_OFFSET

    def machicolation_top(theta):
        return machicolation_bottom(theta) + MACHICOLATION_HEIGHT

    machicolation = _build_wall_arc_strip(
        "Machicolation", MACHICOLATION_OUTWARD_OFFSET,
        machicolation_bottom, machicolation_top,
        MACHICOLATION_THICKNESS,
    )

    return [wall, ledge, merlons, machicolation]


def _build_square_tower(name, theta, radius_tower, height_tower, base_z):
    """ヴォーバン様式の四角い稜堡(TOWER_SQUARE_INDICESで指定した塔)を、接線方向・
    半径方向に軸を揃えた直方体としてbmeshで組み立てる。実物の稜堡は上部が平らな砲座の
    ため、円柱塔と違って屋根の円錐は付けない(_add_flat_box_to_bmeshは天面をキャップする
    ため、これだけで平らな天面になる)。
    """
    dir_x, dir_z = math.cos(theta), math.sin(theta)          # 半径方向(外向き)
    tan_x, tan_z = -math.sin(theta), math.cos(theta)         # 接線方向(弧に沿う向き)

    center_radius = _rampart_radius(theta, TOWER_OUTWARD_OFFSET)
    engine_x = center_radius * math.cos(theta)
    engine_z = center_radius * math.sin(theta)

    bm = bmesh.new()
    try:
        _add_flat_box_to_bmesh(
            bm,
            base=(engine_x, base_z, engine_z),
            along_dir=(tan_x, 0.0, tan_z),
            across_dir=(dir_x, 0.0, dir_z),
            depth=radius_tower * 2.0,
            width=radius_tower * 2.0,
            height=height_tower,
        )
    except Exception as error:  # noqa: BLE001
        print(f"[ERROR] 四角い塔({name})の作成に失敗しました: ({error})", file=sys.stderr)
        raise

    bmesh.ops.recalc_face_normals(bm, faces=bm.faces[:])

    mesh = bpy.data.meshes.new(name)
    bm.to_mesh(mesh)
    bm.free()
    mesh.update()

    obj = bpy.data.objects.new(name, mesh)
    _link(obj)
    return obj


def _add_tower_parapet_to_bmesh(bm, center_x, center_y, base_z, outer_radius, inner_radius,
                                height, segments):
    """塔の天端の砲座(平らな床)と、その縁を回る環状の胸壁をbmeshへ追加する。

    引数はBlenderのネイティブ座標(center_x/center_y=水平、base_z=床の高さ)。

    実物の城壁の塔は屋根が無く、天面は大砲を据えるための平らな床で、その縁に狭間付きの
    胸壁が回っている(参考写真c_aerial_se_goldenhour.jpg)。中身の詰まった円柱で代用すると
    天面が明るい円盤になって「杭」に見えてしまうため、床と胸壁を別に組んで
    **胸壁の内側に影の落ちる窪み**を作る。この窪みの暗さが、遠景で塔が筒として読める主因。

    胸壁は片面だけの筒にせず、外壁・天端・内壁の3面で厚みのある環にする
    (片面だと裏面が抜けて見えるため)。
    """
    top_z = base_z + height
    outer_bottom, outer_top, inner_top, inner_bottom = [], [], [], []
    for k in range(segments):
        angle = 2.0 * math.pi * k / segments
        cos_a, sin_a = math.cos(angle), math.sin(angle)
        ox = center_x + outer_radius * cos_a
        oy = center_y + outer_radius * sin_a
        ix = center_x + inner_radius * cos_a
        iy = center_y + inner_radius * sin_a
        outer_bottom.append(bm.verts.new((ox, oy, base_z)))
        outer_top.append(bm.verts.new((ox, oy, top_z)))
        inner_top.append(bm.verts.new((ix, iy, top_z)))
        inner_bottom.append(bm.verts.new((ix, iy, base_z)))
    bm.verts.ensure_lookup_table()

    for k in range(segments):
        n = (k + 1) % segments
        bm.faces.new((outer_bottom[k], outer_bottom[n], outer_top[n], outer_top[k]))  # 外壁
        bm.faces.new((outer_top[k], outer_top[n], inner_top[n], inner_top[k]))        # 天端
        bm.faces.new((inner_top[k], inner_top[n], inner_bottom[n], inner_bottom[k]))  # 内壁
    bm.faces.new(inner_bottom)  # 砲座の床(build_island()で三角形化されるためNGONでよい)


def build_towers():
    """城壁の弧(RAMPART_ARC_START_DEG〜RAMPART_ARC_END_DEG)の上に8基の塔を、両端を含めて
    等間隔に配置する。名前は史実の塔の名前(TOWER_NAMES)を配列順に割り当てただけで、
    実際の史実の配置順とは対応していない識別用のラベル。半径・高さは固定シードの擬似乱数で
    塔ごとに振り、TOWER_SQUARE_INDICESで指定したインデックスだけ四角い稜堡にする。

    円形の塔は円柱本体(天面・底面は作らない。底面は岩に埋め込まれて見えず、天面は胸壁の
    帯が覆うため)+ 天端の胸壁の帯を、四角い稜堡は_build_square_towerの直方体を
    1基ごとに1オブジェクトへ結合して返す。いずれも屋根は付けない。

    修正パス(ユーザー指摘「城壁の塔に屋根なんてない」を受けた参考写真の再確認): 以前は
    円形の塔にだけスレート葺きの円錐屋根を載せていたが、c_aerial_se_goldenhour.jpgを
    確認したところ城壁の塔はすべて屋根の無い平らな砲座だった。円錐屋根が付いているのは
    修道院側の小さな階段小塔だけで、城壁の塔には1基も無い。屋根を削除し、代わりに実物に
    あるとおり天端へ胸壁の帯を回す。_build_square_towerのdocstringには以前から
    「実物の稜堡は上部が平らな砲座のため屋根の円錐は付けない」と正しく書かれており、
    四角い稜堡だけが正しく円形の塔が間違っていた。

    修正パス(コーディネーター指摘、参考写真との並置での「塔が板に見える」調査で発見した
    不具合): 円形の塔は以前 bpy.ops.mesh.primitive_cylinder_add/primitive_cone_add で
    本体・屋根を別オブジェクトとして作り、それぞれの polygon.material_index を直接
    Masonry/SlateRoofへ設定してから bpy.ops.object.join() で結合していた。しかし
    どちらのオブジェクトも obj.data.materials(マテリアルスロットの実体)が空のままだったため、
    join()がスロットの無い material_index を解決できず全面が0(=ISLAND_MATERIALSの先頭=Rock)へ
    リセットされてしまい、本体・屋根とも常にRockの色で描画されていた
    (実測: probe_tower_material.pyでSlateRoof面数0を確認)。これが「壁の上の淡い色の
    板」に見えていた主因だったため、他パーツ(_add_octagon_turret_to_bmeshなど)と同じ
    bmesh.ops.create_cone + _tag_new_faces + 単一bmからのto_mesh方式へ書き換え、
    join()を使わずに材質を確実に反映させるようにした
    """
    arc_start = math.radians(RAMPART_ARC_START_DEG)
    arc_end = math.radians(RAMPART_ARC_END_DEG)
    tower_count = len(TOWER_NAMES)
    rng = random.Random(TOWER_SEED)
    # 塔の高さを城壁の高さへ追従させるため、壁と同じ制御点を引く
    # (_wall_height_control_pointsは固定シードなのでbuild_rampart()と同じ値になる)
    wall_control_points = _wall_height_control_points()

    towers = []
    for i, name in enumerate(TOWER_NAMES):
        u = i / (tower_count - 1)
        theta = arc_start + (arc_end - arc_start) * u
        radius_tower = rng.uniform(TOWER_RADIUS_MIN, TOWER_RADIUS_MAX)
        # 本体の天端がその位置の城壁の天端よりTOWER_ABOVE_WALL_MIN〜MAXだけ高くなる高さ
        height_tower = _wall_height_at(theta, wall_control_points) + rng.uniform(
            TOWER_ABOVE_WALL_MIN, TOWER_ABOVE_WALL_MAX
        )
        radius = _rampart_radius(theta, TOWER_OUTWARD_OFFSET)
        engine_x = radius * math.cos(theta)
        engine_z = radius * math.sin(theta)
        blender_x, blender_y = _engine_xz_to_blender_xy(engine_x, engine_z)
        base_z = WALL_BASE_Z_REF

        if i in TOWER_SQUARE_INDICES:
            tower_obj = _build_square_tower(name, theta, radius_tower, height_tower, base_z)
            bpy.context.view_layer.objects.active = tower_obj
            tower_obj.select_set(True)
            towers.append(tower_obj)
            continue

        try:
            bm = bmesh.new()

            # 円柱本体(天面・底面は作らない)。_add_octagon_turret_to_bmeshと同じ
            # bmesh.ops.create_coneをdiameter1==diameter2で使う(円柱として組み立てる)
            # bmは空なのでインデックス方式でも取りこぼしは起きないが、opsで作った面は
            # 常に集合差でタグ付けする方針に揃える(_tag_faces_sinceのdocstring参照)
            faces_before = set(bm.faces)
            body_matrix = Matrix.Translation((blender_x, blender_y, base_z + height_tower * 0.5))
            bmesh.ops.create_cone(
                bm, cap_ends=False, cap_tris=False, segments=TOWER_SIDES,
                diameter1=radius_tower * 2.0, diameter2=radius_tower * 2.0, depth=height_tower,
                matrix=body_matrix, calc_uvs=False,
            )
            _tag_faces_since(bm, faces_before, "Masonry")

            # 天端の砲座(平らな床)と、縁を回る環状の胸壁(Masonry)。屋根は付けない。
            # 直前に円柱をbmesh.ops.create_coneで作っているためインデックス基準は使えない
            parapet_faces_before = set(bm.faces)
            _add_tower_parapet_to_bmesh(
                bm, blender_x, blender_y, base_z + height_tower,
                outer_radius=radius_tower + TOWER_PARAPET_EXTRA_RADIUS,
                inner_radius=radius_tower - TOWER_PARAPET_INNER_INSET,
                height=TOWER_PARAPET_HEIGHT, segments=TOWER_SIDES,
            )
            _tag_faces_since(bm, parapet_faces_before, "Masonry")

            bmesh.ops.recalc_face_normals(bm, faces=bm.faces[:])

            mesh = bpy.data.meshes.new(name)
            bm.to_mesh(mesh)
            bm.free()
            mesh.update()

            tower_obj = bpy.data.objects.new(name, mesh)
            _link(tower_obj)
            bpy.context.view_layer.objects.active = tower_obj
            tower_obj.select_set(True)
        except Exception as error:  # noqa: BLE001
            print(f"[ERROR] 塔({name})の作成に失敗しました: ({error})", file=sys.stderr)
            raise

        towers.append(tower_obj)

    return towers


def _engine_to_blender(engine_x, engine_y, engine_z):
    """エンジン空間(X, Y=高さ, Z=奥行き。+Zが北)の任意の3次元座標を、build_rockの頂点生成と
    同じ軸変換規則(blender_x=engine_x, blender_y=engine_z, blender_z=engine_y)で
    Blenderのネイティブ座標(Z-up)へ変換する。

    【重要・南北の反転の原因と、この規則の根拠(実機とパッカーのソースで確定)】
    KurenaiPackerはAssimpへ aiProcess_ConvertToLeftHanded を渡している
    (Tools/KurenaiPacker/Source/ModelSource.cpp:336)。これは MakeLeftHanded |
    FlipUVs | FlipWindingOrder の複合で、取り込み時に Z を反転する(巻き順も一緒に
    反転するので面の向きは保たれる)。D3Dの左手系エンジンとして正しい設計。
    したがってこのプロジェクトの規約は
        エンジンワールドZ = -(glTFのZ)
    であり、ワールド z=-600 から +Z を向くカメラに写るのは「glTFの+Z側」になる。

    以前はここを blender_y = -engine_z としていたため gltf_z = +engine_z となり、
    モデルが南(engine_z<0)に置いた集落がエンジンでは北へ回って裏側になり、
    実機の南面には本来北・西にあるはずの樹木だけが見えていた。
    実測: 集落のglTF Z平均=-93.96(南)なのに、実機では南から見えず北から見えた。
    blender_y = +engine_z にすることで gltf_z = -engine_z となり、パッカーの反転と
    打ち消し合って エンジンワールド = エンジン空間 そのものになる。

    この変換は行列式が-1の鏡像だが、パッカー側も鏡像+巻き順反転なので合成すると
    行列式+1に戻り、エンジン内での向き・巻き順とも正しくなる。Blender内で
    recalc_face_normalsが外向きに揃えていることが前提(各build_*が呼んでいる)。

    Xは反転しない(以前Xを反転していたのは別の誤りで、実測で全廃済み)。
    現在の実測値: VillageWallのX平均=+50.28(東) / TreeCanopy=-30.90(西) / 尖塔・像=+0.00
    """
    return engine_x, engine_z, engine_y


def _add_house_to_bmesh(bm, base, along_dir, across_dir, width, depth, wall_height, roof_height,
                         wall_material="VillageWall", roof_material="SlateRoof"):
    """1棟分の家屋(箱の壁+切妻屋根)のジオメトリをbmeshへ追加する。

    along_dir: 屋根の棟線(道に沿う向き=奥行き方向)の単位ベクトル(エンジン空間、水平)
    across_dir: along_dirに直交する水平方向の単位ベクトル(幅方向)
    base: 家屋の底面中心のエンジン空間座標(X, Y=高さ, Z=奥行き)
    底面は岩に埋め込まれて見えないため作らない(rock/wall/towerと同じ方針)。
    wall_material: 壁4面+妻の三角2面に割り当てるマテリアル名。
    roof_material: 屋根の斜面2面に割り当てるマテリアル名。
    """
    base_x, base_y, base_z = base
    ax, _ay, az = along_dir
    cx, _cy, cz = across_dir

    def point(along, across, up):
        engine_x = base_x + along * ax + across * cx
        engine_y = base_y + up
        engine_z = base_z + along * az + across * cz
        return _engine_to_blender(engine_x, engine_y, engine_z)

    half_depth = depth * 0.5
    half_width = width * 0.5

    # 壁の底(4隅)
    a0 = bm.verts.new(point(-half_depth, -half_width, 0.0))
    a1 = bm.verts.new(point(half_depth, -half_width, 0.0))
    a2 = bm.verts.new(point(half_depth, half_width, 0.0))
    a3 = bm.verts.new(point(-half_depth, half_width, 0.0))

    # 壁の天端=軒(4隅)
    b0 = bm.verts.new(point(-half_depth, -half_width, wall_height))
    b1 = bm.verts.new(point(half_depth, -half_width, wall_height))
    b2 = bm.verts.new(point(half_depth, half_width, wall_height))
    b3 = bm.verts.new(point(-half_depth, half_width, wall_height))

    # 棟(むね。屋根の稜線の両端。alongの両端でacross=0)
    r0 = bm.verts.new(point(-half_depth, 0.0, wall_height + roof_height))
    r1 = bm.verts.new(point(half_depth, 0.0, wall_height + roof_height))

    first_wall_face = len(bm.faces)

    # 壁面(4面。各面の頂点は矩形の周を1周する順に並べる)
    bm.faces.new((a0, a1, b1, b0))  # across=-half_width側
    bm.faces.new((a2, a3, b3, b2))  # across=+half_width側
    bm.faces.new((a3, a0, b0, b3))  # along=-half_depth側(妻の下半分)
    bm.faces.new((a1, a2, b2, b1))  # along=+half_depth側(妻の下半分)

    # 切妻の妻面(三角形2枚。軒から棟までの上半分)。ここまでが壁材(wall_material)
    bm.faces.new((b0, b3, r0))
    bm.faces.new((b2, b1, r1))
    _tag_new_faces(bm, first_wall_face, wall_material)

    # 軒(のき)。屋根を壁より外へVILLAGE_EAVES_OVERHANGだけ張り出させ、その真下に
    # 水平な軒裏(そふぃっと)を作る。軒裏は真下を向くので直射日光が当たらず、
    # 参考写真の家にある「軒の下の濃い水平の線」になる。
    # 軒先の高さは壁の天端と同じにする(斜面を延長して下げると妻面の輪郭が
    # 五角形になり、既存の妻の三角形2枚が使えなくなるため。600m先では差は出ない)
    half_width_eaves = half_width + VILLAGE_EAVES_OVERHANG
    e0 = bm.verts.new(point(-half_depth, -half_width_eaves, wall_height))
    e1 = bm.verts.new(point(half_depth, -half_width_eaves, wall_height))
    e2 = bm.verts.new(point(half_depth, half_width_eaves, wall_height))
    e3 = bm.verts.new(point(-half_depth, half_width_eaves, wall_height))

    first_roof_face = len(bm.faces)

    # 屋根の斜面(2枚。矩形の周を1周する順)。軒先まで伸ばす
    bm.faces.new((e0, e1, r1, r0))  # across=-half_width側の斜面
    bm.faces.new((e3, e2, r1, r0))  # across=+half_width側の斜面
    # 軒裏(2枚。壁の天端から軒先までの水平な帯)
    bm.faces.new((b0, b1, e1, e0))
    bm.faces.new((b3, b2, e2, e3))
    # 軒の妻側の小口(4枚)。これを入れないと、妻の三角形の辺(b→棟)と
    # 軒先の辺(e→棟)・軒裏の辺(b→e)で囲まれた三角形が穴のまま残り、
    # 非多様体になってBlenderが落ちる(実測: EXCEPTION_ACCESS_VIOLATIONで3回とも失敗)
    bm.faces.new((b0, e0, r0))
    bm.faces.new((b3, r0, e3))
    bm.faces.new((b1, r1, e1))
    bm.faces.new((b2, e2, r1))
    _tag_new_faces(bm, first_roof_face, roof_material)


def _village_terrace_arc(terrace_index):
    """段indexから、その段が占める角度範囲(開始角度・終了角度、度)と、
    VILLAGE_ARC_START_DEG〜END_DEGの全幅に対する広さの比率(span_factor)を返す。

    下の段(terrace_index=0)ほど角度範囲いっぱいに広く(span_factor=1.0)、上の段
    (terrace_index=VILLAGE_TERRACE_COUNT-1)ほど狭くなる(最上段でVILLAGE_TERRACE_SPAN_TOP)よう
    線形に絞り込む。
    中心角度は段ごとに VILLAGE_TERRACE_CENTER_SHIFT_DEG まで西へずらす(同定数のコメント参照。
    以前は全段共通で、上の段が南東の一点に固まり中央が登れなかった)。
    """
    if VILLAGE_TERRACE_COUNT <= 1:
        u = 0.0
    else:
        u = terrace_index / (VILLAGE_TERRACE_COUNT - 1)
    span_factor = 1.0 - (1.0 - VILLAGE_TERRACE_SPAN_TOP) * u  # 最下段1.0→最上段SPAN_TOP

    arc_center_deg = (VILLAGE_ARC_START_DEG + VILLAGE_ARC_END_DEG) * 0.5
    arc_center_deg += VILLAGE_TERRACE_CENTER_SHIFT_DEG * u
    arc_half_deg = (VILLAGE_ARC_END_DEG - VILLAGE_ARC_START_DEG) * 0.5 * span_factor
    start_deg = arc_center_deg - arc_half_deg
    if start_deg < VILLAGE_ARC_START_DEG - 1e-6:
        # 西へずらしすぎると城壁の弧(RAMPART_ARC_START_DEG)より外へ家が出る
        print(f"[ERROR] 集落の段{terrace_index}が弧の西端を越えました"
              f"(開始={start_deg:.1f}度 < VILLAGE_ARC_START_DEG={VILLAGE_ARC_START_DEG:.1f}度)。"
              f"VILLAGE_TERRACE_CENTER_SHIFT_DEGを小さくしてください", file=sys.stderr)
        raise ValueError("集落の段が弧の西端を越えました")
    return start_deg, arc_center_deg + arc_half_deg, span_factor


def build_village():
    """岩の南東側の扇形区画に、同心円状のテラス(段)を積んで並ぶ家屋群(グランド・リュ)を
    1つのメッシュへまとめて作る。

    中世の人口300〜400人(fr.wikipedia)から、1棟あたり複数人〜1世帯として数十棟程度の
    規模にした以外に根拠は無く、寸法・段数は出典なしの決め値。実物は指定建造物だけで
    約60棟が隙間なく密着している(出典: French Moments)ため、参考写真pexels1.jpg/
    aerial11.jpg/aerial13.jpgで見られる密集した集落に近づける。

    当初は城壁の弧を折り返しながら登る理想螺旋だったが、岩を全周するため実物の
    「南東側の扇形区画に集落がまとまる」配置と合わず、教会が東西軸へ組み替わったのに
    合わせて廃止した(VILLAGE_ARC_*/VILLAGE_TERRACE_*参照)。同心円のテラス方式では
    棟線の向き(等高線の接線)が有限差分無しで直接求まるため、螺旋方式で起きていた
    折り返し境界での接線縮退も解消する。

    修正パス(タスクC): 「段の角度幅÷棟数」で等角度に家を並べる旧方式は、家の幅
    (VILLAGE_WIDTH_MIN/MAX)が間隔計算に一切使われず隙間と重なりが成り行きになり、
    遠目に「並んだ立方体」に見える不具合があった。段ごとに弧長(radius_ref×角度幅。
    radius_refは弧の中央のthetaでの_rock_radius)に沿って、家の幅ぶんずつ隙間
    VILLAGE_HOUSE_GAPを空けて詰めて置く方式に置き換えた。棟数は結果として弧長÷平均的な
    家の幅で決まる(段ごとの目標棟数を事前に決めていたVILLAGE_HOUSE_COUNT/
    _village_terrace_house_counts()は不要になったため削除した)。

    固定シードVILLAGE_SEEDからのPython標準randomモジュールによる決定論的な擬似乱数
    (Tools/generate_tidal_flat.pyと同じ考え方)で、各段内の家の寸法・張り出し量を
    機械的すぎないよう振る。
    """
    random.seed(VILLAGE_SEED)
    # 窓の間引き専用の乱数。グローバルのrandomを消費すると家・樹木の位置が全部動くため、
    # 独立したインスタンスを使う(ABBEY_FACADE_WINDOW_SEEDと同じ作法)
    window_rng = random.Random(VILLAGE_WINDOW_SEED)

    bm = bmesh.new()

    house_index = 0
    for terrace_index in range(VILLAGE_TERRACE_COUNT):
        start_deg, end_deg, _span_factor = _village_terrace_arc(terrace_index)
        terrace_u = (
            terrace_index / (VILLAGE_TERRACE_COUNT - 1) if VILLAGE_TERRACE_COUNT > 1 else 0.0
        )
        height_t_terrace = (
            VILLAGE_TERRACE_HEIGHT_T_START
            + (VILLAGE_TERRACE_HEIGHT_T_END - VILLAGE_TERRACE_HEIGHT_T_START) * terrace_u
        )

        theta_start_rad = math.radians(start_deg)
        theta_end_rad = math.radians(end_deg)
        theta_center_rad = (theta_start_rad + theta_end_rad) * 0.5
        radius_ref = _rock_radius(height_t_terrace, theta_center_rad)
        arc_length = radius_ref * (theta_end_rad - theta_start_rad)
        if arc_length <= 0.0:
            print(f"[ERROR] 集落の段{terrace_index}の弧長が0以下です(arc_length={arc_length})", file=sys.stderr)
            raise ValueError(f"集落の段{terrace_index}の弧長が0以下です")

        s = 0.0
        while True:
            width = random.uniform(VILLAGE_WIDTH_MIN, VILLAGE_WIDTH_MAX)
            if s + width > arc_length:
                break

            theta_house = theta_start_rad + (s + width * 0.5) / radius_ref

            depth = random.uniform(VILLAGE_DEPTH_MIN, VILLAGE_DEPTH_MAX)
            wall_height = random.uniform(VILLAGE_WALL_HEIGHT_MIN, VILLAGE_WALL_HEIGHT_MAX)
            # 屋根の高さは妻方向の幅に比例させる(絶対値だと幅の広い家で勾配が寝てしまう)
            roof_height = width * random.uniform(
                VILLAGE_ROOF_PITCH_RATIO_MIN, VILLAGE_ROOF_PITCH_RATIO_MAX
            )
            outward_offset = random.uniform(VILLAGE_OUTWARD_OFFSET_MIN, VILLAGE_OUTWARD_OFFSET_MAX)

            radius = _rock_radius(height_t_terrace, theta_house) + outward_offset
            base_engine_x = radius * math.cos(theta_house)
            base_engine_z = radius * math.sin(theta_house)
            # 非頂上リングの高さは_rock_radiusと同じくtheta非依存(build_rock参照)
            base_engine_y = height_t_terrace * ROCK_PLATEAU_Z

            # 同心円(等高線)の接線方向。有限差分は不要で直接求まる
            tangent_x, tangent_z = -math.sin(theta_house), math.cos(theta_house)
            across_x, across_z = math.cos(theta_house), math.sin(theta_house)

            # 修正パス(コーディネーター指摘、段階2): 各家が接線方向をそのまま向くと
            # 屋根が同心円の輪に見えてしまうため、水平面内(エンジンのXZ平面)で±
            # VILLAGE_YAW_JITTER_DEGのランダムなヨーを両方向ベクトルへ同時に加える。
            # along_dir/across_dirのY成分は常に0のままなので屋根の稜線は水平を保つ
            # (傾かない)。家どうしが多少重なっても実物の密集した集落に近いため許容する
            yaw_rad = math.radians(random.uniform(-VILLAGE_YAW_JITTER_DEG, VILLAGE_YAW_JITTER_DEG))
            cos_yaw, sin_yaw = math.cos(yaw_rad), math.sin(yaw_rad)
            tangent_x, tangent_z = (
                tangent_x * cos_yaw - tangent_z * sin_yaw,
                tangent_x * sin_yaw + tangent_z * cos_yaw,
            )
            across_x, across_z = (
                across_x * cos_yaw - across_z * sin_yaw,
                across_x * sin_yaw + across_z * cos_yaw,
            )

            # マテリアルのバリエーション(位置・寸法の抽選順序を変えないよう、既存の乱数
            # 呼び出しの後、_add_house_to_bmesh呼び出し直前=このループの最後に追加で引く)。
            # 修正パス(参考写真c_village_roofs_walls.jpgの精査): 写真の集落は濃灰のスレート・
            # 淡い石板・褐色の瓦が入り混じり、壁も石積みと白い漆喰が同程度に混ざっている。
            # 70/30・85/15では混ざり方が足りず全体が一色に見えていた
            # 屋根: 60% SlateRoof / 40% TileRoof。壁: 72% VillageWall / 28% VillagePlaster
            roof_material = "SlateRoof" if random.random() < 0.6 else "TileRoof"
            wall_material = "VillageWall" if random.random() < 0.72 else "VillagePlaster"

            # 【修正・棟の向きと詰め方の食い違い】以前は along_dir(=棟線の向き)に
            # 常に接線方向(通りに沿う向き)を渡していた。これには2つの誤りがあった:
            #   1) 空撮c_aerial_se_goldenhour.jpgを真上から読むと、棟の向きは通りと直交・
            #      平行がおよそ半々に混在する。一方に固定すると実物のばらつきが出ない
            #   2) 弧に沿ってwidth(5〜9m)ずつ詰めて置いているのに、家が弧方向に占めるのは
            #      along_dir側のdepth(6〜12m)だったため、隣家へ平均2mずつ食い込んでいた
            #      (詰め方に使う寸法と、実際に弧方向を占める寸法の不一致)
            # 向きを抽選しつつ、どちらの向きでも「弧方向の寸法=詰め方に使ったwidth」に
            # なるよう寸法を割り当て直すことで、2つとも同時に解消する。
            # 抽選は乱数の消費順を乱さないよう、既存の抽選の最後(マテリアルの後)に置く
            gable_to_street = random.random() < VILLAGE_GABLE_TO_STREET_RATIO
            if gable_to_street:
                # 妻を通りに向ける: 棟は半径方向(斜面の奥へ)
                house_along = (across_x, 0.0, across_z)
                house_across = (tangent_x, 0.0, tangent_z)
                house_depth, house_width = depth, width   # depth=半径方向 / width=弧方向
            else:
                # 棟が通りに沿う: 弧方向を占めるのはdepth側なので、そこへwidthを渡す
                house_along = (tangent_x, 0.0, tangent_z)
                house_across = (across_x, 0.0, across_z)
                house_depth, house_width = width, depth   # depth=弧方向 / width=半径方向

            try:
                _add_house_to_bmesh(
                    bm,
                    base=(base_engine_x, base_engine_y, base_engine_z),
                    along_dir=house_along,
                    across_dir=house_across,
                    width=house_width,
                    depth=house_depth,
                    wall_height=wall_height,
                    roof_height=roof_height,
                    wall_material=wall_material,
                    roof_material=roof_material,
                )

                # 煙突。棟(むね)の上に立てて屋根の一直線を刻む。参考写真の家並みは
                # 煙突と屋根の段差で稜線がぎざぎざになっており、これが空との境で
                # いちばん目に付く小さな凹凸になっている。
                # 乱数は窓と同じ専用インスタンス(グローバルのrandomは消費しない)
                if window_rng.random() < VILLAGE_CHIMNEY_PROBABILITY:
                    # 棟の長さ方向の位置。両端を避けて中ほどへ置く
                    along_offset = house_depth * (window_rng.uniform(-0.30, 0.30))
                    chimney_base = (
                        base_engine_x + house_along[0] * along_offset,
                        base_engine_y + wall_height + roof_height - VILLAGE_CHIMNEY_WIDTH * 0.5,
                        base_engine_z + house_along[2] * along_offset,
                    )
                    _add_flat_box_to_bmesh(
                        bm, base=chimney_base, along_dir=house_along, across_dir=house_across,
                        depth=VILLAGE_CHIMNEY_WIDTH, width=VILLAGE_CHIMNEY_WIDTH,
                        height=VILLAGE_CHIMNEY_HEIGHT + VILLAGE_CHIMNEY_WIDTH * 0.5,
                        side_material=wall_material, top_material="SlateRoof",
                    )

                # カメラ側(=島の中心から見て外向き)の1面にだけ窓を並べる。
                # 妻を通りに向ける棟では along_dir が半径方向、そうでない棟では
                # across_dir が半径方向なので、外向きの面と、その面に沿う水平方向が入れ替わる
                if gable_to_street:
                    outward = house_along          # 半径方向(外向き)
                    face_along = house_across      # 面に沿う水平方向
                    face_length, face_offset = house_width, house_depth * 0.5
                else:
                    outward = house_across
                    face_along = house_along
                    face_length, face_offset = house_depth, house_width * 0.5

                # 窓の下端の高さ。壁の上端(軒)から窓1つ分の余裕を残す
                sill_ys = []
                sill = VILLAGE_WINDOW_SILL_FIRST
                while sill + VILLAGE_WINDOW_HEIGHT + 0.5 <= wall_height:
                    sill_ys.append(base_engine_y + sill)
                    sill += VILLAGE_WINDOW_FLOOR_HEIGHT

                if sill_ys and face_length > VILLAGE_WINDOW_WIDTH * 2.0 + 0.5:
                    face_center = (
                        base_engine_x + outward[0] * face_offset,
                        base_engine_y,
                        base_engine_z + outward[2] * face_offset,
                    )
                    wall_start = (
                        face_center[0] - face_along[0] * face_length * 0.5,
                        face_center[1],
                        face_center[2] - face_along[2] * face_length * 0.5,
                    )
                    _add_window_wall_to_bmesh(
                        bm, wall_start=wall_start, along_dir=face_along,
                        wall_length=face_length, outward_dir=outward, floor_base_ys=sill_ys,
                        width=VILLAGE_WINDOW_WIDTH, height=VILLAGE_WINDOW_HEIGHT,
                        thin_rng=window_rng, skip_probability=VILLAGE_WINDOW_SKIP_PROBABILITY,
                        spacing=VILLAGE_WINDOW_SPACING, protrusion=VILLAGE_WINDOW_PROTRUSION,
                    )
            except Exception as error:  # noqa: BLE001
                print(f"[ERROR] 集落の家屋(段{terrace_index}, #{house_index})の作成に失敗しました: ({error})", file=sys.stderr)
                raise
            house_index += 1

            s += width + VILLAGE_HOUSE_GAP

    print(f"[INFO] 集落: 総棟数={house_index}")

    bmesh.ops.recalc_face_normals(bm, faces=bm.faces[:])

    mesh = bpy.data.meshes.new("Village")
    bm.to_mesh(mesh)
    bm.free()
    mesh.update()

    obj = bpy.data.objects.new("Village", mesh)
    _link(obj)
    bpy.context.view_layer.objects.active = obj
    obj.select_set(True)
    return obj


def _add_tree_to_bmesh(bm, base_engine, height, crown_radius,
                        trunk_material="TreeTrunk", crown_material="TreeCanopy"):
    """1本の木(細い円柱の幹+1本ごとに形の違う樹冠)のジオメトリをbmeshへ追加する。

    base_engine: 木の根元のエンジン空間座標(X, Y=高さ, Z=奥行き)。600m先のカメラでは
    葉の1枚1枚は視認できないため、幹・樹冠とも低ポリのシルエットのみで表現する
    (bmesh.ops.create_cone/create_uvsphereを直接使い、オブジェクト生成のオーバーヘッドを避ける)。
    height: 木全体のおおよその高さ(m)。幹の高さはこの30%(VEGETATION_TRUNK_HEIGHT_RATIO)
    crown_radius: 樹冠の水平方向の半径(m)。縦方向はVEGETATION_CROWN_SQUASHで潰す
    trunk_material/crown_material: 幹・樹冠にそれぞれ割り当てるマテリアル名。

    樹冠のばらつき(楕円化・向き・傾き・輪郭のノイズ)は**この関数の中で乱数を引く**。
    呼び出しは4箇所(塊・下草・中腹の帯・海際)あるが、ここで完結させれば呼び出し側を
    一切変えずに全部へ効く。乱数は呼び出し側と同じrandomモジュール(VEGETATION_SEEDで
    初期化済み)から引くので再現性は保たれる。
    """
    base_x, base_y, base_z = _engine_to_blender(*base_engine)
    trunk_height = height * VEGETATION_TRUNK_HEIGHT_RATIO

    # 幹: 半径一定の細い円柱。create_coneは原点中心・ローカルZ軸沿いに生成されるため、
    # 底面が根元に来るよう高さの半分だけZ方向へ平行移動する
    faces_before = set(bm.faces)
    trunk_matrix = Matrix.Translation((base_x, base_y, base_z + trunk_height * 0.5))
    bmesh.ops.create_cone(
        bm,
        cap_ends=True,
        cap_tris=True,
        segments=VEGETATION_TRUNK_SEGMENTS,
        diameter1=VEGETATION_TRUNK_RADIUS * 2.0,
        diameter2=VEGETATION_TRUNK_RADIUS * 2.0,
        depth=trunk_height,
        matrix=trunk_matrix,
        calc_uvs=False,
    )
    _tag_faces_since(bm, faces_before, trunk_material)

    # 樹冠: 真球を作ってから、1本ごとに違う楕円体へ変形する(先にスケール、次に回転、
    # 最後に平行移動する順で行列を合成する。Matrix.__matmul__は右側から順に適用される)。
    # 幹の上端へ少しめり込ませて接続を自然に見せる。
    # 【順序が重要】縦に潰しただけの回転体は鉛直軸まわりに対称なので、先に水平断面を
    # 楕円にしておかないと、いくら回しても見た目が変わらない
    crown_vertical_radius = crown_radius * VEGETATION_CROWN_SQUASH
    crown_center_z = base_z + trunk_height + crown_vertical_radius * (1.0 - VEGETATION_CROWN_OVERLAP)

    aspect_x = random.uniform(VEGETATION_CROWN_ASPECT_MIN, VEGETATION_CROWN_ASPECT_MAX)
    aspect_y = random.uniform(VEGETATION_CROWN_ASPECT_MIN, VEGETATION_CROWN_ASPECT_MAX)
    yaw = random.uniform(0.0, 2.0 * math.pi)
    tilt_azimuth = random.uniform(0.0, 2.0 * math.pi)
    tilt = math.radians(random.uniform(0.0, VEGETATION_CROWN_TILT_MAX_DEG))
    # 輪郭のノイズの位相。木ごとに変えることで、同じ式でも凹凸の出る向きが変わる
    noise_phase_a = random.uniform(0.0, 2.0 * math.pi)
    noise_phase_b = random.uniform(0.0, 2.0 * math.pi)

    tilt_axis = Vector((math.cos(tilt_azimuth), math.sin(tilt_azimuth), 0.0))
    crown_matrix = (
        Matrix.Translation((base_x, base_y, crown_center_z))
        @ Matrix.Rotation(tilt, 4, tilt_axis)
        @ Matrix.Rotation(yaw, 4, 'Z')
        @ Matrix.Diagonal((aspect_x, aspect_y, VEGETATION_CROWN_SQUASH, 1.0))
    )
    faces_before = set(bm.faces)
    crown = bmesh.ops.create_uvsphere(
        bm,
        u_segments=VEGETATION_CROWN_U_SEGMENTS,
        v_segments=VEGETATION_CROWN_V_SEGMENTS,
        diameter=crown_radius * 2.0,
        matrix=crown_matrix,
        calc_uvs=False,
    )
    _tag_faces_since(bm, faces_before, crown_material)

    # 輪郭をでこぼこにする。中心からの方向で決まる滑らかな関数で半径を押し引きするので、
    # 頂点ごとに独立な乱数(=とげとげの球になる)ではなく、数個のふくらみになる。
    # bmesh.ops.create_uvsphereの戻り値に新しい頂点が入っているため、面のタグ付けのような
    # 集合差を取る必要はない
    crown_center = Vector((base_x, base_y, crown_center_z))
    for vert in crown["verts"]:
        offset = vert.co - crown_center
        length = offset.length
        if length < 1.0e-6:
            continue
        direction = offset / length
        theta = math.atan2(direction.y, direction.x)
        phi = math.acos(max(-1.0, min(1.0, direction.z)))
        lump = math.sin(3.0 * theta + noise_phase_a) * math.sin(2.0 * phi + noise_phase_b)
        vert.co = crown_center + offset * (1.0 + VEGETATION_CROWN_NOISE * lump)


def _normalize_deg(deg):
    """角度(度)を(-180, 180]の範囲に正規化する(周回する角度どうしの範囲比較のための補助)。"""
    normalized = deg % 360.0
    if normalized > 180.0:
        normalized -= 360.0
    return normalized


def _theta_deg_in_village_lower_arc(theta_deg, height_t):
    """その高さで集落が実際に占める角度範囲にthetaが入っているかどうかを判定する
    (植生クラスタの中心が集落と重ならないようにするための補助)。

    【修正・集落の東西の端の上に裸地の楔ができていた】以前は高さに関わらず弧の全幅
    (VILLAGE_ARC_START_DEG〜END_DEG)を除外していた。しかし集落は_village_terrace_arcで
    上の段ほど弧が狭まり(最下段1.0倍→最上段0.5倍)、上の段は弧の中央付近しか占めない。
    そのため「集落が無いのに樹木も置けない」領域が弧の両端の上側にでき、
    空撮(c_aerial_se_goldenhour.jpgとの並置)で楔形の裸地として見えていた。
    _village_terrace_arcと同じ絞り込みを高さから逆算して適用する。
    """
    if height_t >= VILLAGE_TERRACE_HEIGHT_T_END:
        return False

    span = VILLAGE_TERRACE_HEIGHT_T_END - VILLAGE_TERRACE_HEIGHT_T_START
    u = 0.0 if span <= 0.0 else (height_t - VILLAGE_TERRACE_HEIGHT_T_START) / span
    u = min(max(u, 0.0), 1.0)
    span_factor = 1.0 - 0.5 * u  # _village_terrace_arcと同じ絞り込み

    arc_center = (VILLAGE_ARC_START_DEG + VILLAGE_ARC_END_DEG) * 0.5
    arc_half = (VILLAGE_ARC_END_DEG - VILLAGE_ARC_START_DEG) * 0.5 * span_factor

    normalized = _normalize_deg(theta_deg)
    return (arc_center - arc_half) <= normalized <= (arc_center + arc_half)


def build_vegetation():
    """岩の斜面・城壁内側・集落の隙間に木を配置した植生を1つのメッシュへまとめて作る。

    修正パス(参考写真c_aerial_se_lowtide.jpg/c_aerial_sw_daylight.jpgの精査)で、
    木を岩の斜面へ等間隔にばらまく旧方式(密/疎の一様スキャッタ)は「白い斜面の水玉模様」に
    見えると指摘されたため、塊(クラスタ)方式へ置き換えた。塊の中心をVEGETATION_
    CLUSTER_COUNT個、theta・height_tの範囲から一様に選び、各塊にrandom.randint本の木を
    中心からのガウス分布のずれで生やすことで、樹冠どうしが重なって地面が透けない塊として
    島のほぼ全周(VEGETATION_CLUSTER_THETA_START_DEG〜END_DEG)の中腹を覆う。加えて
    集落の隙間・城壁の内側には低い下草(understory)を一様スキャッタで配置する。木の本数・
    寸法・配置範囲はいずれも出典なしの決め値。固定シードVEGETATION_SEEDからのPython標準
    randomモジュールによる決定論的な擬似乱数(build_village等と同じ考え方)で位置・寸法を振る。
    """
    random.seed(VEGETATION_SEED)

    bm = bmesh.new()
    tree_count = 0
    cluster_skipped_count = 0

    try:
        # クラスタ(塊): 塊の中心をVEGETATION_CLUSTER_COUNT個選び、各塊にrandom.randint
        # (MIN,MAX)本の木を、中心からガウス分布でずらして生やす。theta・height_tは範囲外に
        # 出ると岩の表面から浮いてしまうため、必ず有効範囲へクランプする。
        # 修正パス(タスクB): 集落域(南〜東の下部)に落ちた中心は引き直す(決定論性を保つため
        # 乱数の消費順は「引き直しも含めて必ずrandom.uniform×2を呼ぶ」形で揃える)
        for cluster_index in range(VEGETATION_CLUSTER_COUNT):
            cluster_theta_deg = None
            cluster_height_t = None
            for _attempt in range(VEGETATION_CLUSTER_VILLAGE_AVOID_MAX_RETRIES):
                theta_candidate = random.uniform(
                    VEGETATION_CLUSTER_THETA_START_DEG, VEGETATION_CLUSTER_THETA_END_DEG
                )
                height_t_candidate = random.uniform(
                    VEGETATION_CLUSTER_HEIGHT_T_MIN, VEGETATION_CLUSTER_HEIGHT_T_MAX
                )
                if _theta_deg_in_village_lower_arc(theta_candidate, height_t_candidate):
                    continue
                cluster_theta_deg = theta_candidate
                cluster_height_t = height_t_candidate
                break

            if cluster_theta_deg is None:
                cluster_skipped_count += 1
                print(
                    f"[WARNING] 植生クラスタ#{cluster_index}: 集落域(theta="
                    f"[{VILLAGE_ARC_START_DEG},{VILLAGE_ARC_END_DEG}], height_t<"
                    f"{VILLAGE_TERRACE_HEIGHT_T_END})を避ける抽選が"
                    f"{VEGETATION_CLUSTER_VILLAGE_AVOID_MAX_RETRIES}回失敗したためスキップします"
                )
                continue

            trees_in_cluster = random.randint(
                VEGETATION_TREES_PER_CLUSTER_MIN, VEGETATION_TREES_PER_CLUSTER_MAX
            )

            for _ in range(trees_in_cluster):
                theta_deg = cluster_theta_deg + random.gauss(0.0, VEGETATION_CLUSTER_THETA_SPREAD_DEG)
                theta_deg = min(
                    max(theta_deg, VEGETATION_CLUSTER_THETA_START_DEG), VEGETATION_CLUSTER_THETA_END_DEG
                )
                height_t = cluster_height_t + random.gauss(0.0, VEGETATION_CLUSTER_HEIGHT_T_SPREAD)
                height_t = min(
                    max(height_t, VEGETATION_CLUSTER_HEIGHT_T_MIN), VEGETATION_CLUSTER_HEIGHT_T_MAX
                )
                theta = math.radians(theta_deg)

                outward_offset = random.uniform(
                    VEGETATION_CLUSTER_OUTWARD_OFFSET_MIN, VEGETATION_CLUSTER_OUTWARD_OFFSET_MAX
                )
                height = random.uniform(VEGETATION_HEIGHT_MIN, VEGETATION_HEIGHT_MAX)
                crown_radius = random.uniform(VEGETATION_CROWN_RADIUS_MIN, VEGETATION_CROWN_RADIUS_MAX)

                radius = _rock_radius(height_t, theta) + outward_offset
                base_engine_x = radius * math.cos(theta)
                base_engine_z = radius * math.sin(theta)
                base_engine_y = height_t * ROCK_PLATEAU_Z

                _add_tree_to_bmesh(
                    bm,
                    base_engine=(base_engine_x, base_engine_y, base_engine_z),
                    height=height,
                    crown_radius=crown_radius,
                )
                tree_count += 1

        # 内訳報告用のスナップショット(ループの中身は変えず、境界でtree_countを控えるだけ)
        cluster_tree_count = tree_count

        # 下草(understory): 集落の隙間・城壁の内側に一様スキャッタ。木の高さはVEGETATION_
        # HEIGHT_MIN/MAXの下半分になるようrandom.uniform(MIN, (MIN+MAX)*0.5)を使う
        understory_height_max = (VEGETATION_HEIGHT_MIN + VEGETATION_HEIGHT_MAX) * 0.5
        for _ in range(VEGETATION_UNDERSTORY_COUNT):
            theta = math.radians(
                random.uniform(VEGETATION_CLUSTER_THETA_START_DEG, VEGETATION_CLUSTER_THETA_END_DEG)
            )
            height_t = random.uniform(VEGETATION_UNDERSTORY_HEIGHT_T_MIN, VEGETATION_UNDERSTORY_HEIGHT_T_MAX)
            outward_offset = random.uniform(
                VEGETATION_UNDERSTORY_OUTWARD_OFFSET_MIN, VEGETATION_UNDERSTORY_OUTWARD_OFFSET_MAX
            )
            height = random.uniform(VEGETATION_HEIGHT_MIN, understory_height_max)
            crown_radius = random.uniform(VEGETATION_CROWN_RADIUS_MIN, VEGETATION_CROWN_RADIUS_MAX)

            radius = _rock_radius(height_t, theta) + outward_offset
            base_engine_x = radius * math.cos(theta)
            base_engine_z = radius * math.sin(theta)
            base_engine_y = height_t * ROCK_PLATEAU_Z

            _add_tree_to_bmesh(
                bm,
                base_engine=(base_engine_x, base_engine_y, base_engine_z),
                height=height,
                crown_radius=crown_radius,
            )
            tree_count += 1

        # 内訳報告用のスナップショット(ループの中身は変えず、境界でtree_countを控えるだけ)
        understory_tree_count = tree_count - cluster_tree_count

        # 中腹の緑の帯(belt): 集落上端〜修道院基礎下端の層に、既存のクラスタと違い
        # 角度を絞らず全周(-180度〜180度)から塊の中心を抽選する。帯の下端
        # (VEGETATION_BELT_HEIGHT_T_MIN=0.44)は集落の上端
        # (VILLAGE_TERRACE_HEIGHT_T_END=0.36)より上なので、集落を避ける抽選は不要
        # (参考写真では西〜北の樹林とは別に、集落のすぐ上に全周の庭・並木の帯がある)。
        # ※この前提は集落の上端を上げると崩れる。VILLAGE_TERRACE_HEIGHT_T_ENDを
        #   0.44以上にする場合は、ここにも_theta_deg_in_village_lower_arcの判定を入れること
        # 既存のクラスタ・下草の2ループの後に置くことで、乱数の消費順を変えず既存の木の
        # 配置に影響しないようにする(先に置くと既存の木が全部動いてしまうため必ず最後に置く)
        belt_tree_count = 0
        for _ in range(VEGETATION_BELT_COUNT):
            belt_theta_deg = random.uniform(-180.0, 180.0)
            belt_height_t = random.uniform(VEGETATION_BELT_HEIGHT_T_MIN, VEGETATION_BELT_HEIGHT_T_MAX)

            trees_in_belt_cluster = random.randint(
                VEGETATION_BELT_TREES_PER_CLUSTER_MIN, VEGETATION_BELT_TREES_PER_CLUSTER_MAX
            )

            for _ in range(trees_in_belt_cluster):
                theta_deg = belt_theta_deg + random.gauss(0.0, VEGETATION_BELT_THETA_SPREAD_DEG)
                height_t = belt_height_t + random.gauss(0.0, VEGETATION_BELT_HEIGHT_T_SPREAD)
                height_t = min(max(height_t, VEGETATION_BELT_HEIGHT_T_MIN), VEGETATION_BELT_HEIGHT_T_MAX)
                theta = math.radians(theta_deg)

                outward_offset = random.uniform(
                    VEGETATION_BELT_OUTWARD_OFFSET_MIN, VEGETATION_BELT_OUTWARD_OFFSET_MAX
                )
                height = random.uniform(VEGETATION_HEIGHT_MIN, VEGETATION_HEIGHT_MAX)
                crown_radius = random.uniform(VEGETATION_CROWN_RADIUS_MIN, VEGETATION_CROWN_RADIUS_MAX)

                radius = _rock_radius(height_t, theta) + outward_offset
                base_engine_x = radius * math.cos(theta)
                base_engine_z = radius * math.sin(theta)
                base_engine_y = height_t * ROCK_PLATEAU_Z

                _add_tree_to_bmesh(
                    bm,
                    base_engine=(base_engine_x, base_engine_y, base_engine_z),
                    height=height,
                    crown_radius=crown_radius,
                )
                tree_count += 1
                belt_tree_count += 1

        # 海際の樹林(北〜北西の裾)。
        # 【追加の根拠・裸地を数値で特定した】書き出したglTFを方位36分割×高さ12分割で
        # 「岩以外の頂点がゼロのセル」を数えたところ、432セル中の裸地は31セルで、
        # まとまって残っていたのは モデル方位120〜150度(北西)の t=0.00〜0.30 だけだった。
        # ここは城壁の弧(RAMPART_ARC_START_DEG=-195〜END_DEG=65)から外れる区間で、
        # 実物どおり城壁が無い。ただし参考写真c_north_whole_lowtide.jpgでは、その斜面は
        # 海際まで途切れない森になっており、砂色の裸地にはなっていない。
        # クラスタは全周へ一様に撒くため統計的な穴が残る。城壁の無い区間の裾だけを狙って
        # 低い帯を足し、測定で見つかった穴を確実に埋める。
        # 既存の3ループの後に置き、乱数の消費順を変えない(先に置くと既存の木が全部動く)
        shore_tree_count = 0
        for _ in range(VEGETATION_SHORE_COUNT):
            shore_theta_deg = random.uniform(
                VEGETATION_SHORE_THETA_START_DEG, VEGETATION_SHORE_THETA_END_DEG
            )
            shore_height_t = random.uniform(
                VEGETATION_SHORE_HEIGHT_T_MIN, VEGETATION_SHORE_HEIGHT_T_MAX
            )

            trees_in_shore_cluster = random.randint(
                VEGETATION_SHORE_TREES_PER_CLUSTER_MIN, VEGETATION_SHORE_TREES_PER_CLUSTER_MAX
            )

            for _ in range(trees_in_shore_cluster):
                theta_deg = shore_theta_deg + random.gauss(0.0, VEGETATION_BELT_THETA_SPREAD_DEG)
                height_t = shore_height_t + random.gauss(0.0, VEGETATION_BELT_HEIGHT_T_SPREAD)
                height_t = min(
                    max(height_t, VEGETATION_SHORE_HEIGHT_T_MIN), VEGETATION_SHORE_HEIGHT_T_MAX
                )
                theta = math.radians(theta_deg)

                outward_offset = random.uniform(
                    VEGETATION_BELT_OUTWARD_OFFSET_MIN, VEGETATION_BELT_OUTWARD_OFFSET_MAX
                )
                height = random.uniform(VEGETATION_HEIGHT_MIN, VEGETATION_HEIGHT_MAX)
                crown_radius = random.uniform(VEGETATION_CROWN_RADIUS_MIN, VEGETATION_CROWN_RADIUS_MAX)

                radius = _rock_radius(height_t, theta) + outward_offset
                base_engine_x = radius * math.cos(theta)
                base_engine_z = radius * math.sin(theta)
                base_engine_y = height_t * ROCK_PLATEAU_Z

                _add_tree_to_bmesh(
                    bm,
                    base_engine=(base_engine_x, base_engine_y, base_engine_z),
                    height=height,
                    crown_radius=crown_radius,
                )
                tree_count += 1
                shore_tree_count += 1
    except Exception as error:  # noqa: BLE001
        print(f"[ERROR] 植生(木#{tree_count})の作成に失敗しました: ({error})", file=sys.stderr)
        raise

    bmesh.ops.recalc_face_normals(bm, faces=bm.faces[:])

    # 三角形数の見積もり(凸多角形前提のn-2近似。実際のquads_convert_to_trisの結果とは
    # 厳密には一致しないが目安としては十分)をログへ出す
    tri_estimate = sum(max(len(f.verts) - 2, 0) for f in bm.faces)
    print(
        f"[INFO] 植生: 木{tree_count}本"
        f"(クラスタ{VEGETATION_CLUSTER_COUNT}塊(うち集落回避でスキップ{cluster_skipped_count}塊)"
        f"={cluster_tree_count}本"
        f"+下草{understory_tree_count}本"
        f"+中腹の帯{VEGETATION_BELT_COUNT}塊={belt_tree_count}本"
        f"+海際の樹林{VEGETATION_SHORE_COUNT}塊={shore_tree_count}本)"
        f" 頂点数={len(bm.verts)} 三角形数(概算)={tri_estimate}"
        f" (1本あたり約{tri_estimate / max(tree_count, 1):.1f})"
    )

    mesh = bpy.data.meshes.new("Vegetation")
    bm.to_mesh(mesh)
    bm.free()
    mesh.update()

    obj = bpy.data.objects.new("Vegetation", mesh)
    _link(obj)
    bpy.context.view_layer.objects.active = obj
    obj.select_set(True)
    return obj


def build_slope_terraces():
    """中腹の等高線状の擁壁(段々の庭園・テラス)を1つのメッシュにまとめて作る。

    参考写真c_aerial_sw_daylight.jpgで見える、集落の上端から修道院基礎の間の斜面に
    水平方向に何本も走る石の擁壁の線に対応する(出典なしの決め値)。SLOPE_TERRACE_
    HEIGHT_TSの各高さtについて、岩の等高線(_rock_radius(t, theta))に沿って開いた弧
    (閉じた輪ではない)の帯状の壁を1本作る。底面は岩に埋め込まれて見えないため作らない。
    """
    bm = bmesh.new()

    arc_start = math.radians(SLOPE_TERRACE_ARC_START_DEG)
    arc_end = math.radians(SLOPE_TERRACE_ARC_END_DEG)

    try:
        for t in SLOPE_TERRACE_HEIGHT_TS:
            base_y = t * ROCK_PLATEAU_Z
            top_y = base_y + SLOPE_TERRACE_WALL_HEIGHT

            inner_verts = []
            outer_verts_bottom = []
            outer_verts_top = []
            inner_verts_top = []
            for i in range(SLOPE_TERRACE_SEGMENTS + 1):
                u = i / SLOPE_TERRACE_SEGMENTS
                theta = arc_start + (arc_end - arc_start) * u
                radius = _rock_radius(t, theta)
                inner_x = radius * math.cos(theta)
                inner_z = radius * math.sin(theta)
                # 放射方向(外向き)へSLOPE_TERRACE_THICKNESSだけ張り出した外側の輪郭
                dir_x, dir_z = math.cos(theta), math.sin(theta)
                outer_x = inner_x + dir_x * SLOPE_TERRACE_THICKNESS
                outer_z = inner_z + dir_z * SLOPE_TERRACE_THICKNESS

                inner_verts.append(bm.verts.new(_engine_to_blender(inner_x, base_y, inner_z)))
                inner_verts_top.append(bm.verts.new(_engine_to_blender(inner_x, top_y, inner_z)))
                outer_verts_bottom.append(bm.verts.new(_engine_to_blender(outer_x, base_y, outer_z)))
                outer_verts_top.append(bm.verts.new(_engine_to_blender(outer_x, top_y, outer_z)))

            first_face = len(bm.faces)
            # 開いた弧なので、i と i+1 のペアをrange(n-1)で回す(閉じた輪のように
            # 最後の点と最初の点をつながない)
            for i in range(SLOPE_TERRACE_SEGMENTS):
                # 内側面(岩の表面側)
                bm.faces.new((
                    inner_verts[i], inner_verts[i + 1], inner_verts_top[i + 1], inner_verts_top[i],
                ))
                # 外側面(視認される側)
                bm.faces.new((
                    outer_verts_bottom[i], outer_verts_bottom[i + 1],
                    outer_verts_top[i + 1], outer_verts_top[i],
                ))
                # 天端
                bm.faces.new((
                    inner_verts_top[i], outer_verts_top[i], outer_verts_top[i + 1], inner_verts_top[i + 1],
                ))
            _tag_new_faces(bm, first_face, "Masonry")
    except Exception as error:  # noqa: BLE001
        print(f"[ERROR] 中腹の等高線状の擁壁の作成に失敗しました: ({error})", file=sys.stderr)
        raise

    bmesh.ops.recalc_face_normals(bm, faces=bm.faces[:])

    # 三角形数の見積もり(build_vegetation等と同じ形式)
    tri_estimate = sum(max(len(f.verts) - 2, 0) for f in bm.faces)
    print(
        f"[INFO] 中腹の擁壁: {len(SLOPE_TERRACE_HEIGHT_TS)}段"
        f" 頂点数={len(bm.verts)} 三角形数(概算)={tri_estimate}"
    )

    mesh = bpy.data.meshes.new("SlopeTerraces")
    bm.to_mesh(mesh)
    bm.free()
    mesh.update()

    obj = bpy.data.objects.new("SlopeTerraces", mesh)
    _link(obj)
    bpy.context.view_layer.objects.active = obj
    obj.select_set(True)
    return obj


def _add_flat_box_to_bmesh(bm, base, along_dir, across_dir, depth, width, height,
                            side_material="Masonry", top_material="Masonry"):
    """底面は作らず天面はキャップする直方体をbmeshへ追加する(陸屋根のラ・メルヴェイユ・
    控え壁・飛梁の柱など、切妻屋根を持たない箱型パーツに使う)。

    引数の意味は_add_house_to_bmeshと同じ(along_dir方向にdepth、across_dir方向にwidth)。
    底面は岩や他パーツに埋め込まれて見えないため作らない(rock/wall/village houseと同じ方針)。
    side_material: 側面4面に割り当てるマテリアル名。top_material: 天面(陸屋根)に
    割り当てるマテリアル名(天面だけ別のマテリアルにしたい場合に使う)。
    """
    base_x, base_y, base_z = base
    ax, _ay, az = along_dir
    cx, _cy, cz = across_dir

    def point(along, across, up):
        engine_x = base_x + along * ax + across * cx
        engine_y = base_y + up
        engine_z = base_z + along * az + across * cz
        return _engine_to_blender(engine_x, engine_y, engine_z)

    half_depth = depth * 0.5
    half_width = width * 0.5

    a0 = bm.verts.new(point(-half_depth, -half_width, 0.0))
    a1 = bm.verts.new(point(half_depth, -half_width, 0.0))
    a2 = bm.verts.new(point(half_depth, half_width, 0.0))
    a3 = bm.verts.new(point(-half_depth, half_width, 0.0))
    b0 = bm.verts.new(point(-half_depth, -half_width, height))
    b1 = bm.verts.new(point(half_depth, -half_width, height))
    b2 = bm.verts.new(point(half_depth, half_width, height))
    b3 = bm.verts.new(point(-half_depth, half_width, height))

    first_side_face = len(bm.faces)
    bm.faces.new((a0, a1, b1, b0))
    bm.faces.new((a2, a3, b3, b2))
    bm.faces.new((a3, a0, b0, b3))
    bm.faces.new((a1, a2, b2, b1))
    _tag_new_faces(bm, first_side_face, side_material)

    first_top_face = len(bm.faces)
    bm.faces.new((b0, b1, b2, b3))  # 天面(陸屋根)
    _tag_new_faces(bm, first_top_face, top_material)


def _add_window_to_bmesh(bm, base, along_dir, outward_dir,
                          width=WINDOW_WIDTH, height=WINDOW_HEIGHT, protrusion=WINDOW_PROTRUSION,
                          material="WindowGlass"):
    """壁面のゴシック窓を1つ、外側へわずかに飛び出す薄い縦長の箱としてbmeshへ追加する
    (Booleanで壁に穴を開けると処理が重く破綻しやすいための代替表現。承認済み計画の方針)。

    base: 窓の底辺中央の、壁表面上のエンジン空間座標。along_dir: 壁面に沿う水平方向の
    単位ベクトル(窓の幅方向)。outward_dir: 壁面から外向きの水平方向の単位ベクトル
    (窓の飛び出し方向)。_add_flat_box_to_bmeshは中心基準(along_dir方向にdepthの半分ずつ)
    のため、baseをoutward_dirへprotrusionの半分だけずらし、箱の近い面が壁面に接するように
    調整する。material: 窓の面すべて(側面+天面)に割り当てるマテリアル名。実物の窓は
    暗い開口部のため、既定を壁と同じMasonryではなく専用のWindowGlassにする(修正パス:
    レビューでabbey_closeup.pngで壁より明るい縦縞に見えると指摘されたため)。
    """
    base_x, base_y, base_z = base
    ox, _oy, oz = outward_dir
    shifted_base = (base_x + ox * protrusion * 0.5, base_y, base_z + oz * protrusion * 0.5)
    _add_flat_box_to_bmesh(
        bm, base=shifted_base, along_dir=along_dir, across_dir=outward_dir,
        depth=width, width=protrusion, height=height,
        side_material=material, top_material=material,
    )


def _add_window_wall_to_bmesh(bm, wall_start, along_dir, wall_length, outward_dir, floor_base_ys,
                               width=WINDOW_WIDTH, height=WINDOW_HEIGHT, thin_rng=None,
                               skip_probability=0.0, spacing=WINDOW_HORIZONTAL_SPACING,
                               protrusion=WINDOW_PROTRUSION):
    """壁の1面に沿ってWINDOW_HORIZONTAL_SPACING間隔で窓を並べる(横方向)。floor_base_ysに
    複数の高さを指定すれば、同じ横位置に階ごとの窓を追加する(縦方向)。

    wall_start: 壁の一端(窓を並べ始める側)の、壁面上のエンジン空間座標(高さ成分は
    floor_base_ysで上書きするため任意でよい)。along_dir: 壁に沿う方向の単位ベクトル。
    wall_length: 壁の長さ(along_dir方向)。outward_dir: 壁面から外向きの単位ベクトル。
    width/height: 窓1つの幅・高さ(既定はWINDOW_WIDTH/WINDOW_HEIGHTで、指定すれば
    ラ・メルヴェイユのような専用寸法の窓にも流用できる。修正パス: MERVEILLE_WINDOW_*参照)。

    thin_rng/skip_probability: 窓をランダムに間引いて、揃った格子に見えるのを崩すための
    任意指定(thin_rngはrandom.Randomインスタンス)。既定は間引かない。
    ラ・メルヴェイユの実物は太い控え壁のあいだに縦長の開口が規則的に並ぶので、
    そちらは既定のまま(間引かない)にすること。付属建築の南面だけ間引く。
    """
    margin = width
    span = wall_length - margin * 2.0
    if span <= 0.0:
        print(f"[ERROR] 窓を並べる壁の長さが不足しています(wall_length={wall_length})", file=sys.stderr)
        raise ValueError("窓を並べる壁の長さが不足しています")
    count = max(2, int(span / spacing) + 1)

    start_x, _start_y, start_z = wall_start
    ax, _ay, az = along_dir
    for floor_base_y in floor_base_ys:
        for i in range(count):
            if thin_rng is not None and thin_rng.random() < skip_probability:
                continue
            u = i / (count - 1)
            offset = margin + span * u
            window_base = (start_x + ax * offset, floor_base_y, start_z + az * offset)
            _add_window_to_bmesh(
                bm, base=window_base, along_dir=along_dir, outward_dir=outward_dir,
                width=width, height=height, protrusion=protrusion,
            )


def _apse_pinnacle_height(angle):
    """内陣の小尖塔の高さ。後陣の先端(東)へ向かって低くする(APSE_PINNACLE_EAST_TAPER参照)。

    angle: 後陣の中心から見た方位(ラジアン)。0が張り出しの先端(+X=東)、
    ±π/2が交差部側(西)。
    """
    height = APSE_PINNACLE_HEIGHT * (1.0 - APSE_PINNACLE_EAST_TAPER * math.cos(angle))
    if height <= 0.0:
        print(
            f"[ERROR] 内陣の小尖塔の高さが0以下になりました(angle={math.degrees(angle):.1f}度, "
            f"height={height:.2f}m)。APSE_PINNACLE_EAST_TAPERは1.0未満にしてください",
            file=sys.stderr,
        )
        raise ValueError("内陣の小尖塔の高さが0以下です")
    return height


def _add_pinnacle_to_bmesh(bm, base, size=PINNACLE_BASE_SIZE, height=PINNACLE_HEIGHT):
    """控え壁の上に乗せる小尖塔(四角錐)を1つbmeshへ追加する(承認済み計画の方針。
    石の花などの装飾は600m先では見えないため省略し、単純な四角錐で表現する)。

    base: 四角錐の底面中心の、控え壁の天端におけるエンジン空間座標。
    """
    base_x, base_y, base_z = base
    half = size * 0.5

    corners_engine = [
        (base_x - half, base_y, base_z - half),
        (base_x + half, base_y, base_z - half),
        (base_x + half, base_y, base_z + half),
        (base_x - half, base_y, base_z + half),
    ]
    verts = [bm.verts.new(_engine_to_blender(*c)) for c in corners_engine]
    apex = bm.verts.new(_engine_to_blender(base_x, base_y + height, base_z))

    bm.faces.new((verts[0], verts[1], verts[2], verts[3]))  # 底面(通常は控え壁本体に埋もれるが念のため作る)
    for i in range(4):
        i_next = (i + 1) % 4
        bm.faces.new((verts[i], verts[i_next], apex))


def _add_apse_to_bmesh(bm, center_x, center_z, radius, base_y, wall_height, roof_height, segments=16,
                        wall_material="Masonry", roof_material="SlateRoof"):
    """後陣(内陣)。半円柱を垂直に立てたような簡略形状をbmeshへ追加する(周歩廊・放射状
    礼拝堂は600m先のカメラでは見えないため省略する簡略化。承認済み計画の方針)。

    center_xを直径線(平らな背面、翼廊に接続する側)の中心とし、+X方向(東)へ半円が
    張り出す(教会が東西軸になったことに伴い、旧+Z(北)張り出しから組み替えた)。
    角度は-90°(南)→0°(東、張り出しの先端)→+90°(北)の順にたどる。
    wall_material: 曲面の壁+背面の壁に割り当てるマテリアル名。roof_material: 屋根に
    割り当てるマテリアル名。
    """
    half_pi = math.pi * 0.5
    bottom_curve = []
    top_curve = []
    for i in range(segments + 1):
        u = i / segments
        angle = -half_pi + math.pi * u
        x = center_x + radius * math.cos(angle)
        z = center_z + radius * math.sin(angle)
        bottom_curve.append(bm.verts.new(_engine_to_blender(x, base_y, z)))
        top_curve.append(bm.verts.new(_engine_to_blender(x, base_y + wall_height, z)))

    first_wall_face = len(bm.faces)

    # 曲面の壁
    for i in range(segments):
        bm.faces.new((bottom_curve[i], bottom_curve[i + 1], top_curve[i + 1], top_curve[i]))

    # 背面の壁(直径側、平面。翼廊と少し重なる想定だが単体でも壁として成立させる)
    bm.faces.new((bottom_curve[-1], bottom_curve[0], top_curve[0], top_curve[-1]))
    _tag_new_faces(bm, first_wall_face, wall_material)

    first_roof_face = len(bm.faces)

    # 屋根: 中心の少し上の頂点への三角形ファン(身廊よりやや低い簡易屋根)
    ridge_apex = bm.verts.new(_engine_to_blender(center_x, base_y + wall_height + roof_height, center_z))
    for i in range(segments):
        bm.faces.new((top_curve[i], top_curve[i + 1], ridge_apex))
    bm.faces.new((top_curve[-1], top_curve[0], ridge_apex))
    _tag_new_faces(bm, first_roof_face, roof_material)

    # タスク3: 壁の上端(曲面部)に沿ってAPSE_PINNACLE_COUNT本の小尖塔を等間隔配置する
    # (参考写真で内陣に林立して見える小尖塔の表現)。マテリアルは明示的にMasonryでタグ付けする
    # (_add_pinnacle_to_bmeshはマテリアルを自分でタグ付けしないため)
    first_pinnacle_face = len(bm.faces)
    for i in range(APSE_PINNACLE_COUNT):
        # 飛梁の列と投影が重ならないよう半区間ずらす(APSE_PINNACLE_ANGLE_STAGGER参照)。
        # 端をはみ出さないよう、ずらしたあとの u は 0〜1 に収める
        u = min(max((i + 0.5 + APSE_PINNACLE_ANGLE_STAGGER) / APSE_PINNACLE_COUNT, 0.0), 1.0)
        angle = -half_pi + math.pi * u
        x = center_x + radius * math.cos(angle)
        z = center_z + radius * math.sin(angle)
        _add_pinnacle_to_bmesh(bm, base=(x, base_y + wall_height, z),
                               size=APSE_PINNACLE_BASE_SIZE,
                               height=_apse_pinnacle_height(angle))
    _tag_new_faces(bm, first_pinnacle_face, "Masonry")


def _add_flying_buttresses_to_bmesh(bm, center_x, center_z, base_y):
    """後陣の周りに飛梁(柱+斜めの薄い板)をFLYING_BUTTRESS_COUNT基、半円に沿って
    等間隔配置する(承認済み計画の方針)。柱の上端にはピナクル(小尖塔)を乗せる。
    """
    half_pi = math.pi * 0.5
    wall_top_y = base_y + APSE_WALL_HEIGHT
    pier_top_y = base_y + FLYING_BUTTRESS_PIER_HEIGHT
    # 斜めの梁は柱の天端ではなく、そこからFLYING_BUTTRESS_BEAM_PIER_DROPだけ下がった点へ
    # 取り付ける(壁側のほうが高く、外側へ下る本来の向きにするため。定数のコメント参照)
    beam_pier_y = pier_top_y - FLYING_BUTTRESS_BEAM_PIER_DROP
    if beam_pier_y >= wall_top_y:
        print(
            f"[WARNING] 飛梁の梁が壁側({wall_top_y:.1f}m)より柱側({beam_pier_y:.1f}m)のほうが高く、"
            f"外側へ上る不自然な向きになっています。FLYING_BUTTRESS_BEAM_PIER_DROPを見直してください"
        )
    half_beam = FLYING_BUTTRESS_BEAM_WIDTH * 0.5

    for i in range(FLYING_BUTTRESS_COUNT):
        u = (i + 0.5) / FLYING_BUTTRESS_COUNT  # 両端(妻面の付け根)に重ならないよう半区間ずらす
        angle = -half_pi + math.pi * u
        # 後陣は_add_apse_to_bmeshと同じく+X(東)へ張り出すため、半径方向・接線方向も
        # それに合わせる(角度の定義もangle=0が張り出しの先端(+X)になるよう揃える)
        dir_x, dir_z = math.cos(angle), math.sin(angle)      # 後陣中心から外向きの半径方向
        tan_x, tan_z = -math.sin(angle), math.cos(angle)     # 半径方向と直交する接線方向

        wall_x = center_x + APSE_RADIUS * dir_x
        wall_z = center_z + APSE_RADIUS * dir_z
        pier_x = center_x + (APSE_RADIUS + FLYING_BUTTRESS_PIER_OFFSET) * dir_x
        pier_z = center_z + (APSE_RADIUS + FLYING_BUTTRESS_PIER_OFFSET) * dir_z

        first_buttress_face = len(bm.faces)
        try:
            # 柱(垂直の角柱)
            _add_flat_box_to_bmesh(
                bm,
                base=(pier_x, base_y, pier_z),
                along_dir=(tan_x, 0.0, tan_z),
                across_dir=(dir_x, 0.0, dir_z),
                depth=FLYING_BUTTRESS_PIER_THICKNESS,
                width=FLYING_BUTTRESS_PIER_THICKNESS,
                height=FLYING_BUTTRESS_PIER_HEIGHT,
            )

            # 斜めの薄い板(後陣の壁上部から柱の上端へ)
            wall_left = bm.verts.new(_engine_to_blender(
                wall_x + half_beam * tan_x, wall_top_y, wall_z + half_beam * tan_z))
            wall_right = bm.verts.new(_engine_to_blender(
                wall_x - half_beam * tan_x, wall_top_y, wall_z - half_beam * tan_z))
            pier_left = bm.verts.new(_engine_to_blender(
                pier_x + half_beam * tan_x, beam_pier_y, pier_z + half_beam * tan_z))
            pier_right = bm.verts.new(_engine_to_blender(
                pier_x - half_beam * tan_x, beam_pier_y, pier_z - half_beam * tan_z))
            bm.faces.new((wall_left, wall_right, pier_right, pier_left))

            # 柱の天端に細く高い小尖塔を乗せる(内陣専用の寸法。APSE_PINNACLE_*参照)。
            # 高さは後陣の先端(東)へ向かって落とす(APSE_PINNACLE_EAST_TAPER参照)
            _add_pinnacle_to_bmesh(bm, base=(pier_x, pier_top_y, pier_z),
                                   size=APSE_PINNACLE_BASE_SIZE,
                                   height=_apse_pinnacle_height(angle))
            # 柱・斜めの薄い板・ピナクルはいずれもMasonry(_add_flat_box_to_bmeshの柱は
            # 既定でMasonryだが、薄い板・ピナクルにはマテリアル引数が無いため一括で上書きする)
            _tag_new_faces(bm, first_buttress_face, "Masonry")
        except Exception as error:  # noqa: BLE001
            print(f"[ERROR] 飛梁(#{i})の作成に失敗しました: ({error})", file=sys.stderr)
            raise


def _find_rock_t_for_radius(theta, radius, point_label="", caller_label="修道院基礎の輪郭点"):
    """角度theta(ラジアン)の方向で、_rock_radius(t, theta)==radiusとなる高さパラメータt
    (0=底面, 1=頂上台地)を二分探索で求める(_rock_radiusはtに対して単調減少)。

    radiusが岩の裾(t=0)の半径以上、つまり指定点が岩の外側にある場合はログを出して
    t=0(地面)へフォールバックする。radiusが頂上台地(t=1)の半径以下の場合は、指定点が
    既に頂上台地の内側にあるということなのでt=1(壁の高さ0)を返す。

    caller_label: エラーメッセージに出す呼び出し元の名前。以前はbuild_abbey_substructure
    専用だったため「修道院基礎の輪郭点」が固定で埋め込まれており、他から呼ぶと
    見当違いのログが出る状態だった。既定値は従来の呼び出し元に合わせてある。
    """
    r_at_0 = _rock_radius(0.0, theta)
    r_at_1 = _rock_radius(1.0, theta)
    if radius >= r_at_0:
        print(
            f"[ERROR] {caller_label}{point_label}が岩の外側にあります"
            f"(radius={radius:.1f} >= 岩の裾radius={r_at_0:.1f}, theta={math.degrees(theta):.1f}°)。"
            f"t=0(地面)にフォールバックします",
            file=sys.stderr,
        )
        return 0.0
    if radius <= r_at_1:
        return 1.0

    lo, hi = 0.0, 1.0
    for _ in range(40):  # 2^-40の精度で十分収束する
        mid = (lo + hi) * 0.5
        if _rock_radius(mid, theta) > radius:
            lo = mid
        else:
            hi = mid
    return (lo + hi) * 0.5


def _add_abbey_substructure_buttresses(bm, points, bottom_ys, top_ys, center_x, center_z, label=""):
    """修道院の垂直基礎構造(1段分)の周に沿って、ABBEY_BUTTRESS_SPACING間隔で控え壁を配置する。

    points/bottom_ys/top_ysは輪郭の頂点(x,z)・その頂点での壁の下端・上端の高さのリスト
    (build_abbey_substructureで計算済みのものをそのまま渡す。top_ysは定数でも頂点ごとの
    リストでもよい)。頂点間は辺の長さに沿って線形補間した位置・高さに配置するため、
    輪郭の分割数(ABBEY_SUBSTRUCTURE_SIDES)より細かい間隔で控え壁を配置できる。
    """
    n_pts = len(points)
    top_ys_list = top_ys if hasattr(top_ys, "__len__") else [top_ys] * n_pts
    edge_lengths = []
    for i in range(n_pts):
        i_next = (i + 1) % n_pts
        dx = points[i_next][0] - points[i][0]
        dz = points[i_next][1] - points[i][1]
        edge_lengths.append(math.hypot(dx, dz))
    perimeter = sum(edge_lengths)
    if perimeter <= 0.0:
        print(f"[ERROR] 修道院基礎({label})の輪郭の周長が0です。控え壁の配置をスキップします", file=sys.stderr)
        return

    count = max(1, round(perimeter / ABBEY_BUTTRESS_SPACING))
    for k in range(count):
        target = perimeter * k / count
        cum = 0.0
        for i in range(n_pts):
            edge_length = edge_lengths[i]
            if cum + edge_length < target and i != n_pts - 1:
                cum += edge_length
                continue

            i_next = (i + 1) % n_pts
            local_u = 0.0 if edge_length <= 0.0 else min(max((target - cum) / edge_length, 0.0), 1.0)
            px = points[i][0] + (points[i_next][0] - points[i][0]) * local_u
            pz = points[i][1] + (points[i_next][1] - points[i][1]) * local_u
            by = bottom_ys[i] + (bottom_ys[i_next] - bottom_ys[i]) * local_u
            ty = top_ys_list[i] + (top_ys_list[i_next] - top_ys_list[i]) * local_u

            ex, ez = points[i_next][0] - points[i][0], points[i_next][1] - points[i][1]
            elen = math.hypot(ex, ez)
            if elen < 1.0e-6:
                break
            tan_x, tan_z = ex / elen, ez / elen

            dx, dz = px - center_x, pz - center_z
            dlen = math.hypot(dx, dz)
            out_x, out_z = (dx / dlen, dz / dlen) if dlen > 1.0e-6 else (1.0, 0.0)

            wall_height = ty - by
            if wall_height <= 0.1:
                # 岩の頂上台地にほぼ達している箇所(壁がほぼ無い)には控え壁を置かない
                break

            try:
                _add_flat_box_to_bmesh(
                    bm,
                    base=(
                        px + out_x * ABBEY_BUTTRESS_PROTRUSION * 0.5,
                        by,
                        pz + out_z * ABBEY_BUTTRESS_PROTRUSION * 0.5,
                    ),
                    along_dir=(tan_x, 0.0, tan_z),
                    across_dir=(out_x, 0.0, out_z),
                    depth=ABBEY_BUTTRESS_WIDTH,
                    width=ABBEY_BUTTRESS_PROTRUSION,
                    height=wall_height,
                )
            except Exception as error:  # noqa: BLE001
                print(f"[ERROR] 修道院基礎({label})の控え壁(#{k})の作成に失敗しました: ({error})", file=sys.stderr)
                raise
            break


def _add_abbey_substructure_tier(bm, points, bottom_ys, top_ys, center_x, center_z, label=""):
    """修道院の垂直基礎構造1段分(側面の壁+天端近くのコーニス+控え壁)をbmeshへ追加する。

    points: 輪郭の頂点(x,z)のリスト。bottom_ys/top_ys: 各頂点での壁の下端・上端の高さ
    (定数でも頂点ごとのリストでもよい)。center_x/center_z: 控え壁・コーニスの外向き方向を
    求めるための輪郭のおおよその中心(外接矩形の中心)。
    """
    n_pts = len(points)
    top_ys_list = top_ys if hasattr(top_ys, "__len__") else [top_ys] * n_pts

    # 側面(輪郭を1周する垂直の壁)
    bottom_verts = [bm.verts.new(_engine_to_blender(px, by, pz)) for (px, pz), by in zip(points, bottom_ys)]
    top_verts = [bm.verts.new(_engine_to_blender(px, ty, pz)) for (px, pz), ty in zip(points, top_ys_list)]
    for i in range(n_pts):
        i_next = (i + 1) % n_pts
        bm.faces.new((bottom_verts[i], bottom_verts[i_next], top_verts[i_next], top_verts[i]))

    # コーニス(天端近くの水平の帯)。各輪郭点を中心からの放射方向へABBEY_CORNICE_PROTRUSION
    # だけ外側にずらしたもう1周のリングを、天端の少し下から天端までの間に作る
    inner_verts = []
    outer_bottom_verts = []
    outer_top_verts = []
    for (px, pz), ty in zip(points, top_ys_list):
        cornice_bottom_y = ty - ABBEY_CORNICE_HEIGHT
        dx, dz = px - center_x, pz - center_z
        dlen = math.hypot(dx, dz)
        nx, nz = (dx / dlen, dz / dlen) if dlen > 1.0e-6 else (1.0, 0.0)
        ox, oz = px + nx * ABBEY_CORNICE_PROTRUSION, pz + nz * ABBEY_CORNICE_PROTRUSION
        inner_verts.append(bm.verts.new(_engine_to_blender(px, cornice_bottom_y, pz)))
        outer_bottom_verts.append(bm.verts.new(_engine_to_blender(ox, cornice_bottom_y, oz)))
        outer_top_verts.append(bm.verts.new(_engine_to_blender(ox, ty, oz)))
    for i in range(n_pts):
        i_next = (i + 1) % n_pts
        bm.faces.new((inner_verts[i], inner_verts[i_next], outer_bottom_verts[i_next], outer_bottom_verts[i]))
        bm.faces.new((outer_bottom_verts[i], outer_bottom_verts[i_next], outer_top_verts[i_next], outer_top_verts[i]))

    # 控え壁(バットレス)
    _add_abbey_substructure_buttresses(bm, points, bottom_ys, top_ys_list, center_x, center_z, label=label)


def _add_polygon_cap_to_bmesh(bm, points, y, center_x, center_z):
    """輪郭点(points)を高さyで塞ぐ平らな天面を、中心点への三角形ファンでbmeshへ追加する
    (build_rockの頂上台地のキャップと同じ要領。南テラスのように上に建物を載せず、
    テラス面そのものが見える場合に使う)。
    """
    center = bm.verts.new(_engine_to_blender(center_x, y, center_z))
    verts = [bm.verts.new(_engine_to_blender(px, y, pz)) for px, pz in points]
    n = len(points)
    for i in range(n):
        i_next = (i + 1) % n
        bm.faces.new((center, verts[i], verts[i_next]))


def _add_terrace_railing_to_bmesh(bm, points, base_y, height, thickness, center_x, center_z):
    """テラスの縁に沿って低い手すり壁を1周分bmeshへ追加する(南テラスの縁取り。承認済み
    計画の方針で、写真の印象に近づけるための出典なしの決め値)。

    points: 輪郭点(x,z)のリスト。base_y: 手すりの底面(テラス面と同じ高さ)。thickness:
    輪郭の外側(放射方向)へ付ける厚み。底面はテラス面に埋め込まれて見えないため作らない
    (他パーツと同じ方針)。
    """
    n_pts = len(points)
    inner_bottom, inner_top, outer_bottom, outer_top = [], [], [], []
    for px, pz in points:
        dx, dz = px - center_x, pz - center_z
        dlen = math.hypot(dx, dz)
        nx, nz = (dx / dlen, dz / dlen) if dlen > 1.0e-6 else (1.0, 0.0)
        ox, oz = px + nx * thickness, pz + nz * thickness
        inner_bottom.append(bm.verts.new(_engine_to_blender(px, base_y, pz)))
        inner_top.append(bm.verts.new(_engine_to_blender(px, base_y + height, pz)))
        outer_bottom.append(bm.verts.new(_engine_to_blender(ox, base_y, oz)))
        outer_top.append(bm.verts.new(_engine_to_blender(ox, base_y + height, oz)))

    for i in range(n_pts):
        i_next = (i + 1) % n_pts
        bm.faces.new((inner_bottom[i], inner_top[i], inner_top[i_next], inner_bottom[i_next]))  # 内側面
        bm.faces.new((outer_bottom[i], outer_bottom[i_next], outer_top[i_next], outer_top[i]))  # 外側面(視認される側)
        bm.faces.new((inner_top[i], outer_top[i], outer_top[i_next], inner_top[i_next]))  # 天端


def _add_abbey_facade_windows(bm, points, bottom_ys, top_ys, center_x, center_z, label=""):
    """修道院基礎の1つの段の南側の壁面に、ABBEY_FACADE_WINDOW_ROW_OFFSETSの各行・
    ABBEY_FACADE_WINDOW_SPACING間隔で窓を配置する(擁壁を「窓の並ぶ建物の正面」に
    見せるための追加)。

    points/bottom_ysはその段の輪郭点・各点での壁の下端の高さ。top_ysは天端の高さで、
    スカラー(全周で同一)と輪郭点ごとのリストの両方を受け付ける。
    輪郭の両端点がともにcenter_zより南(pz < center_z)の辺だけを対象にする。
    窓の下端がその位置の壁の下端(辺に沿って線形補間したbottom_ys)より下になる場合は、
    壁が無い場所に窓が浮くのを防ぐためその窓をスキップする。

    修正パス(参考写真c_abbey_south_closeup.jpgの精査): 以前は第0段にしか呼んでおらず、
    南側で第0段の壁が短い区間では窓が全部スキップされていた(36箇所中20箇所)。
    写真では教会の下の塊は平らな壁面に小さな窓が何段も散った「建物」に見えるため、
    全段と南・西のテラス壁にも回すようにした。
    """
    n_pts = len(points)
    place_count = 0
    skip_count = 0
    thinned_count = 0
    # 専用の擬似乱数。labelを混ぜて段ごとに違う散り方にしつつ、実行のたびには変わらないようにする
    rng = random.Random(f"{ABBEY_FACADE_WINDOW_SEED}:{label}")

    def top_y_at(index, u):
        """輪郭点indexと次の点のあいだの位置uにおける天端の高さ。"""
        if isinstance(top_ys, (list, tuple)):
            a = top_ys[index]
            b = top_ys[(index + 1) % len(top_ys)]
            return a + (b - a) * u
        return top_ys
    for i in range(n_pts):
        i_next = (i + 1) % n_pts
        px0, pz0 = points[i]
        px1, pz1 = points[i_next]
        if not (pz0 < center_z and pz1 < center_z):
            continue  # 南側の辺のみ対象

        edge_x, edge_z = px1 - px0, pz1 - pz0
        edge_length = math.hypot(edge_x, edge_z)
        if edge_length < 1.0e-6:
            continue
        tan_x, tan_z = edge_x / edge_length, edge_z / edge_length

        margin = ABBEY_FACADE_WINDOW_WIDTH
        span = edge_length - margin * 2.0
        if span <= 0.0:
            continue  # 辺が短すぎて窓を置けない
        count = max(2, int(span / ABBEY_FACADE_WINDOW_SPACING) + 1)

        for k in range(count):
            u = k / (count - 1)
            local_u = (margin + span * u) / edge_length
            px = px0 + edge_x * local_u
            pz = pz0 + edge_z * local_u
            bottom_y = bottom_ys[i] + (bottom_ys[i_next] - bottom_ys[i]) * local_u

            dx, dz = px - center_x, pz - center_z
            dlen = math.hypot(dx, dz)
            out_x, out_z = (dx / dlen, dz / dlen) if dlen > 1.0e-6 else (1.0, 0.0)

            for row_offset in ABBEY_FACADE_WINDOW_ROW_OFFSETS:
                # 列と行が揃って格子に見えるのを崩す(乱数の消費数を窓の位置に依らず
                # 一定にするため、間引きの判定と高さのばらつきは常にこの順で引く)
                thin = rng.random() < ABBEY_FACADE_WINDOW_SKIP_PROBABILITY
                jitter = rng.uniform(-ABBEY_FACADE_WINDOW_ROW_JITTER, ABBEY_FACADE_WINDOW_ROW_JITTER)
                if thin:
                    thinned_count += 1
                    continue

                window_y = top_y_at(i, local_u) + row_offset + jitter
                if window_y < bottom_y:
                    # 壁が無い(下端より下になる)位置には窓を置かない
                    skip_count += 1
                    continue
                try:
                    _add_window_to_bmesh(
                        bm, base=(px, window_y, pz),
                        along_dir=(tan_x, 0.0, tan_z), outward_dir=(out_x, 0.0, out_z),
                        width=ABBEY_FACADE_WINDOW_WIDTH, height=ABBEY_FACADE_WINDOW_HEIGHT,
                    )
                except Exception as error:  # noqa: BLE001
                    print(f"[ERROR] 修道院基礎正面の窓(辺{i}, k={k})の作成に失敗しました: ({error})", file=sys.stderr)
                    raise
                place_count += 1

    print(
        f"[INFO] 修道院基礎正面の窓({label}): {place_count}個配置、{skip_count}個スキップ"
        f"(壁の下端より下のため)、{thinned_count}個間引き(格子崩し)"
    )
    return place_count, skip_count


def _add_abbey_south_row_to_bmesh(bm, outline, top_ys):
    """修道院の南面に、基礎の最下段の天端へ載る棟の列を追加する(ABBEY_SOUTH_ROW_*参照)。

    outline: その段の輪郭点[(x, z), ...]。top_ys: 各輪郭点での天端の高さ。
    棟線はX方向(東西)。各棟のZ位置は、その棟の中心Xにおける輪郭の南端から
    ABBEY_SOUTH_ROW_EDGE_INSETだけ北へ引いた位置を南壁とする。

    【天端は棟ごとに取る】段の天端は輪郭点ごとに高さが違う(岩の斜面に追随するため、
    南の正面では81mでも南東・南西の隅では50m台まで下がる)。南側の点の最小値を使うと
    正面の棟まで28m下がって基礎の中へ埋もれてしまったので、棟ごとに**中心Xに最も近い
    輪郭点の天端**を使う。結果として棟の列は岩の斜面に沿って東西へ下がり、
    参考写真の「斜面を段々に下りる建物群」と同じ並びになる。
    """
    south_points = [(x, z, ty) for (x, z), ty in zip(outline, top_ys) if z < 0.0]
    if not south_points:
        print(
            "[ERROR] 修道院の南面の棟を載せる段に、南側(z<0)の輪郭点がありません。"
            "ABBEY_TERRACE_OUTSETS/基礎の輪郭を見直してください",
            file=sys.stderr,
        )
        raise ValueError("修道院の南面の棟を載せる輪郭点がありません")

    span = ABBEY_SOUTH_ROW_X_MAX - ABBEY_SOUTH_ROW_X_MIN
    pitch = span / ABBEY_SOUTH_ROW_COUNT
    width_x = pitch - ABBEY_SOUTH_ROW_GAP
    if width_x <= 0.0:
        print(
            f"[ERROR] 修道院の南面の棟の幅が0以下です(間隔{pitch:.1f}m - 隙間"
            f"{ABBEY_SOUTH_ROW_GAP}m)。ABBEY_SOUTH_ROW_COUNT/GAPを見直してください",
            file=sys.stderr,
        )
        raise ValueError("修道院の南面の棟の幅が0以下です")

    placed = 0
    ridge_ys = []
    for i in range(ABBEY_SOUTH_ROW_COUNT):
        center_x = ABBEY_SOUTH_ROW_X_MIN + pitch * (i + 0.5)
        # その中心Xにいちばん近い南側の輪郭点から、段の南端Zとその位置の天端を取る
        _px, edge_z, base_y = min(south_points, key=lambda p: abs(p[0] - center_x))
        south_wall_z = edge_z + ABBEY_SOUTH_ROW_EDGE_INSET
        center_z = south_wall_z + ABBEY_SOUTH_ROW_DEPTH * 0.5
        try:
            _add_house_to_bmesh(
                bm,
                base=(center_x, base_y, center_z),
                along_dir=(1.0, 0.0, 0.0),
                across_dir=(0.0, 0.0, 1.0),
                width=ABBEY_SOUTH_ROW_DEPTH,
                depth=width_x,
                wall_height=ABBEY_SOUTH_ROW_WALL_HEIGHT,
                roof_height=ABBEY_SOUTH_ROW_ROOF_HEIGHT,
                wall_material="Masonry",
                roof_material="SlateRoof",
            )
        except Exception as error:  # noqa: BLE001
            print(f"[ERROR] 修道院の南面の棟(#{i})の作成に失敗しました: ({error})", file=sys.stderr)
            raise
        placed += 1
        ridge_ys.append(base_y + ABBEY_SOUTH_ROW_WALL_HEIGHT + ABBEY_SOUTH_ROW_ROOF_HEIGHT)

    # プラットフォーム(92m)を少し越えるのは意図どおり(上段の建物の足元に掛けて
    # 重なりを作るため)。ただし上段の建物のいちばん低い屋根(ABBEY_BLOCKSのOfficialite、
    # 棟線94.7m)を越えると上段が丸ごと隠れるので、そこを閾値にする
    if max(ridge_ys) > CHURCH_FLOOR_Y + 3.0:
        print(
            f"[WARNING] 修道院の南面の棟の棟線(最高{max(ridge_ys):.1f}m)が高すぎ、"
            f"上段のいちばん低い建物(約{CHURCH_FLOOR_Y + 3.0:.1f}m)を隠します。"
            f"ABBEY_SOUTH_ROW_WALL_HEIGHT/ROOF_HEIGHTを見直してください"
        )
    print(f"[INFO] 修道院の南面の棟: {placed}棟 1棟の幅={width_x:.1f}m "
          f"棟線={' / '.join(f'{y:.1f}' for y in ridge_ys)}m(西→東)")


def build_abbey_substructure():
    """修道院(教会+ラ・メルヴェイユ)の平面輪郭を、岩の斜面まで垂直に落とす花崗岩の壁の
    塊(垂直基礎構造)を1つのメッシュにまとめて作る。

    aerial12.jpg/aerial11.jpg/aerial6.jpgのいずれでも、教会はなだらかな岩の頂上台地に
    直接載っておらず、岩の斜面から垂直な壁が立ち上がり、その天端に教会が載っている。
    この「要塞のような垂直の石の塊」が島の中央部の大部分を占め、シルエットの説得力の
    中核になっている(ユーザーからの参考写真精査に基づく指摘)。実物の修道院の床は
    自然の岩ではなく人工的なプラットフォームで、「4つのクリプトが頂上の建物を支えるために
    造られ、岩の上に教会を建てることを可能にした」(修道院公式サイト)という記述のとおり、
    狭い岩の頂(ROCK_PLATEAU_RADIUS=20m)から基礎構造で外へ床を張り出して建物を載せる
    構成にした(詳細はROCK_PLATEAU_RADIUSのコメント参照)。

    参考写真(c_aerial_sw_daylight.jpg/c_aerial_se_goldenhour.jpg)では基礎が一枚壁・
    二段ではなく、外へ広がりながら何段も下りる「階段ピラミッド」になっているため、
    第0段(教会の輪郭)+ABBEY_TERRACE_OUTSETSで指定した段数(既定3段)の多段構成にする。
    第0段はCHURCH_FLOOR_Yから、その輪郭位置での岩の表面高さとの間をABBEY_TIER_DROP_FRACTION
    (既定0.5)だけ下りた高さまで(下まで届かせず途中で止め、次の段へ引き継ぐ)。
    以降の各段は、1つ上の段の下端よりABBEY_TERRACE_STEP_GAPだけ低い位置を天端とし、
    その段自身の(より外側の)輪郭位置での岩の表面高さまでの距離をABBEY_TIER_DROP_FRACTION
    だけ下りる(最下段だけはdrop=1.0で岩の表面まで届かせる)。各段にコーニス・控え壁を
    回す(_add_abbey_substructure_tier参照)。

    輪郭は厳密でなくてよいため、教会+ラ・メルヴェイユを合わせた外接矩形を
    ABBEY_SUBSTRUCTURE_MARGINだけ膨らませ、超楕円(角を丸めた矩形)で近似した
    ABBEY_SUBSTRUCTURE_SIDES角形を使う。岩の表面高さは各輪郭点の水平位置(半径radius,
    角度theta)から_find_rock_t_for_radiusで逆算したt*ROCK_PLATEAU_Z。

    教会の南側は身廊・交差部が岩の中心付近(ROCK_PLATEAU_RADIUS=20mの内側)にあるため
    上段・下段の壁がほぼ0mになる(検証で確認済みの既知の限界)。実物の写真
    (aerial11.jpg/aerial12.jpg/pexels1.jpg)では教会の南側に「西のテラス」に相当する
    張り出したテラスとその下の高い擁壁があるため、教会の南辺(=upper/lowerの外接矩形の
    南端z_min)からSOUTH_TERRACE_DEPTHだけ-Z方向へ張り出す第3の区画(南テラス)を追加する。
    南テラスは上に建物を載せない平らな面のため、上段・下段と違って天面をキャップし、
    縁に低い手すり壁(SOUTH_TERRACE_RAILING_*)を回す。
    """
    # 【修正・ラ・メルヴェイユが基礎の壁に隠れていた】以前はz_maxにMERVEILLE_Z_MAXを
    # 含めていたため、基礎の壁(天端=CHURCH_FLOOR_Y=92m)がラ・メルヴェイユ(壁の天端97.5m)の
    # 北側を丸ごと囲ってしまい、北から見えるのは上端5.5mと屋根だけだった。
    # 参考写真c_northeast_whole_lowtide.jpgでは、北面の主役はラ・メルヴェイユ自身の
    # 高い一枚壁で、その前に別の擁壁は立っていない(基礎は教会のプラットフォームを
    # 支えるためのもので、ラ・メルヴェイユは北の崖に自立する)。
    # z_maxを翼廊の北端(TRANSEPT_NORTH_Z=16)までに留め、北側25mをラ・メルヴェイユへ譲る。
    # x方向は教会のほうが広い(-45〜21 に対しメルヴェイユは-30〜5)ので影響しない
    x_min = CHURCH_WEST_X
    x_max = max(CHURCH_APSE_CENTER_X + APSE_RADIUS, CROSSING_CENTER_X + TRANSEPT_DEPTH * 0.5)
    z_min = min(TRANSEPT_SOUTH_Z, -NAVE_WIDTH * 0.5, MERVEILLE_Z_MIN)
    z_max = max(TRANSEPT_NORTH_Z, NAVE_WIDTH * 0.5)

    x_min -= ABBEY_SUBSTRUCTURE_MARGIN
    x_max += ABBEY_SUBSTRUCTURE_MARGIN
    z_min -= ABBEY_SUBSTRUCTURE_MARGIN
    z_max += ABBEY_SUBSTRUCTURE_MARGIN

    center_x = (x_min + x_max) * 0.5
    center_z = (z_min + z_max) * 0.5
    half_x = (x_max - x_min) * 0.5
    half_z = (z_max - z_min) * 0.5

    def make_superellipse_points(cx, cz, hx, hz):
        """外接矩形の中心(cx, cz)・半径(hx, hz)から、超楕円(角を丸めた矩形)で
        近似した輪郭点を作る。
        """
        n = ABBEY_SUBSTRUCTURE_SUPERELLIPSE_EXPONENT
        pts = []
        for i in range(ABBEY_SUBSTRUCTURE_SIDES):
            angle = 2.0 * math.pi * i / ABBEY_SUBSTRUCTURE_SIDES
            c, s = math.cos(angle), math.sin(angle)
            px = cx + hx * math.copysign(abs(c) ** (2.0 / n), c)
            pz = cz + hz * math.copysign(abs(s) ** (2.0 / n), s)
            pts.append((px, pz))
        return pts

    def rock_bottom_ys(points, label):
        ys = []
        for i, (px, pz) in enumerate(points):
            radius = math.hypot(px, pz)
            theta = math.atan2(pz, px)
            t = _find_rock_t_for_radius(theta, radius, point_label=f"{label}#{i}({px:.1f},{pz:.1f})")
            ys.append(t * ROCK_PLATEAU_Z)
        return ys

    # 第0段(教会の輪郭)
    upper_points = make_superellipse_points(center_x, center_z, half_x, half_z)
    upper_full_bottom_ys = rock_bottom_ys(upper_points, "tier0")
    # 第0段は下まで届かせず、CHURCH_FLOOR_Yとその位置での岩の表面高さの間をABBEY_TIER_
    # DROP_FRACTIONだけ下りた高さで止める
    upper_bottom_ys = [
        CHURCH_FLOOR_Y - (CHURCH_FLOOR_Y - full_by) * ABBEY_TIER_DROP_FRACTION
        for full_by in upper_full_bottom_ys
    ]

    # 第1段以降(ABBEY_TERRACE_OUTSETSを回す「階段ピラミッド」)。段ごとに外へ張り出し
    # ながら下りる。最下段だけdrop=1.0で岩の表面まで届かせ、それ以外はABBEY_TIER_
    # DROP_FRACTIONだけ下りて次の段へ引き継ぐ
    tier_points_list = [upper_points]
    tier_bottom_ys_list = [upper_bottom_ys]
    tier_top_ys_list = [CHURCH_FLOOR_Y]

    _south0 = min(range(len(upper_points)), key=lambda i: upper_points[i][1])
    print(f"[INFO] 修道院基礎 第0段(教会の輪郭): 南端"
          f"(x={upper_points[_south0][0]:.1f}, z={upper_points[_south0][1]:.1f}) "
          f"天端={CHURCH_FLOOR_Y:.1f}m 下端={upper_bottom_ys[_south0]:.1f}m "
          f"壁の高さ={CHURCH_FLOOR_Y - upper_bottom_ys[_south0]:.1f}m")

    prev_bottom_ys = upper_bottom_ys
    outset_count = len(ABBEY_TERRACE_OUTSETS)
    for k, outset in enumerate(ABBEY_TERRACE_OUTSETS):
        points = make_superellipse_points(center_x, center_z, half_x + outset, half_z + outset)
        rock_ys = rock_bottom_ys(points, f"tier{k + 1}")
        # この段の天端は1つ上の段の下端よりABBEY_TERRACE_STEP_GAPだけ低い位置(段差として見える)
        top_ys = [by - ABBEY_TERRACE_STEP_GAP for by in prev_bottom_ys]
        is_last_tier = (k == outset_count - 1)
        drop = 1.0 if is_last_tier else ABBEY_TIER_DROP_FRACTION
        bottom_ys = [ty - (ty - ry) * drop for ty, ry in zip(top_ys, rock_ys)]

        # 輪郭点が既に頂上台地の内側(岩の表面高さ=天端付近)にあり、下端が天端以上に
        # なってしまう箇所は、逆さまの壁ができてしまうため薄い壁にクランプする。
        # 段ごとに何点クランプしたかを1行のWARNINGにまとめる(0点なら出さない)
        clamp_count = 0
        for i in range(len(bottom_ys)):
            if bottom_ys[i] >= top_ys[i]:
                bottom_ys[i] = top_ys[i] - 0.1
                clamp_count += 1
        if clamp_count > 0:
            print(
                f"[WARNING] 修道院基礎(第{k + 1}段)で{clamp_count}点、下端が天端以上になったため"
                f"天端の少し下にクランプしました",
                file=sys.stderr,
            )

        tier_points_list.append(points)
        tier_bottom_ys_list.append(bottom_ys)
        tier_top_ys_list.append(top_ys)
        prev_bottom_ys = bottom_ys

        # 南面(カメラの向き)での各段の高さをログに出す。修道院の分節を検討するとき、
        # 「どの高さからどの高さまでが一枚の石壁か」を推測ではなく実際の値で見るため
        # (輪郭点のうちzが最小=最も南のものを代表に取る)
        south_index = min(range(len(points)), key=lambda i: points[i][1])
        print(f"[INFO] 修道院基礎 第{k + 1}段(張り出し{outset}m): 南端"
              f"(x={points[south_index][0]:.1f}, z={points[south_index][1]:.1f}) "
              f"天端={top_ys[south_index]:.1f}m 下端={bottom_ys[south_index]:.1f}m "
              f"壁の高さ={top_ys[south_index] - bottom_ys[south_index]:.1f}m")

    # 南テラス。X方向は上段/下段と同じ外接矩形(x_min〜x_max)を流用し、Z方向は
    # 教会の南辺(z_min。upper_pointsの南端がちょうどこの値になる)からさらに
    # SOUTH_TERRACE_DEPTHだけ-Z方向へ張り出す
    south_half_x = half_x
    south_half_z = SOUTH_TERRACE_DEPTH * 0.5
    south_center_x = center_x
    south_center_z = z_min - south_half_z
    south_points = make_superellipse_points(south_center_x, south_center_z, south_half_x, south_half_z)
    south_bottom_ys = rock_bottom_ys(south_points, "south")

    # タスク2: 西のテラス。南テラスと同じ作りをX方向へ流用する(X方向はx_minからさらに
    # WEST_TERRACE_DEPTHだけ-X方向へ張り出し、Z方向は南テラスがX方向にhalf_xを流用して
    # いるのと対称にhalf_zを流用する)
    west_half_x = WEST_TERRACE_DEPTH * 0.5
    west_half_z = half_z
    west_center_z = center_z
    west_center_x = x_min - west_half_x
    west_points = make_superellipse_points(west_center_x, west_center_z, west_half_x, west_half_z)
    west_bottom_ys = rock_bottom_ys(west_points, "west")

    bm = bmesh.new()

    try:
        for k in range(len(tier_points_list)):
            _add_abbey_substructure_tier(
                bm, tier_points_list[k], tier_bottom_ys_list[k], tier_top_ys_list[k],
                center_x, center_z, label=f"tier{k}",
            )
        _add_abbey_substructure_tier(
            bm, south_points, south_bottom_ys, CHURCH_FLOOR_Y, south_center_x, south_center_z, label="south",
        )
        _add_polygon_cap_to_bmesh(bm, south_points, CHURCH_FLOOR_Y, south_center_x, south_center_z)
        _add_terrace_railing_to_bmesh(
            bm, south_points, CHURCH_FLOOR_Y, SOUTH_TERRACE_RAILING_HEIGHT, SOUTH_TERRACE_RAILING_THICKNESS,
            south_center_x, south_center_z,
        )
        _add_abbey_substructure_tier(
            bm, west_points, west_bottom_ys, CHURCH_FLOOR_Y, west_center_x, west_center_z, label="west",
        )
        _add_polygon_cap_to_bmesh(bm, west_points, CHURCH_FLOOR_Y, west_center_x, west_center_z)
        _add_terrace_railing_to_bmesh(
            bm, west_points, CHURCH_FLOOR_Y, SOUTH_TERRACE_RAILING_HEIGHT, SOUTH_TERRACE_RAILING_THICKNESS,
            west_center_x, west_center_z,
        )
    except Exception as error:  # noqa: BLE001
        print(f"[ERROR] 修道院の垂直基礎構造の作成に失敗しました: ({error})", file=sys.stderr)
        raise

    # 修道院の垂直基礎構造は段・キャップ・欄干・控え壁すべて花崗岩(Masonry)
    _tag_new_faces(bm, 0, "Masonry")

    # 南面の下段の建物群(ABBEY_SOUTH_ROW_*参照)。Masonryの一括タグ付けの後に足すことで、
    # 屋根のSlateRoofが上書きされないようにする(基礎正面の窓と同じ理由)
    _add_abbey_south_row_to_bmesh(bm, tier_points_list[-1], tier_top_ys_list[-1])

    # タスク1: 第0段の南側の壁面に窓を配置する(上のMasonry一括タグ付けの後に追加することで、
    # 窓のマテリアル(WindowGlass、_add_window_to_bmesh内で設定)がMasonryに上書きされないようにする)
    try:
        total_placed = 0
        total_skipped = 0
        for k in range(len(tier_points_list)):
            placed, skipped = _add_abbey_facade_windows(
                bm, tier_points_list[k], tier_bottom_ys_list[k], tier_top_ys_list[k],
                center_x, center_z, label=f"tier{k}",
            )
            total_placed += placed
            total_skipped += skipped
        for pts, bys, cx, cz, lbl in (
            (south_points, south_bottom_ys, south_center_x, south_center_z, "south"),
            (west_points, west_bottom_ys, west_center_x, west_center_z, "west"),
        ):
            placed, skipped = _add_abbey_facade_windows(
                bm, pts, bys, CHURCH_FLOOR_Y, cx, cz, label=lbl,
            )
            total_placed += placed
            total_skipped += skipped
        print(f"[INFO] 修道院基礎正面の窓(合計): {total_placed}個配置、{total_skipped}個スキップ")
    except Exception as error:  # noqa: BLE001
        print(f"[ERROR] 修道院基礎正面の窓の配置に失敗しました: ({error})", file=sys.stderr)
        raise

    bmesh.ops.recalc_face_normals(bm, faces=bm.faces[:])

    mesh = bpy.data.meshes.new("AbbeySubstructure")
    bm.to_mesh(mesh)
    bm.free()
    mesh.update()

    obj = bpy.data.objects.new("AbbeySubstructure", mesh)
    _link(obj)
    bpy.context.view_layer.objects.active = obj
    obj.select_set(True)
    return obj


def build_church():
    """教会本体(身廊+翼廊+後陣+飛梁)を1つのメッシュにまとめて作る。

    実物の根拠は「床の海抜80m」「プラットフォーム長80m」(修道院公式サイト)、
    「元7ベイのうち西3ベイが1776年に破壊され現在4ベイ」(Catholic Encyclopedia)、
    「半円形の後陣」(Catholic Encyclopedia/fr.wikipedia)のみで、高さ・平面寸法・
    配置座標は出典なしの決め値(各定数のコメント参照)。身廊・翼廊は_add_house_to_bmesh
    (集落の家屋と同じ「箱+切妻屋根」のヘルパー)を、軸並行のalong_dir/across_dirを
    渡すことで再利用する。

    実物の教会は東西軸(身廊が西、内陣・後陣が東)で建つため、身廊はX軸方向(西→東)、
    翼廊はZ軸方向(南北)へ張り出す配置にする(CHURCH_WEST_X/NAVE_EAST_X/CROSSING_CENTER_*/
    CHURCH_APSE_CENTER_Xの各定数のコメント参照)。旧クリプト擁壁(_add_rect_crypt_skirt/
    _add_apse_crypt_skirt)はbuild_abbey_substructure()の垂直基礎構造に統合したため
    ここでは呼ばない。
    """
    bm = bmesh.new()

    nave_depth = NAVE_BAY_DEPTH * NAVE_BAY_COUNT
    nave_center_x = CHURCH_WEST_X + nave_depth * 0.5
    transept_total_span = TRANSEPT_NORTH_Z - TRANSEPT_SOUTH_Z  # Z方向(南北)の全長

    # 確認用: 交差部(=鐘楼・尖塔・像の位置)が岩の頂上台地の中心(原点)に載っていることを
    # ログで確認する。ここが0.0から外れると尖塔が岩の頂上から東西へずれる
    print(
        f"[INFO] 教会: 身廊全長={nave_depth:.1f}m(西端CHURCH_WEST_X={CHURCH_WEST_X:.1f},"
        f" 東端NAVE_EAST_X={NAVE_EAST_X:.1f}) CROSSING_CENTER_X={CROSSING_CENTER_X:.1f}"
        f"(岩の頂上に載せるため0.0であるべき)"
    )

    try:
        # 身廊(棟線はX軸方向、屋根はZ方向に傾斜)。壁はMasonry、屋根はSlateRoof
        _add_house_to_bmesh(
            bm,
            base=(nave_center_x, CHURCH_FLOOR_Y, CROSSING_CENTER_Z),
            along_dir=(1.0, 0.0, 0.0),
            across_dir=(0.0, 0.0, 1.0),
            width=NAVE_WIDTH,
            depth=nave_depth,
            wall_height=NAVE_WALL_HEIGHT,
            roof_height=NAVE_ROOF_HEIGHT,
            wall_material="Masonry",
            roof_material="SlateRoof",
        )

        # 修正パス(コーディネーター指摘): 身廊の西正面(妻壁)が一枚の巨大な平面に
        # 見えないよう、身廊より幅が狭く・背が低い前室状の塊をさらに西へ足す
        west_block_center_x = CHURCH_WEST_X - CHURCH_WEST_BLOCK_DEPTH * 0.5
        _add_house_to_bmesh(
            bm,
            base=(west_block_center_x, CHURCH_FLOOR_Y, CROSSING_CENTER_Z),
            along_dir=(1.0, 0.0, 0.0),
            across_dir=(0.0, 0.0, 1.0),
            width=CHURCH_WEST_BLOCK_WIDTH,
            depth=CHURCH_WEST_BLOCK_DEPTH,
            wall_height=CHURCH_WEST_BLOCK_WALL_HEIGHT,
            roof_height=CHURCH_WEST_BLOCK_ROOF_HEIGHT,
            wall_material="Masonry",
            roof_material="SlateRoof",
        )

        # 窓: 身廊の南北の側壁(1段)
        half_nave_width = NAVE_WIDTH * 0.5
        _add_window_wall_to_bmesh(
            bm, wall_start=(CHURCH_WEST_X, CHURCH_FLOOR_Y, half_nave_width),
            along_dir=(1.0, 0.0, 0.0), wall_length=nave_depth,
            outward_dir=(0.0, 0.0, 1.0), floor_base_ys=[CHURCH_FLOOR_Y],
        )
        _add_window_wall_to_bmesh(
            bm, wall_start=(CHURCH_WEST_X, CHURCH_FLOOR_Y, -half_nave_width),
            along_dir=(1.0, 0.0, 0.0), wall_length=nave_depth,
            outward_dir=(0.0, 0.0, -1.0), floor_base_ys=[CHURCH_FLOOR_Y],
        )

        # タスク4: 身廊の南に低い付属棟(実物の修道院長の館などにあたる)を足し、屋根面を
        # 重ねてのっぺり感を消す。棟線はX方向(along_dir=(1,0,0))。壁はMasonry、屋根はSlateRoof
        annex_width_x = ABBEY_SOUTH_ANNEX_X_MAX - ABBEY_SOUTH_ANNEX_X_MIN
        annex_center_x = (ABBEY_SOUTH_ANNEX_X_MIN + ABBEY_SOUTH_ANNEX_X_MAX) * 0.5
        annex_nave_wall_z = -half_nave_width  # 身廊の南壁(=-13.0)
        annex_south_wall_z = annex_nave_wall_z - ABBEY_SOUTH_ANNEX_DEPTH
        annex_center_z = (annex_nave_wall_z + annex_south_wall_z) * 0.5
        _add_house_to_bmesh(
            bm,
            base=(annex_center_x, CHURCH_FLOOR_Y, annex_center_z),
            along_dir=(1.0, 0.0, 0.0),
            across_dir=(0.0, 0.0, 1.0),
            width=ABBEY_SOUTH_ANNEX_DEPTH,
            depth=annex_width_x,
            wall_height=ABBEY_SOUTH_ANNEX_WALL_HEIGHT,
            roof_height=ABBEY_SOUTH_ANNEX_ROOF_HEIGHT,
            wall_material="Masonry",
            roof_material="SlateRoof",
        )
        # 窓: 付属棟の南面(1段)
        _add_window_wall_to_bmesh(
            bm, wall_start=(ABBEY_SOUTH_ANNEX_X_MIN, CHURCH_FLOOR_Y, annex_south_wall_z),
            along_dir=(1.0, 0.0, 0.0), wall_length=annex_width_x,
            outward_dir=(0.0, 0.0, -1.0), floor_base_ys=[CHURCH_FLOOR_Y + 4.0],
        )

        # 翼廊(棟線はZ軸方向、屋根はX方向に傾斜。交差部を中心に南北へ張り出す)。
        # 壁はMasonry、屋根はSlateRoof
        _add_house_to_bmesh(
            bm,
            base=(CROSSING_CENTER_X, CHURCH_FLOOR_Y, CROSSING_CENTER_Z),
            along_dir=(0.0, 0.0, 1.0),
            across_dir=(1.0, 0.0, 0.0),
            width=TRANSEPT_DEPTH,
            depth=transept_total_span,
            wall_height=NAVE_WALL_HEIGHT,
            roof_height=NAVE_ROOF_HEIGHT,
            wall_material="Masonry",
            roof_material="SlateRoof",
        )

        # 後陣(半円形、+X=東へ張り出す)+飛梁(ピナクル付き)
        _add_apse_to_bmesh(
            bm, center_x=CHURCH_APSE_CENTER_X, center_z=CROSSING_CENTER_Z, radius=APSE_RADIUS,
            base_y=CHURCH_FLOOR_Y, wall_height=APSE_WALL_HEIGHT, roof_height=APSE_ROOF_HEIGHT,
        )
        _add_flying_buttresses_to_bmesh(
            bm, center_x=CHURCH_APSE_CENTER_X, center_z=CROSSING_CENTER_Z, base_y=CHURCH_FLOOR_Y,
        )

        # 窓: 後陣の壁面に放射状に(両端の平らな背面付近を避け-60°〜+60°に均等配置)
        for i in range(APSE_WINDOW_COUNT):
            u = i / (APSE_WINDOW_COUNT - 1)
            angle = math.radians(-60.0) + math.radians(120.0) * u
            dir_x, dir_z = math.cos(angle), math.sin(angle)
            tan_x, tan_z = -math.sin(angle), math.cos(angle)
            window_x = CHURCH_APSE_CENTER_X + APSE_RADIUS * dir_x
            window_z = CROSSING_CENTER_Z + APSE_RADIUS * dir_z
            _add_window_to_bmesh(
                bm, base=(window_x, CHURCH_FLOOR_Y, window_z),
                along_dir=(tan_x, 0.0, tan_z), outward_dir=(dir_x, 0.0, dir_z),
            )
    except Exception as error:  # noqa: BLE001
        print(f"[ERROR] 教会本体の作成に失敗しました: ({error})", file=sys.stderr)
        raise

    bmesh.ops.recalc_face_normals(bm, faces=bm.faces[:])

    mesh = bpy.data.meshes.new("Church")
    bm.to_mesh(mesh)
    bm.free()
    mesh.update()

    obj = bpy.data.objects.new("Church", mesh)
    _link(obj)
    bpy.context.view_layer.objects.active = obj
    obj.select_set(True)
    return obj


def build_abbey_blocks():
    """修道院の付属建築(ABBEY_BLOCKS)を1つのメッシュにまとめて作る。

    手続き生成の身廊・翼廊・後陣・ラ・メルヴェイユ・南の付属棟だけでは、実物の
    「高さの違う塊が10近く積み重なって屋根面が複雑に交差する」量塊に届かないため、
    座標を直書きした塊の表(ABBEY_BLOCKS)を_add_house_to_bmeshで積み増す
    (詳細はABBEY_BLOCKSのコメント参照)。build_abbey_substructure()の基礎の中に
    下部が埋まる想定(実体のあるモデルなので中は見えない)。
    """
    bm = bmesh.new()

    for name, x_min, x_max, z_min, z_max, orientation, base_height, wall_height, roof_height, has_windows in ABBEY_BLOCKS:
        try:
            center_x = (x_min + x_max) * 0.5
            center_z = (z_min + z_max) * 0.5
            base = (center_x, base_height, center_z)

            if orientation == 'X':
                along_dir = (1.0, 0.0, 0.0)
                across_dir = (0.0, 0.0, 1.0)
                depth = x_max - x_min
                width = z_max - z_min
            elif orientation == 'Z':
                along_dir = (0.0, 0.0, 1.0)
                across_dir = (1.0, 0.0, 0.0)
                depth = z_max - z_min
                width = x_max - x_min
            else:
                raise ValueError(f"未知の棟の向きです: {orientation}")

            _add_house_to_bmesh(
                bm,
                base=base,
                along_dir=along_dir,
                across_dir=across_dir,
                width=width,
                depth=depth,
                wall_height=wall_height,
                roof_height=roof_height,
                wall_material="Masonry",
                roof_material="SlateRoof",
            )

            if has_windows:
                # 南面(z=z_minの面、外向きは-Z)に窓を2段付ける
                if orientation == 'X':
                    wall_start = (x_min, base_height, z_min)
                    window_along_dir = (1.0, 0.0, 0.0)
                    wall_length = x_max - x_min
                else:
                    wall_start = (x_min, base_height, z_min)
                    window_along_dir = (0.0, 0.0, 1.0)
                    wall_length = z_max - z_min
                floor_base_ys = [
                    base_height + wall_height * 0.35,
                    base_height + wall_height * 0.70,
                ]
                # 揃った格子に見えるのを崩すため間引く(理由は
                # ABBEY_FACADE_WINDOW_ROW_OFFSETSのコメント参照)。棟ごとに違う散り方に
                # なるよう名前をシードへ混ぜ、実行のたびには変わらないようにする
                _add_window_wall_to_bmesh(
                    bm, wall_start=wall_start, along_dir=window_along_dir, wall_length=wall_length,
                    outward_dir=(0.0, 0.0, -1.0), floor_base_ys=floor_base_ys,
                    thin_rng=random.Random(f"{ABBEY_FACADE_WINDOW_SEED}:{name}"),
                    skip_probability=ABBEY_FACADE_WINDOW_SKIP_PROBABILITY,
                )
        except Exception as error:  # noqa: BLE001
            print(f"[ERROR] 修道院の付属建築({name})の作成に失敗しました: ({error})", file=sys.stderr)
            raise

    try:
        # シャトレの双塔(実物の入口左右の円塔)
        for turret_x, turret_z in ABBEY_CHATELET_TURRET_CENTERS:
            _add_octagon_turret_to_bmesh(
                bm, turret_x, turret_z, ABBEY_CHATELET_TURRET_BOTTOM_Y,
                ABBEY_CHATELET_TURRET_BODY_HEIGHT, ABBEY_CHATELET_TURRET_ROOF_HEIGHT,
                ABBEY_CHATELET_TURRET_RADIUS, ABBEY_CHATELET_TURRET_SIDES,
            )
    except Exception as error:  # noqa: BLE001
        print(f"[ERROR] シャトレの双塔の作成に失敗しました: ({error})", file=sys.stderr)
        raise

    bmesh.ops.recalc_face_normals(bm, faces=bm.faces[:])

    mesh = bpy.data.meshes.new("AbbeyBlocks")
    bm.to_mesh(mesh)
    bm.free()
    mesh.update()

    obj = bpy.data.objects.new("AbbeyBlocks", mesh)
    _link(obj)
    bpy.context.view_layer.objects.active = obj
    obj.select_set(True)
    return obj


def _rock_surface_base_y(engine_x, engine_z, label):
    """エンジン空間の水平位置(x, z)における岩の表面の高さを返す。

    任意の(x, z)へ建物を置くとき、足元を岩の表面に合わせるための補助。
    _rock_radiusは「高さパラメータt → 半径」の向きなので、_find_rock_t_for_radiusで
    半径から逆算する(この用途の共通ヘルパーはこれまで存在せず、
    build_abbey_substructureが自前の closure で同じことをしていた)。
    """
    theta = math.atan2(engine_z, engine_x)
    radius = math.hypot(engine_x, engine_z)
    t = _find_rock_t_for_radius(theta, radius, point_label=label, caller_label="建物の足元")
    return t * ROCK_PLATEAU_Z


def build_west_end():
    """西端の建築(ガブリエル塔+その内側の大きな棟)を1つのメッシュにまとめて作る。

    追加の根拠と寸法の出どころはWEST_END_*定数のコメント参照。どちらも足元は
    _rock_surface_base_yで岩の表面へ合わせるため、岩のプロファイルを変えても浮かない。
    """
    bm = bmesh.new()

    try:
        # 【順序に注意】_add_house_to_bmeshはインデックス基準の_tag_new_facesを使うため、
        # 先にbmesh.ops(小塔)を呼ぶとタグ付けを取りこぼす(実際に2面がRockのまま残り、
        # _warn_untagged_facesが検出した)。手作業で面を作る棟を先に、opsを使う塔を後に置く。
        # 理由は_tag_faces_sinceのdocstring参照
        # 大きな棟。城壁のすぐ内側の岩の上に、棟線を半径方向にして置く
        lodge_theta = math.radians(WEST_END_LODGE_THETA_DEG)
        lodge_radius = _rock_radius(0.0, lodge_theta) - WEST_END_LODGE_RADIUS_INSET
        lodge_x = lodge_radius * math.cos(lodge_theta)
        lodge_z = lodge_radius * math.sin(lodge_theta)
        lodge_base_y = _rock_surface_base_y(lodge_x, lodge_z, "(西端の棟)")

        radial = (math.cos(lodge_theta), 0.0, math.sin(lodge_theta))
        tangent = (-math.sin(lodge_theta), 0.0, math.cos(lodge_theta))
        _add_house_to_bmesh(
            bm,
            base=(lodge_x, lodge_base_y, lodge_z),
            along_dir=radial,          # 棟線は斜面の奥へ
            across_dir=tangent,        # 妻の幅は接線方向
            width=WEST_END_LODGE_WIDTH,
            depth=WEST_END_LODGE_DEPTH,
            wall_height=WEST_END_LODGE_WALL_HEIGHT,
            roof_height=WEST_END_LODGE_ROOF_HEIGHT,
            wall_material="VillagePlaster",
            roof_material="SlateRoof",
        )

        # ガブリエル塔。城壁の基準線(_rampart_radius)の上に立てる。
        # 城壁と同じく水際近くから立ち上がるので、足元は城壁の底面高さに合わせる
        tower_theta = math.radians(WEST_END_TOWER_THETA_DEG)
        tower_radius = _rampart_radius(tower_theta, 0.0)
        tower_x = tower_radius * math.cos(tower_theta)
        tower_z = tower_radius * math.sin(tower_theta)
        _add_octagon_turret_to_bmesh(
            bm, tower_x, tower_z, WALL_BASE_Z_REF,
            WEST_END_TOWER_BODY_HEIGHT, WEST_END_TOWER_ROOF_HEIGHT,
            WEST_END_TOWER_RADIUS, WEST_END_TOWER_SIDES,
        )
        print(
            f"[INFO] 西端の建築: ガブリエル塔 (x={tower_x:.1f}, z={tower_z:.1f}) 天端"
            f"{WALL_BASE_Z_REF + WEST_END_TOWER_BODY_HEIGHT + WEST_END_TOWER_ROOF_HEIGHT:.1f}m / "
            f"棟 (x={lodge_x:.1f}, z={lodge_z:.1f}) 足元{lodge_base_y:.1f}m 棟線"
            f"{lodge_base_y + WEST_END_LODGE_WALL_HEIGHT + WEST_END_LODGE_ROOF_HEIGHT:.1f}m"
        )
    except Exception as error:  # noqa: BLE001
        print(f"[ERROR] 西端の建築の作成に失敗しました: ({error})", file=sys.stderr)
        raise

    bmesh.ops.recalc_face_normals(bm, faces=bm.faces[:])

    mesh = bpy.data.meshes.new("WestEnd")
    bm.to_mesh(mesh)
    bm.free()
    mesh.update()

    obj = bpy.data.objects.new("WestEnd", mesh)
    _link(obj)
    bpy.context.view_layer.objects.active = obj
    obj.select_set(True)
    return obj


def build_merveille():
    """ラ・メルヴェイユ(教会北側に隣接する2つの切妻屋根付きの塊、控え壁・窓付き)。

    高さ40m・3階建て(出典: fr.wikipedia)。3階建てを示す水平の目地線は省略するが、
    3階建てを表現するため北面・西面の壁に窓を3段配置する。修正パス(参考写真
    c_aerial_sw_daylight.jpgの精査)で、1つの直方体だけでは「窓が格子状に並んだ平らな
    板」に見えてしまうと指摘されたため、X方向にMERVEILLE_SPLIT_Xで2つの塊(西側=
    MERVEILLE_HEIGHT、東側=MERVEILLE_HEIGHT-MERVEILLE_EAST_HEIGHT_DROPと高さを変える)
    へ分割し、それぞれに窓・控え壁を回す形にした。build_abbey_substructure()が参照する
    外接矩形(MERVEILLE_X_MIN/MAX/Z_MIN/MAX)は変えていないため、基礎構造の輪郭には
    影響しない(2分割はこの関数の内部だけで行う)。控え壁(buttress)はArrayの考え方で
    露出する外側の面(西側の塊の西面・東側の塊の東面)だけに等間隔配置し、それぞれの
    天端にピナクルを乗せる。旧クリプト擁壁(_add_rect_crypt_skirt)はbuild_abbey_
    substructure()の垂直基礎構造に統合したためここでは呼ばない。

    修正パス(参考写真c_aerial_sw_daylight.jpg/c_abbey_south_closeup.jpgの精査)で、
    陸屋根の平らな天面では北から見たときに「窓が格子状に並んだ平らな箱」に見えてしまうと
    指摘されたため、各塊の天面を陸屋根から切妻屋根(棟がX方向=東西に走る)へ変更した。
    集落の家屋と同じ「箱の壁+切妻屋根」の形そのものであるため、専用の屋根組みを新たに
    作らず既存の_add_house_to_bmesh(along_dir=ridge方向, across_dir=軒の傾斜方向)を
    そのまま流用できた(壁面の形状は_add_flat_box_to_bmeshの側面と同一のため、北面・
    西面の窓・控え壁の配置ロジックは変更不要)。
    """
    bm = bmesh.new()

    center_z = (MERVEILLE_Z_MIN + MERVEILLE_Z_MAX) * 0.5
    depth_z = MERVEILLE_Z_MAX - MERVEILLE_Z_MIN

    # 修正パス(コーディネーター指摘): 参考写真c_north_merveille_detail.jpg/
    # c_north_wall_detail1.jpgでは、細く背の高い開口が太い控え壁のあいだに縦長に並び、
    # 3階建てを示す均等な窓格子(オフィスビル風)には見えない。段数を3→2へ減らし、
    # 窓自体もMERVEILLE_WINDOW_WIDTH/HEIGHTの縦長寸法にする(出典なしの決め値)
    # 修正パス(コーディネーター指摘、基準面をCHURCH_FLOOR_Y→MERVEILLE_BASE_Yへ変更): 窓の段の
    # 高さもMERVEILLE_BASE_Y基準に合わせて置き換えた(出典なしの決め値)
    floor_base_ys = [
        MERVEILLE_BASE_Y + 10.0,
        MERVEILLE_BASE_Y + 28.0,
    ]

    def add_block(x_min, x_max, height, add_west_buttress, add_east_buttress):
        """ラ・メルヴェイユの1つの塊(壁+切妻屋根・北面の窓・控え壁)をbmeshへ追加する。"""
        block_center_x = (x_min + x_max) * 0.5
        width_x = x_max - x_min

        # 壁はMasonry、屋根(棟がX方向=東西)はSlateRoof。_add_house_to_bmeshの
        # along_dir=棟の方向・depth=棟の長さ、across_dir=軒の傾斜方向・width=軒の幅
        _add_house_to_bmesh(
            bm,
            base=(block_center_x, MERVEILLE_BASE_Y, center_z),
            along_dir=(1.0, 0.0, 0.0),
            across_dir=(0.0, 0.0, 1.0),
            width=depth_z,
            depth=width_x,
            wall_height=height,
            roof_height=MERVEILLE_ROOF_HEIGHT,
            wall_material="Masonry",
            roof_material="SlateRoof",
        )

        # 北面(Z=MERVEILLE_Z_MAX)。塊ごとの幅の範囲だけ窓を並べる(ラ・メルヴェイユ専用の
        # 縦長寸法MERVEILLE_WINDOW_WIDTH/HEIGHTを使う)
        _add_window_wall_to_bmesh(
            bm, wall_start=(x_min, MERVEILLE_BASE_Y, MERVEILLE_Z_MAX),
            along_dir=(1.0, 0.0, 0.0), wall_length=width_x,
            outward_dir=(0.0, 0.0, 1.0), floor_base_ys=floor_base_ys,
            width=MERVEILLE_WINDOW_WIDTH, height=MERVEILLE_WINDOW_HEIGHT,
        )

        # 控え壁: 角にめり込みすぎないよう両端から1本分内側を始点・終点にして等間隔配置。
        # 天端にはピナクル(小尖塔)を乗せる。露出する外側の面だけに付ける
        margin = MERVEILLE_BUTTRESS_WIDTH
        z_start = MERVEILLE_Z_MIN + margin
        z_end = MERVEILLE_Z_MAX - margin
        for i in range(MERVEILLE_BUTTRESS_COUNT):
            u = i / (MERVEILLE_BUTTRESS_COUNT - 1)
            z = z_start + (z_end - z_start) * u

            if add_west_buttress:
                west_x = x_min - MERVEILLE_BUTTRESS_DEPTH * 0.5
                _add_flat_box_to_bmesh(
                    bm,
                    base=(west_x, MERVEILLE_BASE_Y, z),
                    along_dir=(0.0, 0.0, 1.0),
                    across_dir=(1.0, 0.0, 0.0),
                    depth=MERVEILLE_BUTTRESS_WIDTH,
                    width=MERVEILLE_BUTTRESS_DEPTH,
                    height=height,
                )
                first_pinnacle_face = len(bm.faces)
                _add_pinnacle_to_bmesh(bm, base=(west_x, MERVEILLE_BASE_Y + height, z))
                _tag_new_faces(bm, first_pinnacle_face, "Masonry")

            if add_east_buttress:
                east_x = x_max + MERVEILLE_BUTTRESS_DEPTH * 0.5
                _add_flat_box_to_bmesh(
                    bm,
                    base=(east_x, MERVEILLE_BASE_Y, z),
                    along_dir=(0.0, 0.0, 1.0),
                    across_dir=(1.0, 0.0, 0.0),
                    depth=MERVEILLE_BUTTRESS_WIDTH,
                    width=MERVEILLE_BUTTRESS_DEPTH,
                    height=height,
                )
                first_pinnacle_face = len(bm.faces)
                _add_pinnacle_to_bmesh(bm, base=(east_x, MERVEILLE_BASE_Y + height, z))
                _tag_new_faces(bm, first_pinnacle_face, "Masonry")

        # 北面(Z=MERVEILLE_Z_MAX)のリブ。北から見たときに正面に来る面で、参考写真では
        # ここに細いリブが密に走る(定数のコメント参照)。塊の幅をMERVEILLE_NORTH_BUTTRESS_
        # SPACINGで割って本数を決め、両端はリブ1本分内側から始める
        north_span = width_x - MERVEILLE_BUTTRESS_WIDTH * 2.0
        if north_span > 0.0:
            north_count = max(2, int(north_span / MERVEILLE_NORTH_BUTTRESS_SPACING) + 1)
            north_z = MERVEILLE_Z_MAX + MERVEILLE_BUTTRESS_DEPTH * 0.5
            for i in range(north_count):
                u = i / (north_count - 1)
                x = x_min + MERVEILLE_BUTTRESS_WIDTH + north_span * u
                _add_flat_box_to_bmesh(
                    bm,
                    base=(x, MERVEILLE_BASE_Y, north_z),
                    along_dir=(1.0, 0.0, 0.0),
                    across_dir=(0.0, 0.0, 1.0),
                    depth=MERVEILLE_BUTTRESS_WIDTH,
                    width=MERVEILLE_BUTTRESS_DEPTH,
                    height=height,
                )
                first_pinnacle_face = len(bm.faces)
                _add_pinnacle_to_bmesh(bm, base=(x, MERVEILLE_BASE_Y + height, north_z))
                _tag_new_faces(bm, first_pinnacle_face, "Masonry")

    try:
        # 西面(X=MERVEILLE_X_MIN)の窓は西側の塊にだけ付ける(実物どおり露出する外壁のみ。
        # ラ・メルヴェイユ専用の縦長寸法MERVEILLE_WINDOW_WIDTH/HEIGHTを使う)
        _add_window_wall_to_bmesh(
            bm, wall_start=(MERVEILLE_X_MIN, MERVEILLE_BASE_Y, MERVEILLE_Z_MIN),
            along_dir=(0.0, 0.0, 1.0), wall_length=depth_z,
            outward_dir=(-1.0, 0.0, 0.0), floor_base_ys=floor_base_ys,
            width=MERVEILLE_WINDOW_WIDTH, height=MERVEILLE_WINDOW_HEIGHT,
        )

        # 西側の塊(高さMERVEILLE_HEIGHT)。西面(露出する外壁)にだけ控え壁を付ける
        add_block(
            MERVEILLE_X_MIN, MERVEILLE_SPLIT_X, MERVEILLE_HEIGHT,
            add_west_buttress=True, add_east_buttress=False,
        )
        # 東側の塊(高さMERVEILLE_HEIGHT-MERVEILLE_EAST_HEIGHT_DROP)。境界(西面)は
        # 西側の塊と接するため付けず、東面(露出する外壁)にだけ控え壁を付ける
        add_block(
            MERVEILLE_SPLIT_X, MERVEILLE_X_MAX, MERVEILLE_HEIGHT - MERVEILLE_EAST_HEIGHT_DROP,
            add_west_buttress=False, add_east_buttress=True,
        )
    except Exception as error:  # noqa: BLE001
        print(f"[ERROR] ラ・メルヴェイユの作成に失敗しました: ({error})", file=sys.stderr)
        raise

    bmesh.ops.recalc_face_normals(bm, faces=bm.faces[:])

    mesh = bpy.data.meshes.new("Merveille")
    bm.to_mesh(mesh)
    bm.free()
    mesh.update()

    obj = bpy.data.objects.new("Merveille", mesh)
    _link(obj)
    bpy.context.view_layer.objects.active = obj
    obj.select_set(True)
    return obj


def _add_octagon_turret_to_bmesh(bm, center_x, center_z, bottom_y, body_height, roof_height, radius, sides,
                                  body_material="Masonry", roof_material="SlateRoof"):
    """小塔(細い多角柱+円錐屋根)を1本bmeshへ追加する(鐘楼の隅・ラ・メルヴェイユの
    控え壁上などで使う_add_tree_to_bmeshと同じ要領のヘルパー。円錐屋根は多角形にすると
    円柱本体と辺の数が揃って自然に繋がるため、sidesを本体・屋根で共通に使う)。

    center_x/center_z: 小塔の中心軸のエンジン空間水平座標。bottom_y: 本体の底面の高さ。
    body_material: 本体(多角柱)に割り当てるマテリアル名。roof_material: 円錐屋根に
    割り当てるマテリアル名。
    """
    blender_x, blender_y, blender_z = _engine_to_blender(center_x, bottom_y, center_z)

    faces_before = set(bm.faces)
    body_matrix = Matrix.Translation((blender_x, blender_y, blender_z + body_height * 0.5))
    bmesh.ops.create_cone(
        bm, cap_ends=True, cap_tris=True, segments=sides,
        diameter1=radius * 2.0, diameter2=radius * 2.0, depth=body_height,
        matrix=body_matrix, calc_uvs=False,
    )
    _tag_faces_since(bm, faces_before, body_material)

    faces_before = set(bm.faces)
    roof_matrix = Matrix.Translation((blender_x, blender_y, blender_z + body_height + roof_height * 0.5))
    bmesh.ops.create_cone(
        bm, cap_ends=True, cap_tris=True, segments=sides,
        diameter1=radius * 2.0, diameter2=0.0, depth=roof_height,
        matrix=roof_matrix, calc_uvs=False,
    )
    _tag_faces_since(bm, faces_before, roof_material)


def build_belfry():
    """鐘楼(交差部の塔。正方形の基部)。教会・翼廊の交差部の屋根の実際の高さ
    (NAVE_WALL_HEIGHT+NAVE_ROOF_HEIGHT、y=CHURCH_FLOOR_Y+29=121)から
    塔の頂(BELFRY_TOP_Y=126.70、出典あり)まで隙間なく届くよう、底面をその屋根の高さに
    合わせて高さを逆算する。

    平面形は正方形(BELFRY_SIDES=4)。以前は八角形だったが、参考写真
    c_abbey_south_closeup.jpg / c_belfry_spire_detail.jpg のどちらでも実物は正方形で、
    平らな面が縦の稜線で交わり4隅すべてに小塔が立つ。寸法の実測値と導出は
    BELFRY_HALF_WIDTH のコメントを参照。

    壁面(BELFRY_WINDOW_FACE_COUNT)に窓、4隅に小塔(BELFRY_TURRET_*)、屋根の頂に
    尖塔の付け根を取り巻く小尖塔の環(SPIRE_PINNACLE_*)を追加するため、
    primitive_cylinder_addではなくbmeshで直接角柱を組み立てる
    (頂点・面の角度を自分で把握して窓・小塔の位置決めに使うため)。
    """
    base_y = CHURCH_FLOOR_Y + NAVE_WALL_HEIGHT + NAVE_ROOF_HEIGHT  # 教会・翼廊交差部の屋根の高さ
    height = BELFRY_TOP_Y - base_y
    if height <= 0.0:
        print(
            f"[ERROR] 鐘楼の高さが0以下になりました(教会屋根の高さ{base_y}がBELFRY_TOP_Y"
            f"{BELFRY_TOP_Y}以上のため)。NAVE_WALL_HEIGHT/NAVE_ROOF_HEIGHT/BELFRY_TOP_Yの"
            f"値を見直してください",
            file=sys.stderr,
        )
        raise ValueError("鐘楼の高さが0以下です")

    # 修正パス(修道院の量塊を実測比に合わせる対応): NAVE_WALL_HEIGHTの変更で鐘楼の高さが
    # どれだけ縮んだかを確認できるようログに出す
    print(f"[INFO] 鐘楼: 底面高さ(base_y)={base_y}m 高さ(height)={height}m (BELFRY_TOP_Y={BELFRY_TOP_Y}m)")

    bm = bmesh.new()

    try:
        bottom_verts = []
        top_verts = []
        for i in range(BELFRY_SIDES):
            angle = BELFRY_CORNER_ANGLE_OFFSET + 2.0 * math.pi * i / BELFRY_SIDES
            x = CROSSING_CENTER_X + BELFRY_CORNER_RADIUS * math.cos(angle)
            z = CROSSING_CENTER_Z + BELFRY_CORNER_RADIUS * math.sin(angle)
            bottom_verts.append(bm.verts.new(_engine_to_blender(x, base_y, z)))
            top_verts.append(bm.verts.new(_engine_to_blender(x, base_y + height, z)))

        for i in range(BELFRY_SIDES):
            i_next = (i + 1) % BELFRY_SIDES
            bm.faces.new((bottom_verts[i], bottom_verts[i_next], top_verts[i_next], top_verts[i]))

        # 底面・天面のキャップ(天面は尖塔の底面と同径でぴったり接続するため見えないが、
        # 継ぎ目のない閉じたメッシュにするため作る)
        bottom_center = bm.verts.new(_engine_to_blender(CROSSING_CENTER_X, base_y, CROSSING_CENTER_Z))
        top_center = bm.verts.new(_engine_to_blender(CROSSING_CENTER_X, base_y + height, CROSSING_CENTER_Z))
        for i in range(BELFRY_SIDES):
            i_next = (i + 1) % BELFRY_SIDES
            bm.faces.new((bottom_center, bottom_verts[i_next], bottom_verts[i]))
            bm.faces.new((top_center, top_verts[i], top_verts[i_next]))

        # 鐘楼本体(角柱+底面・天面キャップ)はMasonry(窓・小塔本体は既定でMasonry、
        # 小塔の円錐屋根は既定でSlateRoofになるため、ここでは本体のみタグ付けする)
        _tag_new_faces(bm, 0, "Masonry")

        # アーチ列: BELFRY_WINDOW_FACE_COUNT面(等間隔)に配置する。BELFRY_SIDES=4なので
        # 4面すべてに入る。実物どおり上段3連・下段2つの2段構成にする(BELFRY_ARCADE_*参照)。
        # 【旧実装】面あたり1つだけで「600m先では影絵に出ないため1つで代表させる」と
        # していたが、実際に撮って測ると開口1つ(幅1.5m)は描かれている。3連の間隔3.08mは
        # 内部解像度で約4.5画素あり、分離して見える
        apothem = BELFRY_HALF_WIDTH  # 面の中心までの距離(=対面幅の半分)
        arcade_stages = (
            (BELFRY_ARCADE_COUNT, BELFRY_ARCADE_WIDTH, BELFRY_ARCADE_HEIGHT,
             BELFRY_ARCADE_SPACING, BELFRY_ARCADE_HEAD_BELOW_TOP),
            (BELFRY_LOWER_ARCADE_COUNT, BELFRY_LOWER_ARCADE_WIDTH, BELFRY_LOWER_ARCADE_HEIGHT,
             BELFRY_LOWER_ARCADE_SPACING, BELFRY_LOWER_ARCADE_HEAD_BELOW_TOP),
        )
        for count, opening_width, opening_height, spacing, head_below_top in arcade_stages:
            sill_y = BELFRY_TOP_Y - head_below_top - opening_height
            if sill_y < base_y:
                print(
                    f"[ERROR] 鐘楼のアーチ列の敷居({sill_y:.2f}m)が胴の底({base_y:.2f}m)より"
                    f"下にあります。BELFRY_ARCADE_*/身廊の高さを見直してください",
                    file=sys.stderr,
                )
                raise ValueError("鐘楼のアーチ列が胴に収まりません")
            if (count - 1) * spacing + opening_width > BELFRY_HALF_WIDTH * 2.0:
                print(
                    f"[ERROR] 鐘楼のアーチ列({count}連・間隔{spacing}m)が面の幅"
                    f"({BELFRY_HALF_WIDTH * 2.0}m)に収まりません",
                    file=sys.stderr,
                )
                raise ValueError("鐘楼のアーチ列が面幅に収まりません")

            for k in range(BELFRY_WINDOW_FACE_COUNT):
                i = (k * BELFRY_SIDES) // BELFRY_WINDOW_FACE_COUNT
                # 面i(頂点iとi+1の間)の中心角。頂点をBELFRY_CORNER_ANGLE_OFFSETだけ回して
                # いるので、面の中心はちょうど 2πi/BELFRY_SIDES(=±X・±Z)になる
                angle = BELFRY_CORNER_ANGLE_OFFSET + (i + 0.5) * 2.0 * math.pi / BELFRY_SIDES
                outward_x, outward_z = math.cos(angle), math.sin(angle)
                along_x, along_z = -math.sin(angle), math.cos(angle)
                face_x = CROSSING_CENTER_X + apothem * outward_x
                face_z = CROSSING_CENTER_Z + apothem * outward_z
                for j in range(count):
                    # 面の中心を挟んで左右対称に並べる
                    offset = (j - (count - 1) * 0.5) * spacing
                    _add_window_to_bmesh(
                        bm, base=(face_x + along_x * offset, sill_y, face_z + along_z * offset),
                        along_dir=(along_x, 0.0, along_z),
                        outward_dir=(outward_x, 0.0, outward_z),
                        width=opening_width, height=opening_height,
                        protrusion=BELFRY_ARCADE_PROTRUSION,
                    )

        # 小塔: **すべての隅**に1本ずつ立てる。参考写真c_belfry_spire_detail.jpgでは
        # 正方形の塔の4隅すべてに小塔がある。
        # (八角形だった頃は「窓を付けていない面の側の角だけ」という数え方をしていたが、
        #  正方形では窓が4面すべてに入るため、その式では小塔が0本になってしまう)
        turret_bottom_y = base_y + height - BELFRY_TURRET_EMBED
        turret_body_height = BELFRY_TURRET_EMBED + BELFRY_TURRET_ABOVE_TOP
        for i in range(BELFRY_SIDES):
            angle = BELFRY_CORNER_ANGLE_OFFSET + 2.0 * math.pi * i / BELFRY_SIDES
            turret_x = CROSSING_CENTER_X + BELFRY_CORNER_RADIUS * math.cos(angle)
            turret_z = CROSSING_CENTER_Z + BELFRY_CORNER_RADIUS * math.sin(angle)
            _add_octagon_turret_to_bmesh(
                bm, turret_x, turret_z, turret_bottom_y, turret_body_height,
                BELFRY_TURRET_ROOF_HEIGHT, BELFRY_TURRET_RADIUS, BELFRY_TURRET_SIDES,
            )

        # 塔の頂に載る急勾配のスレート屋根(四角錐台)。参考写真では尖塔はこの屋根の頂から
        # 立ち上がる。頂は尖らせず、尖塔の底面まで絞った錐台にして継ぎ目を無くす。
        # 天面は隅までSPIRE_BASE_RADIUSの正方形にする。尖塔は同じ外接円半径の八角形なので、
        # 八角形が正方形を常に覆い、隙間が出ない
        # このbmeshには既に小塔をbmesh.ops.create_coneで足しているため、インデックス基準の
        # _tag_new_facesは使えない(実測で屋根の面が取りこぼされてRockになっていた)
        roof_faces_before = set(bm.faces)
        roof_top_y = BELFRY_TOP_Y + BELFRY_ROOF_HEIGHT
        roof_bottom_verts = []
        roof_top_verts = []
        for i in range(BELFRY_SIDES):
            angle = BELFRY_CORNER_ANGLE_OFFSET + 2.0 * math.pi * i / BELFRY_SIDES
            cos_a, sin_a = math.cos(angle), math.sin(angle)
            bx = CROSSING_CENTER_X + BELFRY_CORNER_RADIUS * cos_a
            bz = CROSSING_CENTER_Z + BELFRY_CORNER_RADIUS * sin_a
            tx = CROSSING_CENTER_X + SPIRE_BASE_RADIUS * cos_a
            tz = CROSSING_CENTER_Z + SPIRE_BASE_RADIUS * sin_a
            roof_bottom_verts.append(bm.verts.new(_engine_to_blender(bx, BELFRY_TOP_Y, bz)))
            roof_top_verts.append(bm.verts.new(_engine_to_blender(tx, roof_top_y, tz)))
        for i in range(BELFRY_SIDES):
            i_next = (i + 1) % BELFRY_SIDES
            bm.faces.new((
                roof_bottom_verts[i], roof_bottom_verts[i_next],
                roof_top_verts[i_next], roof_top_verts[i],
            ))
        _tag_faces_since(bm, roof_faces_before, "SlateRoof")

        # 尖塔の付け根を取り巻く小尖塔の環(SPIRE_PINNACLE_*参照)。屋根の頂へ少し
        # 埋め込んでから立てる。実物では尖塔がここでいったんくびれ、小尖塔で広がってから
        # また細く立ち上がる。これが無いと「屋根から棒が生えている」ように見える
        pinnacle_bottom_y = SPIRE_BASE_Y - SPIRE_PINNACLE_EMBED
        for i in range(SPIRE_PINNACLE_COUNT):
            angle = 2.0 * math.pi * i / SPIRE_PINNACLE_COUNT
            pinnacle_x = CROSSING_CENTER_X + SPIRE_PINNACLE_RING_RADIUS * math.cos(angle)
            pinnacle_z = CROSSING_CENTER_Z + SPIRE_PINNACLE_RING_RADIUS * math.sin(angle)
            _add_octagon_turret_to_bmesh(
                bm, pinnacle_x, pinnacle_z, pinnacle_bottom_y,
                SPIRE_PINNACLE_BODY_HEIGHT, SPIRE_PINNACLE_ROOF_HEIGHT,
                SPIRE_PINNACLE_RADIUS, SPIRE_PINNACLE_SIDES,
                body_material="Masonry", roof_material="LeadRoof",
            )
    except Exception as error:  # noqa: BLE001
        print(f"[ERROR] 鐘楼の作成に失敗しました: ({error})", file=sys.stderr)
        raise

    bmesh.ops.recalc_face_normals(bm, faces=bm.faces[:])

    mesh = bpy.data.meshes.new("Belfry")
    bm.to_mesh(mesh)
    bm.free()
    mesh.update()

    obj = bpy.data.objects.new("Belfry", mesh)
    _link(obj)
    bpy.context.view_layer.objects.active = obj
    obj.select_set(True)
    return obj


def build_spire():
    """尖塔(八角錐)。鐘楼のスレート屋根の頂(SPIRE_BASE_Y)から積む。底辺半径は屋根の
    天端と同じSPIRE_BASE_RADIUS(継ぎ目が生じないように)、先端はy=SPIRE_TOP_Y
    (塔の頂から39.80m、出典あり)。

    修正パス(参考写真c_abbey_south_closeup.jpgの実測): 以前は鐘楼の天端(BELFRY_TOP_Y)から
    鐘楼と同径で直接立ち上げていたため、写真にある錐形のスレート屋根が抜け落ち、
    尖塔も太かった。屋根を鐘楼側へ追加し、尖塔はその頂から細く立ち上げる。
    出典のあるSPIRE_TOP_Yは変えていない。

    鐘楼を正方形に直したあとも、**尖塔だけは八角錐のまま**にする(写真でも尖塔は八角形)。
    そのため辺の数は鐘楼のBELFRY_SIDESではなくSPIRE_SIDESを使う。
    鐘楼の屋根の天面は隅までSPIRE_BASE_RADIUSの正方形で、この八角錐は同じ外接円半径を
    持つため常に正方形を覆い、継ぎ目に隙間が出ない。

    修正パス(写真との並置): 直線の円錐(primitive_cone_add)では、写真の「根元で急に
    細くなってから針のように立つ」輪郭にならず、ずんぐりして見えた。高さ方向を
    SPIRE_PROFILE_SEGMENTSに分け、半径を r = R * (1-t)^SPIRE_PROFILE_EXPONENT で
    与えて内側へ反った輪郭にする(指数の根拠はSPIRE_PROFILE_EXPONENTのコメント)。
    このためbmeshで直接組み立てる。
    """
    bm = bmesh.new()

    try:
        height = SPIRE_TOP_Y - SPIRE_BASE_Y
        rings = []
        for j in range(SPIRE_PROFILE_SEGMENTS):
            t = j / SPIRE_PROFILE_SEGMENTS
            radius = SPIRE_BASE_RADIUS * ((1.0 - t) ** SPIRE_PROFILE_EXPONENT)
            # 遠景で消えないための下限(SPIRE_MIN_RADIUSのコメント参照)。
            # 先端は最上段のリングからapexへ絞るので、針の形そのものは保たれる
            radius = max(radius, SPIRE_MIN_RADIUS)
            y = SPIRE_BASE_Y + height * t
            ring = []
            for i in range(SPIRE_SIDES):
                angle = 2.0 * math.pi * i / SPIRE_SIDES
                x = CROSSING_CENTER_X + radius * math.cos(angle)
                z = CROSSING_CENTER_Z + radius * math.sin(angle)
                ring.append(bm.verts.new(_engine_to_blender(x, y, z)))
            rings.append(ring)

        apex = bm.verts.new(_engine_to_blender(CROSSING_CENTER_X, SPIRE_TOP_Y, CROSSING_CENTER_Z))

        for j in range(SPIRE_PROFILE_SEGMENTS - 1):
            for i in range(SPIRE_SIDES):
                i_next = (i + 1) % SPIRE_SIDES
                bm.faces.new((rings[j][i], rings[j][i_next], rings[j + 1][i_next], rings[j + 1][i]))
        # 最上段のリングから先端へ
        top_ring = rings[-1]
        for i in range(SPIRE_SIDES):
            bm.faces.new((top_ring[i], top_ring[(i + 1) % SPIRE_SIDES], apex))
        # 底面のキャップ(鐘楼の屋根に埋もれて見えないが、閉じたメッシュにするため作る)
        bottom_center = bm.verts.new(_engine_to_blender(CROSSING_CENTER_X, SPIRE_BASE_Y, CROSSING_CENTER_Z))
        for i in range(SPIRE_SIDES):
            i_next = (i + 1) % SPIRE_SIDES
            bm.faces.new((bottom_center, rings[0][i_next], rings[0][i]))

        # 尖塔は全面なまり葺き(LeadRoof)
        _tag_new_faces(bm, 0, "LeadRoof")
    except Exception as error:  # noqa: BLE001
        print(f"[ERROR] 尖塔の作成に失敗しました: ({error})", file=sys.stderr)
        raise

    bmesh.ops.recalc_face_normals(bm, faces=bm.faces[:])

    mesh = bpy.data.meshes.new("Spire")
    bm.to_mesh(mesh)
    bm.free()
    mesh.update()

    obj = bpy.data.objects.new("Spire", mesh)
    _link(obj)
    bpy.context.view_layer.objects.active = obj
    obj.select_set(True)
    return obj


def _add_wing_to_bmesh(bm, root, span_dir, thickness_dir, length, width, thickness):
    """翼(斜めに開く薄い板)を1枚bmeshへ追加する。像の翼のような、水平・垂直のどちらの
    軸とも揃わない向きの薄い直方体を作るための汎用ヘルパー(_add_flat_box_to_bmeshは
    「上方向は常にエンジン空間のY」という前提のため、斜めの翼には使えない)。

    root: 付け根の中心(エンジン空間座標)。span_dir: 翼が伸びる方向の単位ベクトル(長さlength)。
    thickness_dir: 板の厚み方向の単位ベクトル(span_dirと直交している必要がある)。
    width(翼弦方向の幅)方向は、span_dirとthickness_dirの外積から自動的に求める。
    """
    root_x, root_y, root_z = root
    sx, sy, sz = span_dir
    tx, ty, tz = thickness_dir
    wx = sy * tz - sz * ty
    wy = sz * tx - sx * tz
    wz = sx * ty - sy * tx
    wlen = math.sqrt(wx * wx + wy * wy + wz * wz)
    if wlen < 1.0e-9:
        print("[ERROR] 翼のspan_dirとthickness_dirが平行です(外積が縮退)。ベクトルを見直してください", file=sys.stderr)
        raise ValueError("翼の方向ベクトルが縮退しました")
    wx, wy, wz = wx / wlen, wy / wlen, wz / wlen

    def point(along, w, t):
        engine_x = root_x + along * sx + w * wx + t * tx
        engine_y = root_y + along * sy + w * wy + t * ty
        engine_z = root_z + along * sz + w * wz + t * tz
        return _engine_to_blender(engine_x, engine_y, engine_z)

    half_w = width * 0.5
    half_t = thickness * 0.5

    r00 = bm.verts.new(point(0.0, -half_w, -half_t))
    r10 = bm.verts.new(point(0.0, half_w, -half_t))
    r11 = bm.verts.new(point(0.0, half_w, half_t))
    r01 = bm.verts.new(point(0.0, -half_w, half_t))
    p00 = bm.verts.new(point(length, -half_w, -half_t))
    p10 = bm.verts.new(point(length, half_w, -half_t))
    p11 = bm.verts.new(point(length, half_w, half_t))
    p01 = bm.verts.new(point(length, -half_w, half_t))

    bm.faces.new((r00, r10, p10, p00))
    bm.faces.new((r10, r11, p11, p10))
    bm.faces.new((r11, r01, p01, p11))
    bm.faces.new((r01, r00, p00, p01))
    bm.faces.new((p00, p10, p11, p01))  # 先端
    bm.faces.new((r01, r11, r10, r00))  # 付け根


def build_statue():
    """聖ミカエル像(簡略プレースホルダー)。尖塔の先端(SPIRE_TOP_Y)から像の頂
    (STATUE_TOP_Y、出典あり: 尖塔の頂→像の頂4.00m)まで。600m先では2〜3pxにしかならない
    ため、人物・竜・翼の詳細な造形はせず、「翼を広げた輪郭が分かる程度」の簡略形状にする
    (承認済み計画の方針): 縦長の箱(胴体)+左右に斜めに開く薄い板(翼)。
    """
    bm = bmesh.new()
    base = (CROSSING_CENTER_X, SPIRE_TOP_Y, CROSSING_CENTER_Z)

    try:
        # 胴体(縦長の箱。底面はSPIRE_TOP_Y、天面はSTATUE_TOP_Yに一致する)
        _add_flat_box_to_bmesh(
            bm, base=base,
            along_dir=(0.0, 0.0, 1.0), across_dir=(1.0, 0.0, 0.0),
            depth=STATUE_BODY_DEPTH, width=STATUE_BODY_WIDTH, height=STATUE_BODY_HEIGHT,
        )

        # 翼(左右に1枚ずつ、外側・やや上向きに開く薄い板)
        angle = math.radians(STATUE_WING_ANGLE_DEG)
        for side in (-1.0, 1.0):
            span_dir = (side * math.cos(angle), math.sin(angle), 0.0)
            root = (
                base[0] + side * STATUE_BODY_WIDTH * 0.5,
                base[1] + STATUE_WING_ROOT_HEIGHT,
                base[2],
            )
            _add_wing_to_bmesh(
                bm, root=root, span_dir=span_dir, thickness_dir=(0.0, 0.0, 1.0),
                length=STATUE_WING_LENGTH, width=STATUE_WING_WIDTH, thickness=STATUE_WING_THICKNESS,
            )
    except Exception as error:  # noqa: BLE001
        print(f"[ERROR] 聖ミカエル像の作成に失敗しました: ({error})", file=sys.stderr)
        raise

    # 聖ミカエル像は全面Gilt(金泥)
    _tag_new_faces(bm, 0, "Gilt")

    bmesh.ops.recalc_face_normals(bm, faces=bm.faces[:])

    mesh = bpy.data.meshes.new("Statue")
    bm.to_mesh(mesh)
    bm.free()
    mesh.update()

    obj = bpy.data.objects.new("Statue", mesh)
    _link(obj)
    bpy.context.view_layer.objects.active = obj
    obj.select_set(True)
    return obj


def _apply_box_projection_uv(island):
    """マテリアルごとのタイルサイズで、ワールド空間のボックス投影UVを作る。

    テクスチャはタイル状に繰り返して貼るため、島全体を展開する必要はなく、
    面の法線が最も向いている軸に沿って平面投影すればよい。これでテクセル密度が
    実寸(メートル)に対して全面で揃う。

    bpy.ops.uv.cube_projectはオペレータのコンテキスト(選択状態・ビュー)に依存し、
    面ごとに投影軸を選べないため使わず、ここでは自前でpolygonごとに計算する。
    """
    try:
        mesh = island.data
        if len(mesh.uv_layers) == 0:
            mesh.uv_layers.new(name="UVMap")
        uv_data = mesh.uv_layers[0].data

        axis_face_counts = {"X": 0, "Y": 0, "Z": 0}

        for poly in mesh.polygons:
            mat_name = ISLAND_MATERIALS[poly.material_index][0]
            scale = MATERIAL_UV_TILE_METERS.get(mat_name, 5.0)

            normal = poly.normal
            abs_normal = (abs(normal.x), abs(normal.y), abs(normal.z))
            max_component = max(abs_normal)

            # 最大成分がZ(Blenderの上下)の面が最も多い想定のため、Zを優先して判定する
            # (同値の場合の判定順は出典なしの決め値)
            if abs_normal[2] == max_component:
                axis = "Z"
            elif abs_normal[0] == max_component:
                axis = "X"
            else:
                axis = "Y"
            axis_face_counts[axis] += 1

            for loop_index in range(poly.loop_start, poly.loop_start + poly.loop_total):
                vertex_index = mesh.loops[loop_index].vertex_index
                co = mesh.vertices[vertex_index].co  # オブジェクトの変換行列は単位行列のためローカル=ワールド

                if axis == "Z":
                    # 屋根面・水平面。上から見た投影
                    u = co.x / scale
                    v = co.y / scale
                elif axis == "X":
                    # 壁面。vをBlenderのZ(=高さ)にすることで、石積みの段やスレートの段が
                    # 水平に並ぶようにする(意図的。この対応関係を変えないこと)
                    u = co.y / scale
                    v = co.z / scale
                else:  # axis == "Y"
                    # 壁面。Xと同じ理由でvをZ(高さ)にする
                    u = co.x / scale
                    v = co.z / scale

                uv_data[loop_index].uv = (u, v)

        print(
            f"[INFO] UV投影: X軸={axis_face_counts['X']} Y軸={axis_face_counts['Y']} "
            f"Z軸={axis_face_counts['Z']}"
        )
    except Exception as error:  # noqa: BLE001
        print(f"[ERROR] ボックス投影UVの生成に失敗しました: ({error})", file=sys.stderr)
        raise


def _warn_untagged_faces(all_parts, rock_obj):
    """岩以外のパーツにmaterial_index=0(=Rock)の面が混ざっていないか点検する。

    material_indexの既定値は0なので、タグ付けを取りこぼした面は黙ってRockになり、
    石造りのはずの箇所が岩のテクスチャで描かれる。遠景では色が近く目視で気づけないため、
    ここで面数として検出する。実際にこの取りこぼしが起きていた(_tag_faces_since参照)。
    """
    total = 0
    for obj in all_parts:
        if obj is rock_obj:
            continue
        count = sum(1 for poly in obj.data.polygons if poly.material_index == 0)
        if count:
            total += count
            print(
                f"[WARNING] {obj.name}: マテリアル未タグの面が{count}面あります"
                f"(既定値のmaterial_index=0=Rockのまま)"
            )
    if total:
        print(f"[WARNING] マテリアル未タグの面の合計={total}面。タグ付けの取りこぼしを直してください")


def build_island():
    """島全体のパーツを組み立て、1つのメッシュオブジェクト「Island」へ結合して返す。"""
    _clear_scene()

    rock = build_rock()
    rampart_parts = build_rampart()
    towers = build_towers()
    village = build_village()
    vegetation = build_vegetation()
    slope_terraces = build_slope_terraces()
    west_end = build_west_end()
    church = build_church()
    abbey_blocks = build_abbey_blocks()
    merveille = build_merveille()
    abbey_substructure = build_abbey_substructure()

    # 鐘楼(belfry)・尖塔(spire)・像(statue)はいずれもbuild_*内部で
    # (CROSSING_CENTER_X, CROSSING_CENTER_Z)の真上に配置済み(教会・翼廊の交差部)
    belfry = build_belfry()
    spire = build_spire()
    statue = build_statue()

    all_parts = [
        rock, *rampart_parts, *towers, village, vegetation, slope_terraces, west_end,
        church, abbey_blocks, merveille, abbey_substructure, belfry, spire, statue,
    ]

    # 全パーツへ共通の順序(ISLAND_MATERIALS順)でマテリアルスロットを割り当てる。
    # 面のmaterial_indexは各build_*内で既に設定済みのため、スロット順さえ揃えれば
    # このあとのjoinで正しいマテリアルが引かれる
    for obj in all_parts:
        _assign_material_slots(obj)

    _warn_untagged_faces(all_parts, rock)

    for obj in all_parts:
        obj.select_set(True)
    bpy.context.view_layer.objects.active = rock
    bpy.ops.object.join()

    island = bpy.context.active_object
    island.name = "Island"

    # glTFエクスポータのタンジェント計算はtris/quadsのみ対応(NGON面が残っていると失敗する。
    # 円錐台・円柱の端面が既定でNGONになっているため)。全面を三角形化して確実に対応させる
    bpy.ops.object.mode_set(mode='EDIT')
    bpy.ops.mesh.select_all(action='SELECT')
    bpy.ops.mesh.quads_convert_to_tris(quad_method='BEAUTY', ngon_method='BEAUTY')
    bpy.ops.object.mode_set(mode='OBJECT')

    _apply_box_projection_uv(island)

    # 全パーツ結合・三角形化後の頂点数・三角形数をログへ出す(密度向上作業での確認用)
    print(f"[INFO] Island: 頂点数={len(island.data.vertices)} 三角形数={len(island.data.polygons)}")

    return island


def export_gltf(path):
    """指定パスへglTF(GLTF_SEPARATE, .gltf+.bin)をエクスポートする。"""
    out_dir = os.path.dirname(path)
    try:
        os.makedirs(out_dir, exist_ok=True)
    except OSError as error:
        print(f"[ERROR] 出力ディレクトリの作成に失敗しました: {out_dir} ({error})", file=sys.stderr)
        raise

    try:
        bpy.ops.export_scene.gltf(
            filepath=path,
            export_format='GLTF_SEPARATE',
            export_tangents=True,
            export_yup=True,
            export_apply=True,
            export_materials=True,
        )
    except Exception as error:  # noqa: BLE001 - Blenderオペレータの例外型は多岐にわたるため広く捕捉する
        print(f"[ERROR] glTFのエクスポートに失敗しました: {path} ({error})", file=sys.stderr)
        raise

    print(f"wrote {path}")


def add_camera(name, position, forward, fov_y_degrees=PREVIEW_FOV_Y_DEGREES):
    """指定位置・向きのカメラを追加する。

    forwardはBlenderのワールド空間(Z-up)での前方向ベクトル。カメラのローカル-Z軸を
    forwardへ、ローカルY軸をできるだけワールドZ(上方向)へ向くようto_track_quatで
    解く(手動でオイラー角を導出するより符号ミスが起きにくいため)。
    """
    cam_data = bpy.data.cameras.new(name)
    cam_data.sensor_fit = 'VERTICAL'
    cam_data.angle_y = math.radians(fov_y_degrees)
    # Blenderの新規カメラの既定のclip_endは島より近い(遠方の較正ビューnorth_far(6000m)が
    # 真っ白ならぬ背景単色のまま出力され、抽出が「島の画素が1つも無い」で落ちて発覚した)。
    # このスクリプトのカメラはすべて島(半径150m程度)を写すためだけのもので、
    # 深度バッファの精度が問題になる用途は無いため、余裕をもった一律の値にする
    cam_data.clip_end = CAMERA_CLIP_END

    cam_obj = bpy.data.objects.new(name, cam_data)
    _link(cam_obj)
    cam_obj.location = position

    direction = Vector(forward)
    cam_obj.rotation_mode = 'QUATERNION'
    cam_obj.rotation_quaternion = direction.to_track_quat('-Z', 'Y')
    return cam_obj


def setup_lighting():
    """太陽光(SUN)を2つ追加する。

    ステップ2のレビューで「影が濃すぎて目視確認しづらい」との指摘があったための変更
    (厳密な物理的正しさは不要、目視確認のしやすさを優先する決め値でよいとの指示):
    主光源(Key)の強度を5→3へ弱め、さらに反対側・低い角度からのフィルライトを1本足して
    影を完全には潰さない程度に柔らかくする。
    """
    bpy.ops.object.light_add(type='SUN', location=(0.0, 0.0, 300.0))
    key_sun = bpy.context.active_object
    key_sun.name = "KeySun"
    key_sun.data.energy = 3.0
    key_sun.rotation_euler = (math.radians(55.0), 0.0, math.radians(35.0))

    # 主光源とは反対側(Z回転を180度ずらす)・より低い角度(X回転を90度に近づける=水平に近い
    # 光線=グレージング角)からの弱いフィルライト。影の中を完全に潰さない程度の強さにする
    bpy.ops.object.light_add(type='SUN', location=(0.0, 0.0, 300.0))
    fill_sun = bpy.context.active_object
    fill_sun.name = "FillSun"
    # 修正パス(レビュー): 背景色(青)を強度1.0で環境光として当てると石の暖色が
    # 打ち消されて無彩色に見えるため、フィルライトの強度も0.5へ下げる(KeySunは据え置き)
    fill_sun.data.energy = 0.5
    fill_sun.rotation_euler = (math.radians(80.0), 0.0, math.radians(35.0 + 180.0))

    return key_sun, fill_sun


def setup_render_settings(scene):
    """Cyclesレンダーエンジンを有効化し、プレビュー用の解像度・サンプル数を設定する。

    【削除した処理について】以前ここでレンダ結果を水平反転するコンポジットを組んでいた。
    Blenderのプレビューの左右が実機と合わないのを「右手系(Blender)と左手系(実機)の
    描画規約の差」と解釈した対症療法だったが、真の原因は軸変換のZの符号の誤りだった
    (_engine_to_blenderのdocstring参照)。Zの符号を直すと
      Blender: 画面右 = forward × up = +blender_x = engine_x = 東
      実機:    画面右 = up × forward = +world_x = engine_x = 東
    となって両者が一致するため、水平反転は不要になった。

    軸の符号を直す代わりに絵を反転して辻褄を合わせていたので、
    「プレビューと実機が一致した」という当時の確認は、実際には南面と北面という
    別の面どうしを見比べていた。対症療法で見かけを合わせると検証も一緒に壊れる。
    """
    try:
        addon_utils.enable("cycles", default_set=True, persistent=False)
    except Exception as error:  # noqa: BLE001
        print(f"[ERROR] Cyclesアドオンの有効化に失敗しました: ({error})", file=sys.stderr)
        raise

    scene.render.engine = 'CYCLES'
    scene.cycles.samples = PREVIEW_SAMPLES
    scene.render.resolution_x = PREVIEW_RESOLUTION_X
    scene.render.resolution_y = PREVIEW_RESOLUTION_Y
    scene.render.resolution_percentage = 100
    scene.render.image_settings.file_format = 'PNG'


def _engine_lookat_to_blender(position_engine, target_engine):
    """エンジン空間(X, Y=高さ, Z=奥行き、Y-up)でのカメラ位置とその注視点(見る対象の点)から、
    Blenderのネイティブ座標(Z-up)でのカメラ位置と正規化済み前方向ベクトルを求める。

    village_closeup/abbey_closeupは近距離から特定の対象(集落・城壁、修道院本体)を
    画面に大きく収めたいため、main/side/topのような固定ピッチではなく注視点を直接
    指定できるこの方式にした(build_rockの頂点生成と同じ軸変換規則
    blender_x=engine_x, blender_y=engine_z, blender_z=engine_yを、位置・方向ベクトルの
    両方に適用する。理由は_engine_to_blenderのdocstring参照)。
    """
    dx = target_engine[0] - position_engine[0]
    dy = target_engine[1] - position_engine[1]
    dz = target_engine[2] - position_engine[2]
    length = math.sqrt(dx * dx + dy * dy + dz * dz)
    if length < 1.0e-6:
        print(f"[ERROR] プレビューカメラの注視点が位置と一致しています: position={position_engine} target={target_engine}", file=sys.stderr)
        raise ValueError("カメラ位置と注視点が一致しています")

    forward_engine = (dx / length, dy / length, dz / length)
    # モデル側と同じ軸変換規則(blender_y=engine_z)をカメラの位置・方向にも適用する
    blender_position = (position_engine[0], position_engine[2], position_engine[1])
    blender_forward = (forward_engine[0], forward_engine[2], forward_engine[1])
    return blender_position, blender_forward


def _setup_world_background(color, strength):
    """ワールド背景(空)の色・強度を設定する(地面の有無に関わらず共通の処理)。

    _setup_preview_world_and_ground()(地面あり、--preview用)と
    render_compare()(地面なし、--compare用)の両方から呼べるよう分離した。
    """
    scene = bpy.context.scene
    try:
        world = scene.world
        if world is None:
            world = bpy.data.worlds.new("PreviewWorld")
            scene.world = world
        world.use_nodes = True
        background = world.node_tree.nodes.get("Background")
        if background is None:
            print("[ERROR] ワールドのBackgroundノードが見つかりません", file=sys.stderr)
            raise RuntimeError("ワールドのBackgroundノードが見つかりません")
        background.inputs["Color"].default_value = (color[0], color[1], color[2], 1.0)
        background.inputs["Strength"].default_value = strength
    except Exception as error:  # noqa: BLE001
        print(f"[ERROR] ワールド背景の設定に失敗しました: ({error})", file=sys.stderr)
        raise


def _setup_preview_world_and_ground():
    """プレビュー専用のワールド背景(空)と地面(干潟)を追加する。

    エクスポートするglTFにはワールド背景も地面も一切含めない(export_gltf()の経路では
    build_island()の後この関数を呼ばないため混入しない)。地面はエンジン空間のy=0
    (=Blenderのz=0)に一辺4000mの平面として配置し、名前をPreviewGroundにする。
    """
    # 修正パス(レビュー): 背景色(青)を強度1.0で環境光として当てると石の暖色が
    # 打ち消されて無彩色に見えるため、強度を0.5へ下げる(色自体は変更しない)
    _setup_world_background((0.30, 0.42, 0.58), 0.5)

    try:
        bpy.ops.mesh.primitive_plane_add(size=4000.0, location=(0.0, 0.0, 0.0))
        ground = bpy.context.active_object
        ground.name = "PreviewGround"

        sand_mat = bpy.data.materials.get("PreviewSand")
        if sand_mat is None:
            sand_mat = bpy.data.materials.new("PreviewSand")
            sand_mat.use_nodes = True
            bsdf = sand_mat.node_tree.nodes.get("Principled BSDF")
            if bsdf is None:
                print("[ERROR] PreviewSandマテリアルにPrincipled BSDFノードが見つかりません", file=sys.stderr)
                raise RuntimeError("PreviewSandマテリアルにPrincipled BSDFノードが見つかりません")
            bsdf.inputs["Base Color"].default_value = (0.550, 0.500, 0.440, 1.0)
            bsdf.inputs["Roughness"].default_value = 0.95
            bsdf.inputs["Metallic"].default_value = 0.0
        ground.data.materials.append(sand_mat)
    except Exception as error:  # noqa: BLE001
        print(f"[ERROR] プレビュー用地面(干潟)の作成に失敗しました: ({error})", file=sys.stderr)
        raise


def render_previews(out_dir):
    """main / main_mid / side / east / north / top / aerial_sw / aerial_se / aerial_ne /
    village_closeup / abbey_closeup / veg_closeupの12枚をCyclesでレンダリングする。

    カメラ位置・向きはScenes/MontSaintMichel.kscene([Camera] Position=(0,1.6,-600),
    Yaw=0, Pitch=2)のKurenaiEngine側の定義(X, Y=高さ, Z=奥行き、Y-up)を、Blenderの
    エクスポータの軸変換規則(gltf_x=blender_x, gltf_y=blender_z, gltf_z=-blender_y)の
    逆変換(blender_x=engine_x, blender_y=engine_z, blender_z=engine_y。Xは反転せず
    Zは反転する。理由は_engine_to_blenderのdocstring参照)でBlenderのネイティブ座標
    (Z-up)へ変換した値。この規則なら画面の左右が実機と一致するため、レンダ結果の
    反転処理は不要(setup_render_settingsのdocstring参照)。

    ワールド背景・地面(干潟)はプレビュー専用(export_gltf()の経路では呼ばれない
    _setup_preview_world_and_ground()の中だけで生成する)。
    """
    try:
        os.makedirs(out_dir, exist_ok=True)
    except OSError as error:
        print(f"[ERROR] プレビュー出力ディレクトリの作成に失敗しました: {out_dir} ({error})", file=sys.stderr)
        raise

    build_island()
    _setup_preview_world_and_ground()
    setup_lighting()

    scene = bpy.context.scene
    setup_render_settings(scene)

    pitch = math.radians(PREVIEW_PITCH_DEGREES)
    cos_p, sin_p = math.cos(pitch), math.sin(pitch)

    # main_mid: 南から中距離。参考写真の定番アングル(全景+建物のディテールの中間)
    main_mid_pos, main_mid_fwd = _engine_lookat_to_blender(
        position_engine=(0.0, 60.0, -320.0), target_engine=(0.0, 60.0, 0.0))
    # east: 東側の立面(城壁・Tour Gabriel方面)の確認用
    east_pos, east_fwd = _engine_lookat_to_blender(
        position_engine=(600.0, 30.0, 0.0), target_engine=(0.0, 40.0, 0.0))
    # north: 北側(ラ・メルヴェイユ側)の立面の確認用
    north_pos, north_fwd = _engine_lookat_to_blender(
        position_engine=(0.0, 30.0, 600.0), target_engine=(0.0, 40.0, 0.0))
    # aerial_sw: 南西からの空撮アングル(西側斜面の植生・崖の確認用)
    aerial_sw_pos, aerial_sw_fwd = _engine_lookat_to_blender(
        position_engine=(-300.0, 260.0, -300.0), target_engine=(0.0, 60.0, 0.0))
    # aerial_se: 南東からの空撮アングル(集落側の確認用)
    aerial_se_pos, aerial_se_fwd = _engine_lookat_to_blender(
        position_engine=(300.0, 240.0, -300.0), target_engine=(0.0, 60.0, 0.0))
    # aerial_ne: 北東からの空撮アングル(修道院・城壁北東側の確認用)
    aerial_ne_pos, aerial_ne_fwd = _engine_lookat_to_blender(
        position_engine=(300.0, 250.0, 300.0), target_engine=(0.0, 60.0, 0.0))
    # veg_closeup: 西斜面の植生の確認用(木の密度・大きさが分かる距離まで寄せる)
    veg_closeup_pos, veg_closeup_fwd = _engine_lookat_to_blender(
        position_engine=(-300.0, 110.0, -140.0), target_engine=(-70.0, 65.0, -60.0))

    # 集落・城壁のクローズアップ: 南側から見て、城壁の裾(南、高さ約15m)を注視点にする。
    # 岩の基部半径(ROCK_BASE_RADIUS=153m)より十分外側の距離280mから見下ろす
    village_closeup_pos, village_closeup_fwd = _engine_lookat_to_blender(
        position_engine=(0.0, 70.0, -280.0), target_engine=(0.0, 20.0, -150.0))
    # 修道院クローズアップ: 北側から見て、教会〜鐘楼〜尖塔の複合体の中間高さ(床80m〜像頂158.5mの
    # ほぼ中央≒119m)を注視点にする。距離200mまで寄せ、複合体全体が画面に収まる範囲で
    # できるだけ大きく見えるようにする(300mでは複合体が小さすぎたための調整)
    abbey_closeup_pos, abbey_closeup_fwd = _engine_lookat_to_blender(
        position_engine=(0.0, 120.0, 200.0), target_engine=(0.0, 119.0, 20.0))

    # (名前, Blender空間でのカメラ位置, Blender空間での前方向)
    views = [
        ("main", (0.0, -600.0, 1.6), (0.0, cos_p, sin_p)),   # engine: pos=(0,1.6,-600) 前方=+Z
        # main_mid: 南から中距離の定番アングルの確認用
        ("main_mid", main_mid_pos, main_mid_fwd),
        # side: 西から東を見る立面(engine: pos=(-600,1.6,0) 前方=+X)
        ("side", (-600.0, 0.0, 1.6), (cos_p, 0.0, sin_p)),
        # east: 東側の立面の確認用
        ("east", east_pos, east_fwd),
        # north: 北側(ラ・メルヴェイユ側)の立面の確認用
        ("north", north_pos, north_fwd),
        ("top", (0.0, 0.0, 500.0), (0.0, 0.0, -1.0)),        # engine: pos=(0,500,0) 前方=-Y(真下)
        # aerial_sw: 南西からの空撮アングルの確認用
        ("aerial_sw", aerial_sw_pos, aerial_sw_fwd),
        # aerial_se: 南東からの空撮アングルの確認用
        ("aerial_se", aerial_se_pos, aerial_se_fwd),
        # aerial_ne: 北東からの空撮アングルの確認用
        ("aerial_ne", aerial_ne_pos, aerial_ne_fwd),
        # 集落・城壁のディテール確認用に南側から近距離で寄ったアングル(城壁の裾を注視)
        ("village_closeup", village_closeup_pos, village_closeup_fwd),
        # 修道院・鐘楼・尖塔の確認用に北側から寄ったアングル(複合体の中間高さを注視)
        ("abbey_closeup", abbey_closeup_pos, abbey_closeup_fwd),
        # veg_closeup: 西斜面の植生の確認用
        ("veg_closeup", veg_closeup_pos, veg_closeup_fwd),
    ]

    for view_name, position, forward in views:
        camera = add_camera(f"Camera_{view_name}", position, forward)
        scene.camera = camera

        output_path = os.path.join(out_dir, f"{view_name}.png")
        scene.render.filepath = output_path
        try:
            bpy.ops.render.render(write_still=True)
        except Exception as error:  # noqa: BLE001
            print(f"[ERROR] プレビューのレンダリングに失敗しました: {output_path} ({error})", file=sys.stderr)
            raise
        print(f"wrote {output_path}")

        # camera(オブジェクト)を先にremoveすると以後Python側の参照が無効化されるため、
        # data(カメラデータブロック)への参照は先に取っておく
        camera_data = camera.data
        bpy.data.objects.remove(camera, do_unlink=True)
        if camera_data.users == 0:
            bpy.data.cameras.remove(camera_data)


def render_compare(out_dir):
    """COMPARE_VIEWSの各ビューを、参考写真との突き合わせ用にCyclesでレンダリングする。

    ビューごとに2枚出力する(タスクA):
      - <name>.png      : --previewと同じ見た目(青空+砂地の地面、view_transformは既定のまま)。
                           並置画像(側にレンダ結果を並べる画像)で目視比較するための見た目版。
      - <name>_mask.png : マゼンタ背景・地面無し・view_transform=Standardのマスク版。
                           compare_reference.py側のスカイライン抽出・指標算出専用
                           (地面が画面を横切ると地面の水平線を島の輪郭と誤認してしまうため。
                           COMPARE_BACKGROUND_COLORのコメント参照)。

    build_island()は1回だけ呼び、ワールド・地面・view_transformを切り替えて2回レンダする
    (地面オブジェクトは1枚目のレンダ後にhide_renderで隠し、2枚目の前にremoveする)。
    解像度だけCOMPARE_RESOLUTION_X/Yへsetup_render_settings()呼び出し後に上書きする
    (PREVIEW_RESOLUTION_*自体は変更しない)。
    """
    try:
        os.makedirs(out_dir, exist_ok=True)
    except OSError as error:
        print(f"[ERROR] 比較用出力ディレクトリの作成に失敗しました: {out_dir} ({error})", file=sys.stderr)
        raise

    build_island()
    setup_lighting()

    scene = bpy.context.scene
    setup_render_settings(scene)
    scene.render.resolution_x = COMPARE_RESOLUTION_X
    scene.render.resolution_y = COMPARE_RESOLUTION_Y

    # 1枚目: 見た目版(青空+地面、--previewと同じ設定)。view_transformは既定のまま
    _setup_preview_world_and_ground()
    ground_obj = bpy.data.objects.get("PreviewGround")

    for view in COMPARE_VIEWS:
        name = view["name"]
        position, forward = _engine_lookat_to_blender(view["position"], view["target"])
        camera = add_camera(f"Camera_{name}", position, forward, fov_y_degrees=view["fov_y"])
        scene.camera = camera

        output_path = os.path.join(out_dir, f"{name}.png")
        scene.render.filepath = output_path
        try:
            bpy.ops.render.render(write_still=True)
        except Exception as error:  # noqa: BLE001
            print(f"[ERROR] 比較用レンダリング(見た目版)に失敗しました: {output_path} ({error})", file=sys.stderr)
            raise
        print(f"wrote {output_path}")

        # camera(オブジェクト)を先にremoveすると以後Python側の参照が無効化されるため、
        # data(カメラデータブロック)への参照は先に取っておく
        camera_data = camera.data
        bpy.data.objects.remove(camera, do_unlink=True)
        if camera_data.users == 0:
            bpy.data.cameras.remove(camera_data)

    # 2枚目: マスク版(マゼンタ背景、地面無し)。地面オブジェクトを削除してからワールド・
    # view_transformを切り替える
    if ground_obj is not None:
        try:
            ground_mesh = ground_obj.data
            bpy.data.objects.remove(ground_obj, do_unlink=True)
            if ground_mesh.users == 0:
                bpy.data.meshes.remove(ground_mesh)
        except Exception as error:  # noqa: BLE001
            print(f"[ERROR] マスク版レンダ前の地面(PreviewGround)の削除に失敗しました: ({error})", file=sys.stderr)
            raise
    else:
        print("[WARNING] マスク版レンダ前に地面(PreviewGround)が見つかりませんでした(削除をスキップします)")

    _setup_world_background(COMPARE_BACKGROUND_COLOR, 1.0)

    # 修正パス(コーディネーター指摘で発覚): Blenderの既定の色管理(Filmic)は、
    # 背景のマゼンタ(1.0, 0.0, 1.0)をPNGへ書き出す際にトーンマッピングで大きく変色させて
    # しまい(実測でRGB(0.81, 0.004, 0.81)程度まで彩度・明度が落ちる)、
    # compare_reference.py側の背景色距離マスクが背景ピクセルまで「島」と誤判定する
    # 不具合があった。マスク版限定でview_transformをStandard(トーンマッピング無し)に
    # 切り替え、保存されるPNGの背景色が指定どおりの値に近くなるようにする
    # (見た目版・--preview/--exportの経路には影響しない)
    try:
        scene.view_settings.view_transform = 'Standard'
    except Exception as error:  # noqa: BLE001
        print(f"[ERROR] --compare用の色管理(view_transform)の設定に失敗しました: ({error})", file=sys.stderr)
        raise

    for view in COMPARE_VIEWS:
        name = view["name"]
        position, forward = _engine_lookat_to_blender(view["position"], view["target"])
        camera = add_camera(f"Camera_{name}_mask", position, forward, fov_y_degrees=view["fov_y"])
        scene.camera = camera

        output_path = os.path.join(out_dir, f"{name}_mask.png")
        scene.render.filepath = output_path
        try:
            bpy.ops.render.render(write_still=True)
        except Exception as error:  # noqa: BLE001
            print(f"[ERROR] 比較用レンダリング(マスク版)に失敗しました: {output_path} ({error})", file=sys.stderr)
            raise
        print(f"wrote {output_path}")

        camera_data = camera.data
        bpy.data.objects.remove(camera, do_unlink=True)
        if camera_data.users == 0:
            bpy.data.cameras.remove(camera_data)


def _parse_args():
    argv = sys.argv
    if "--" in argv:
        argv = argv[argv.index("--") + 1:]
    else:
        argv = []

    export_path = None
    preview_dir = None
    compare_dir = None
    material_id = False
    i = 0
    while i < len(argv):
        token = argv[i]
        if token == "--export" and i + 1 < len(argv):
            export_path = argv[i + 1]
            i += 2
        elif token == "--preview" and i + 1 < len(argv):
            preview_dir = argv[i + 1]
            i += 2
        elif token == "--compare" and i + 1 < len(argv):
            compare_dir = argv[i + 1]
            i += 2
        elif token == "--material-id":
            material_id = True
            i += 1
        else:
            print(f"[WARNING] 未知の引数を無視しました: {token}", file=sys.stderr)
            i += 1

    return export_path, preview_dir, compare_dir, material_id


def main():
    global MATERIAL_ID_MODE

    export_path, preview_dir, compare_dir, material_id = _parse_args()
    # マテリアルを作る前に立てる必要がある(_create_island_materials()は結果をキャッシュする)
    MATERIAL_ID_MODE = material_id
    if MATERIAL_ID_MODE:
        print("[INFO] 材質IDモード: ベースカラーをMATERIAL_ID_PALETTEへ差し替えて書き出します")

    if export_path is None and preview_dir is None and compare_dir is None:
        print("--export/--preview/--compareのいずれも指定されなかったため、何も実行せずに終了します")
        return

    # Blenderの scene.render.filepath などは、相対パスをPythonのos.getcwd()とは異なる基準
    # (未保存の.blendファイルの既定ディレクトリ)で解決することがあるため、渡された時点で
    # os.getcwd()(=Blenderを起動したプロセスの作業ディレクトリ)基準の絶対パスへ変換しておく
    if export_path is not None:
        export_path = os.path.abspath(export_path)
    if preview_dir is not None:
        preview_dir = os.path.abspath(preview_dir)
    if compare_dir is not None:
        compare_dir = os.path.abspath(compare_dir)

    if export_path is not None:
        build_island()
        export_gltf(export_path)

    if preview_dir is not None:
        render_previews(preview_dir)

    if compare_dir is not None:
        render_compare(compare_dir)


if __name__ == "__main__":
    main()
